def calculate_average_song_length(playlist):
    total_seconds = 0
    for song in playlist:
        minutes, seconds = map(int, song.split(":"))
        total_seconds += minutes * 60 + seconds

    average_seconds = total_seconds / len(playlist)
    average_minutes = average_seconds // 60
    average_seconds_remainder = average_seconds % 60

    return round(average_minutes + average_seconds_remainder / 60, 2)

