fn triangle_area(side1: f64, side2: Option<f64>, side3: Option<f64>) -> f64 {
    match (side2, side3) {
        (None, None) => {
            // equilateral triangle
            // area = (sqrt(3)/4) * a^2
            (3f64.sqrt() / 4f64) * side1.powf(2f64)
        },
        (Some(side2), None) => {
            // isosceles triangle
            // area = 1/2 * base * height
            0.5 * side1 * side2
        },
        (Some(side2), Some(side3)) => {
            // scalene triangle
            // from the sides, get the semi-perimeter (s = (a+b+c)/2)
            // then plug it in Heron's formula: area = sqrt(s*(s-a)*(s-b)*(s-c))
            // which gives the formula for the area of a triangle from its sides
            let semi_perimeter = (side1 + side2 + side3) / 2f64;
            (semi_perimeter * (semi_perimeter-side1) * (semi_perimeter-side2) * (semi_perimeter-side3)).sqrt()
        },
        _ => panic!("Invalid arguments"),
    }
}
