from itertools import combinations


def largest_palindromic(numbers):
    products = set()
    n = len(numbers)
    # Generate products of all subsets with size at least 2
    for r in range(2, n + 1):
        for comb in combinations(numbers, r):
            prod = 1
            for num in comb:
                prod *= num
            products.add(prod)

    max_pal = 0
    # For every product, build the largest palindrome possible
    for p in products:
        freq = {}
        for d in str(p):
            freq[d] = freq.get(d, 0) + 1

        left = []  # left half of palindrome (as list of strings)
        for val in range(9, -1, -1):
            d = str(val)
            cnt = freq.get(d, 0)
            pairs = cnt // 2
            if pairs == 0:
                continue
            # avoid leading zero
            if d == '0' and not left:
                continue
            left.append(d * pairs)
            freq[d] -= 2 * pairs

        middle = ''
        for val in range(9, -1, -1):
            d = str(val)
            if freq.get(d, 0):
                middle = d
                break

        left_str = ''.join(left)
        palindrome_str = left_str + middle + left_str[::-1]
        current = int(palindrome_str) if palindrome_str else 0
        max_pal = max(max_pal, current)

    return max_pal


