def construct_array(A, B):
    C = []

    def F(x, y):
        if x % 2 == 0 and y % 2 == 1:
            return (x ** 2) * (y ** 2)
        elif x % 2 == 1 and y % 2 == 0:
            return x * y * (x + y)
        else:
            return x * y

    for i in range(len(A)):
