Here's an implementation in Python that uses a doubly-linked list. First, we define the `Node` class and the `DoublyLinkedList` class. Then, we implement the `shared_elements` function. This function iterates through `list1` and `list2`, creating a doubly-linked list for elements which exist in both lists. After that, it iterates through the list, counting the frequency of each element and storing the result in a dictionary. The function then converts the dictionary into a list of tuples and sorts it by the elements.

```Python
class Node:
    def __init__(self, item):
        self.item = item
        self.next = None
        self.prev = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def append(self, item):
        if self.head is None:
            new_node = Node(item)
            new_node.prev = None
            self.head = new_node
        else:
            new_node = Node(item)
            cur = self.head
            while cur.next:
                cur = cur.next
            cur.next = new_node
            new_node.prev = cur
            new_node.next = None

    def count(self, item):
        count = 0
        cur = self.head
        while cur:
            if cur.item == item:
                count += 1
            cur = cur.next
        return count

def shared_elements(list1, list2):
    dll = DoublyLinkedList()
    item_dict = {}
    result = []

    for item in list1:
        if item in list2 and dll.count(item) == 0:
            dll.append(item)

    cur = dll.head
    while cur:
        count = list1.count(cur.item) + list2.count(cur.item)
        item_dict[cur.item] = count
        cur = cur.next

    for item, count in item_dict.items():
        result.append((item, count))

    result.sort()
    return result

