import sys
def compute_z(s: str):
    n = len(s)
    if n == 0:
        return []
    Z = [0] * n
    Z[0] = n
    l = r = 0
    for i in range(1, n):
        if i <= r:
            Z[i] = min(r - i + 1, Z[i - l])
        while i + Z[i] < n and s[Z[i]] == s[i + Z[i]]:
            Z[i] += 1
        if i + Z[i] - 1 > r:
            l, r = i, i + Z[i] - 1
    return Z

def process_string(s: str) -> str:
    while True:
        Z = compute_z(s)
        max_z = 0
        for i in range(1, len(s)):
            if Z[i] > max_z:
                max_z = Z[i]
        if max_z == 0:
            break
        s = s[max_z:]
    return s

