def longest_common_subsequence(X, Y, Z, m, n, p):
    LCStable = [[[0 for k in range(p+1)] for j in range(n+1)] for i in range(m+1)]

    # Fill LCS table in bottom up manner
    for i in range(m+1):
        for j in range(n+1):
            for k in range(p+1):
                if (i == 0 or j == 0 or k == 0):
                    LCStable[i][j][k] = 0
