class Node:
    def __init__(self, value=0, next=None):
        self.value = value
        self.next = next

def build_linked_list(values):
    head = None
    prev = None
    for value in values:
        node = Node(value)
        if prev is None:
            head = node
        else:
            prev.next = node
        prev = node
    return head

def print_linked_list(head):
    cur = head
    output = []
    while cur:
        output.append(str(cur.value))
        cur = cur.next
    print(' '.join(output))

def reverse_linked_list(head):
    # Recursive in-place reversal
    if head is None or head.next is None:
        return head
    rest = reverse_linked_list(head.next)
    head.next.next = head
    head.next = None
    return rest

