import sys
import collections

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def serialize(root):
    if not root:
        return ""
    result = []
    q = collections.deque([root])
    while q:
        node = q.popleft()
        if node:
            result.append(str(node.val))
            q.append(node.left)
            q.append(node.right)
        else:
            result.append('null')
    while result and result[-1] == 'null':
        result.pop()
    return ','.join(result)

def deserialize(data):
    if not data:
        return None
    nodes = data.split(',')
    root = TreeNode(int(nodes[0]))
    q = collections.deque([root])
    index = 1
    while index < len(nodes):
        node = q.popleft()
        val = nodes[index]
        if val != 'null':
            left = TreeNode(int(val))
            node.left = left
            q.append(left)
        index += 1
        if index >= len(nodes):
            break
        val = nodes[index]
        if val != 'null':
            right = TreeNode(int(val))
            node.right = right
            q.append(right)
        index += 1
    return root

def main():
