    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        return None

    def peek(self):
        if not self.is_empty():
            return self.items[-1]
        return None

    def size(self):
        return len(self.items)

    def display(self):
        print(self.items)

    def reverse(self):
        start = 0
        end = len(self.items) - 1
        while start < end:
            self.items[start], self.items[end] = self.items[end], self.items[start]
            start += 1
            end -= 1

    def is_empty(self):
        return len(self.items) == 0

