import sys
from collections import deque

class Node:
    __slots__ = ("data", "left", "right")
    def __init__(self, val):
        self.data = val
        self.left = None
        self.right = None

def build_tree(tokens):
    if not tokens or tokens[0] == 'N':
        return None
    it = iter(tokens)
    root_val = next(it)
    root = Node(int(root_val))
    q = deque([root])
    for val in it:
        parent = q.popleft()
        # left child
        if val != 'N':
            left_node = Node(int(val))
            parent.left = left_node
            q.append(left_node)
        # right child: may still have more tokens
        try:
            val = next(it)
        except StopIteration:
            break
        if val != 'N':
            right_node = Node(int(val))
            parent.right = right_node
            q.append(right_node)
    return root

def leftLeavesSum(root):
    if not root:
        return 0
    stack = [(root, False)]  # (node, is_left_child)
    total = 0
    while stack:
        node, is_left = stack.pop()
        if is_left and node.left is None and node.right is None:
            total += node.data
        if node.right:
            stack.append((node.right, False))
        if node.left:
            stack.append((node.left, True))
    return total

