Tensor preprocess_image(const char* file_path) {
    // Load image using OpenCV
    Mat image = imread(file_path, IMREAD_UNCHANGED);

    // Convert to grayscale
    if (image.channels() >= 3) {
        cvtColor(image, image, COLOR_BGR2GRAY);
    }

    // Resize to 224x224
    Mat resized;
    resize(image, resized, Size(224, 224));

    // Normalize and convert to floating point format
    Mat normalized;
    resized.convertTo(normalized, CV_32FC1, 1.0/255);

    // Prepare tensor shape (1 batch, 224x224 size, 1 channel)
    Tensor tensor(DT_FLOAT, TensorShape({1, 224, 224, 1}));

    // Copy data to tensor - assuming column-major layout
    auto tensor_data = tensor.tensor<float, 4>();
    const float* src_data = reinterpret_cast<const float*>(normalized.data);

    for (int y = 0; y < 224; y++) {
        for (int x = 0; x < 224; x++) {
            tensor_data(0, y, x, 0) = src_data[y * 224 + x];
        }
    }

    return tensor;
}
