def recursive_extract(data, field_name):
    found_usernames = []
    if isinstance(data, dict):
        for key, value in data.items():
            if key == field_name:
                found_usernames.append(value)
            found_usernames.extend(recursive_extract(value, field_name))
    elif isinstance(data, list):
        for item in data:
            found_usernames.extend(recursive_extract(item, field_name))
    return found_usernames

