class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None
    def insert(self, value):
        if self.root is None:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)
    def _insert_recursively(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._insert_recursively(node.right, value)
    def in_order_traversal(self, node, result):
        if node is not None:
            self.in_order_traversal(node.left, result)
            result.append(str(node.value))
            self.in_order_traversal(node.right, result)
    def pre_order_traversal(self, node, result):
        if node is not None:
            result.append(str(node.value))
            self.pre_order_traversal(node.left, result)
            self.pre_order_traversal(node.right, result)
    def post_order_traversal(self, node, result):
        if node is not None:
            self.post_order_traversal(node.left, result)
            self.post_order_traversal(node.right, result)
            result.append(str(node.value))

def main():
    n = int(input())
    vals = [int(input()) for _ in range(n)]
    tree = BinaryTree()
    for v in vals:
        tree.insert(v)
    inorder, preorder, postorder = [], [], []
    tree.in_order_traversal(tree.root, inorder)
    tree.pre_order_traversal(tree.root, preorder)
    tree.post_order_traversal(tree.root, postorder)
    print(' '.join(inorder))
    print(' '.join(preorder))
    print(' '.join(postorder))

if __name__ == "__main__":
