        self.my_list = my_list if my_list is not None else []
        self.my_dict = my_dict if my_dict is not None else {}

def deep_copy(input_data):
    if isinstance(input_data, list):
        return [deep_copy(item) for item in input_data]
    elif isinstance(input_data, dict):
        return {key: deep_copy(value) for key, value in input_data.items()}
    elif isinstance(input_data, set):
        return {deep_copy(item) for item in input_data}
    elif isinstance(input_data, CustomObject):
        return CustomObject(deep_copy(input_data.my_list), deep_copy(input_data.my_dict))
    else:
        return copy.deepcopy(input_data)

