    import ast
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    objs = []
    is_custom = []
    for i in range(1, n+1):
        line = lines[i]
        if line.startswith('list '):
            val = ast.literal_eval(line[5:])
            objs.append(val)
            is_custom.append(False)
        elif line.startswith('dict '):
            val = ast.literal_eval(line[5:])
            objs.append(val)
            is_custom.append(False)
        elif line.startswith('set '):
            val = ast.literal_eval(line[4:])
            objs.append(val)
            is_custom.append(False)
        elif line.startswith('custom '):
            remain = line[7:].strip()
            # Find the first space separating the list and dict
            # The list might contain spaces, so look for the end of first bracket
            l_bracket = remain.index(']')
            lst_str = remain[:l_bracket+1]
            dict_str = remain[l_bracket+1:].strip()
            my_list = ast.literal_eval(lst_str)
            my_dict = ast.literal_eval(dict_str)
            co = CustomObject(my_list, my_dict)
