class Matrix:
    def __init__(self, data):
        if not data or not all(len(row) == len(data) for row in data):
            raise ValueError("Data must represent a square matrix.")
        self.data = data
        self.n = len(data)
    def __add__(self, other):
        if not isinstance(other, Matrix) or self.n != other.n:
            raise ValueError()
        return Matrix([[self.data[i][j] + other.data[i][j] for j in range(self.n)] for i in range(self.n)])
    def __sub__(self, other):
        if not isinstance(other, Matrix) or self.n != other.n:
            raise ValueError()
        return Matrix([[self.data[i][j] - other.data[i][j] for j in range(self.n)] for i in range(self.n)])
    def __mul__(self, other):
        if not isinstance(other, Matrix) or self.n != other.n:
            raise ValueError()
        n = self.n
        result = [[sum(self.data[i][k]*other.data[k][j] for k in range(n)) for j in range(n)] for i in range(n)]
        return Matrix(result)
    def hadamard_product(self, other):
        if not isinstance(other, Matrix) or self.n != other.n:
            raise ValueError()
        return Matrix([[self.data[i][j] * other.data[i][j] for j in range(self.n)] for i in range(self.n)])
    def __repr__(self):
        return '\n'.join(' '.join(map(str, row)) for row in self.data)

