def find_longest_increasing_subsequence(nums):
    if not nums:
        return []

    n = len(nums)
    dp = [1] * n
    prev = [-1] * n

    max_length = 1
    max_index = 0

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                prev[i] = j

        if dp[i] > max_length:
            max_length = dp[i]
            max_index = i

    subsequence = []
    while max_index != -1:
        subsequence.append(nums[max_index])
        max_index = prev[max_index]

    return subsequence[::-1]

