In its current state, the function can only handle positive integral exponents. It doesn't account for the special case where the base is zero. If the base is zero and the exponent is positive, the result should be zero. However, if the base is zero and the exponent is negative, this would lead to a division by zero error, which is not defined in mathematics.

 Here's the same code with required modifications to handle both positive and negative exponents, and to handle the possible edge case of the base being zero:

```javascript
function power(base, exponent) {
    // handle the special case where the base is zero
    if (base === 0) {
        // if the exponent is zero, return 1 (0 to the power of 0 equals 1)
        if (exponent === 0) return 1;
        // if the exponent is positive, return 0 (0 to the power of any positive number equals 0)
        if (exponent > 0) return 0;
        // if the exponent is negative, return Infinity (as per the mathematical convention)
        if (exponent < 0) return Infinity;
    }

    let result = 1;

    // check if the exponent is positive
    if (exponent > 0) {
        for (let count = 0; count < exponent; count++) {
            result *= base;
        }
    } else { 
        // if the exponent is negative, invert the base and change the exponent to positive
        let posExponent = -exponent;
        let invBase = 1 / base;
        for (let count = 0; count < posExponent; count++) {
            result *= invBase;
        }
    }

    return result;
}
