import json
import sys

def flatten_dict(d, parent_key='', sep='.', seen=None):
    if seen is None:
        seen = set()
    obj_id = id(d)
    if obj_id in seen:
        return {}
    if isinstance(d, dict):
        seen.add(obj_id)
    items = {}
    if isinstance(d, dict):
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(flatten_dict(v, new_key, sep, seen))
            elif isinstance(v, list):
                for i, element in enumerate(v):
                    element_key = f"{new_key}.{i}"
                    if isinstance(element, dict):
                        items.update(flatten_dict(element, element_key, sep, seen))
                    else:
                        items[element_key] = element
            else:
                items[new_key] = v
        seen.remove(obj_id)
    else:
        # For the rare case where the root of the JSON is a list
        if isinstance(d, list):
            for i, element in enumerate(d):
                element_key = f"{parent_key}.{i}" if parent_key else str(i)
                if isinstance(element, dict):
                    items.update(flatten_dict(element, element_key, sep, seen))
                else:
                    items[element_key] = element
    return items

def main():
    json_str = sys.stdin.read().strip()
    data = json.loads(json_str)
    flattened_data = flatten_dict(data)
