def precedence(op):
    if op in ('+', '-'):
        return 1
    if op in ('*', '/'):
        return 2
    return 0

def apply_operator(operators, values):
    operator = operators.pop()
    right = values.pop()
    left = values.pop()
    if operator == '+':
        values.append(left + right)
    elif operator == '-':
        values.append(left - right)
    elif operator == '*':
        values.append(left * right)
    elif operator == '/':
        values.append(left / right)

def greater_precedence(op1, op2):
    return precedence(op1) > precedence(op2)

def to_number(token):
    try:
        return float(token)
    except ValueError:
        return int(token)

def main():
    expression = input().strip()
    operators = []
    values = []
    i = 0
    n = len(expression)
    last_token = 'op'  # assume we start before any number; use to distinguish unary '-'
    while i < n:
        if expression[i] == ' ':
            i += 1
            continue

        if expression[i] in '0123456789.':
            j = i
            while j < n and (expression[j] in '0123456789.'):
                j += 1
            values.append(to_number(expression[i:j]))
            i = j
            last_token = 'num'
            continue

        if expression[i] == '-':
            # Negative number detection: If at start or after '(' or after an operator
            if last_token == 'op' or last_token == '(':  # unary minus
                j = i + 1
                while j < n and expression[j] == ' ':  # skip spaces after minus
                    j += 1
                k = j
                if k < n and (expression[k] in '0123456789.'):
                    while k < n and (expression[k] in '0123456789.'):
                        k += 1
                    values.append(-to_number(expression[j:k]))
                    i = k
                    last_token = 'num'
                    continue
            # Otherwise, this is a binary operator
        if expression[i] == '(':
            operators.append('(')
            last_token = '('
        elif expression[i] == ')':
            while operators and operators[-1] != '(':  
                apply_operator(operators, values)
            operators.pop()
            last_token = ')'
        elif expression[i] in '+-*/':
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])
            last_token = 'op'
        i += 1
    while operators:
        apply_operator(operators, values)
    print(float(values[0]))

