        self.value = value
        self.left = left
        self.right = right

def build_tree(n, nodes_data):
    if n == 0:
        return None
    nodes = {}
    for node_id, value, left_id, right_id in nodes_data:
        nodes[node_id] = TreeNode(value)
    for node_id, value, left_id, right_id in nodes_data:
        node = nodes[node_id]
        node.left = nodes[left_id] if left_id != -1 else None
        node.right = nodes[right_id] if right_id != -1 else None
    return nodes[0]

def inorder_traversal(root):
    result = []
    def traverse(node):
        if not node:
            return
        traverse(node.left)
        result.append(node.value)
        traverse(node.right)
    traverse(root)
    return result

