def build_tree_from_level_order(values):
    if not values or values[0] == 'null':
        return None
    root = TreeNode(int(values[0]))
    queue = [root]
    i = 1
    while i < len(values):
        current = queue.pop(0)
        if values[i] != 'null':
            current.left = TreeNode(int(values[i]))
            queue.append(current.left)
        i += 1
        if i < len(values) and values[i] != 'null':
            current.right = TreeNode(int(values[i]))
            queue.append(current.right)
        i += 1
    return root

def isBalanced(root):
    def check_balance(node):
        if not node:
            return 0, True
        left_height, left_balanced = check_balance(node.left)
        right_height, right_balanced = check_balance(node.right)
        current_height = max(left_height, right_height) + 1
        current_balanced = left_balanced and right_balanced and abs(left_height - right_height) <= 1
        return current_height, current_balanced
    _, balanced = check_balance(root)
    return balanced

