import re

def is_valid_email(email):
    # Split local and domain part
    if '@' not in email:
        return False
    local, domain = email.split('@', 1)
    # Local part rules:
    # - At least one hyphen
    # - No double underscores
    # - Only allowed chars
    if '-' not in local:
        return False
    if '__' in local:
        return False
    if not re.fullmatch(r'[A-Za-z0-9._-]+', local):
        return False
    # Domain rules:
    # - Starts with letter, then alphanum, ends with .edu or .org
    if not re.fullmatch(r'[A-Za-z][A-Za-z0-9]*\.(edu|org)', domain):
        return False
    return True

def main():
    n = int(input())
    emails = [input().strip() for _ in range(n)]
    for email in emails:
        if is_valid_email(email):
            print(email)

