def is_well_formed_html(html_string):
    def is_html_tag_closing(tag):
        return tag and tag[0] == '/'

    def extract_tag(html, start_index):
        end_index = start_index + 1
        while end_index < len(html) and html[end_index] != '>':
            end_index += 1
        return html[start_index + 1:end_index], end_index + 1

    stack = []
    index = 0
    while index < len(html_string):
        if html_string[index] == '<':
            tag, index = extract_tag(html_string, index)
            tag = tag.strip()
            if not tag:
                continue
            if is_html_tag_closing(tag):
                tag_name = tag[1:]
                if stack and stack[-1] == tag_name:
                    stack.pop()
                else:
                    return False
            elif tag[-1] == '/': # self-closing
                continue
            else:
                stack.append(tag)
        else:
            index += 1
    return len(stack) == 0

if __name__ == "__main__":
    html_string = input()
    print(is_well_formed_html(html_string))

