import ast
import operator

def main():
    n = int(input())
    variables = {}
    for _ in range(n):
        name, value = input().split()
        try:
            variables[name] = float(value) if '.' in value else int(value)
        except Exception:
            variables[name] = value
    expression = input()

    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv
    }

    def _eval(node):
        if isinstance(node, ast.Num):
            return node.n
        elif hasattr(ast, 'Constant') and isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            return operators[type(node.op)](left, right)
        elif isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            else:
                raise ValueError(f"Variable '{node.id}' not defined")
        elif isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return +operand
            else:
                raise SyntaxError("Unsupported operator")
        else:
            raise SyntaxError("Unsupported syntax")

    try:
        node = ast.parse(expression, mode='eval')
        result = _eval(node.body)
        if isinstance(result, float) and result.is_integer():
            print(int(result))
        else:
            print(result)
    except Exception as e:
        print(f"Error evaluating expression: {e}")

