class Library:
    def __init__(self):
        self.books = {}

    def add_book(self, title, genre):
        if title in self.books:
            print(f"The book '{title}' is already in the library.")
        else:
            self.books[title] = (genre, True)
            print(f"The book '{title}' was successfully added to the library.")

    def check_out_book(self, title):
        if title not in self.books:
            print(f"The book '{title}' is not available in the library.")
        else:
            genre, is_available = self.books[title]
            if is_available:
                self.books[title] = (genre, False)
                print(f"You have successfully checked out '{title}'.")
            else:
                print(f"Sorry, the book '{title}' is currently checked out.")

    def return_book(self, title):
        if title not in self.books:
            print(f"The book '{title}' does not belong to this library.")
        else:
            genre, is_available = self.books[title]
            if not is_available:
                self.books[title] = (genre, True)
                print(f"Thank you for returning '{title}'.")
            else:
                print(f"The book '{title}' was not checked out.")

    def search_books_by_genre(self, genre):
        Books_in_genre = [title for title, (bk_genre, _) in self.books.items() if bk_genre == genre]
        if Books_in_genre:
            print(f"Books in the genre '{genre}': {', '.join(Books_in_genre)}.")
        else:
            print(f"No books found in the genre '{genre}'.")

def main():
    library = Library()
    while True:
        try:
            command = input()
        except EOFError:
            break
        if not command:
            continue
        parts = command.strip().split()
        if not parts:
            continue
        action = parts[0]
        if action == 'ADD' and len(parts) == 3:
            _, title, genre = parts
            library.add_book(title, genre)
        elif action == 'CHECKOUT' and len(parts) == 2:
            _, title = parts
            library.check_out_book(title)
        elif action == 'RETURN' and len(parts) == 2:
            _, title = parts
            library.return_book(title)
        elif action == 'SEARCH' and len(parts) == 2:
            _, genre = parts
            library.search_books_by_genre(genre)
        elif action == 'EXIT':
