    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2)

    def is_operator(c):
        return c in "+-*/"

    def is_digit(c):
        return c.isdigit() or c == '.'

    expression = expression.replace(" ", "")
    operators = []
    values = []
    i = 0
    n = len(expression)
    while i < n:
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] == '(':  # left paren
            operators.append('(')
            i += 1
        elif expression[i] == ')':
            while operators and operators[-1] != '(':  # pop till '('
                apply_operator(operators, values)
            operators.pop()  # remove '(' from stack
            i += 1
        elif expression[i] in '+-*/':
            # handle unary minus (negative numbers)
            if expression[i] == '-' and (i == 0 or expression[i-1] in '+-*/('):
                # get negative number
                j = i + 1
                while j < n and (expression[j].isdigit() or expression[j] == '.'):
                    j += 1
                num = float(expression[i:j])
                values.append(num)
                i = j
            else:
                while (operators and operators[-1] != '(' and precedence(operators[-1]) >= precedence(expression[i])):
                    apply_operator(operators, values)
                operators.append(expression[i])
                i += 1
        elif expression[i].isdigit() or expression[i] == '.':
            j = i
            while j < n and (expression[j].isdigit() or expression[j] == '.'):
                j += 1
            num = float(expression[i:j])
            values.append(num)
            i = j
        else:
            i += 1  # skip any unhandled char
    while operators:
        apply_operator(operators, values)
    return values[0]

def main():
    expression = input()
    result = evaluate_expression(expression)
    print(result)

if __name__ == "__main__":
    main()

