def sum_of_primes(start: int, end: int) -> int:
    """
    Return the sum of all prime numbers in the inclusive range [start, end].
    If the range contains no primes, 0 is returned.
    """

    # Handle the possibility that start > end by swapping
    if start > end:
        start, end = end, start

    # Helper function to test primality
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        # Check potential factors of form 6k±1 up to sqrt(n)
        i = 5
        step = 2
        while i * i <= n:
            if n % i == 0:
                return False
            i += step
            # Toggle step between 2 and 4 to cover 6k±1 sequence
            step = 6 - step
        return True

    total = 0
    for num in range(max(2, start), end + 1):
        if is_prime(num):
            total += num

    return total

