from hashlib import sha256
import sys
import sympy

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(level_order):
    if not level_order or level_order[0] == 'null':
        return None
    nodes = [TreeNode(int(val)) if val != 'null' else None for val in level_order]
    kids = nodes[1:]
    i = 0
    for node in nodes:
        if node:
            if kids: node.left = kids.pop(0)
            if kids: node.right = kids.pop(0)
    return nodes[0]

def custom_hash(value, depth):
    hash_val = sha256((str(value) + str(depth)).encode()).hexdigest()
    num = int(hash_val, 16)
    return sympy.nextprime(num)

def traverse_tree(node, depth, prime_map):
    if node is None:
        return
    prime = custom_hash(node.val, depth)
    if depth not in prime_map:
        prime_map[depth] = []
    prime_map[depth].append(prime)
    traverse_tree(node.left, depth + 1, prime_map)
    traverse_tree(node.right, depth + 1, prime_map)

