    p_values = lines[0].split()
    q_values = lines[1].split()
    p = build_tree(p_values)
    q = build_tree(q_values)
    prime_map_p = {}
    prime_map_q = {}
    traverse_tree(p, 0, prime_map_p)
    traverse_tree(q, 0, prime_map_q)
    if prime_map_p == prime_map_q:
        print("True")
    else:
