import sys
from collections import deque

class Node:
    __slots__ = ("data", "left", "right")
    def __init__(self, val):
        self.data = val
        self.left = None
        self.right = None

def build_tree(level_vals):
    if not level_vals or level_vals[0] == 'N':
        return None
    root = Node(int(level_vals[0]))
    q = deque([root])
    i = 1
    n = len(level_vals)
    while q and i < n:
        current = q.popleft()
        # left child
        if level_vals[i] != 'N':
            current.left = Node(int(level_vals[i]))
            q.append(current.left)
        i += 1
        if i >= n:
            break
        # right child
        if level_vals[i] != 'N':
            current.right = Node(int(level_vals[i]))
            q.append(current.right)
        i += 1
    return root

def children_sum_property(root):
    if not root:
        return 1
    q = deque([root])
    while q:
        node = q.popleft()
        # skip leaves
        if not node.left and not node.right:
            continue
        child_sum = 0
        if node.left:
            child_sum += node.left.data
            q.append(node.left)
        if node.right:
            child_sum += node.right.data
            q.append(node.right)
        if node.data != child_sum:
            return 0
    return 1

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    t = int(data[0].strip())
    outputs = []
    for idx in range(1, t+1):
        tokens = data[idx].strip().split()
        root = build_tree(tokens)
        outputs.append(str(children_sum_property(root)))
    sys.stdout.write("\n".join(outputs))

