```rust
pub fn pluck(tree_branch_values: &[i32], condition: impl Fn(i32) -> bool, minimum_limit: i32) -> Vec<i32> {
    if tree_branch_values.is_empty() {
        return Vec::new();
    }

    let mut min_candidate = None; // Tracks the smallest eligible value and its position
    let mut found = false; // Tracks if any l elements meet the criteria

    for (index, &val) in tree_branch_values.iter().enumerate() {
        if condition(val) && val >= minimum_limit {
            match min_candidate {
                None => {
                    min_candidate = Some((val, index));
                    found = true;
                }
                Some((current_val, _current_idx)) if val < current_val => {
                    min_candidate = Some((val, index));
                }
                _ => {}
            }
        }
    }

    if found {
        let (val, idx) = min_candidate.unwrap();
        vec![val, idx as i32]
    } else {
        Vec::new()
    }
}
```

