    /**
     * Runs through all numbers till the square root of the input number n to find prime factors.
     * Counts the instances of prime digits and composite digits in the prime factors.
     * Prime digits are 2, 3, 5, 7 and composite digits are 4, 6, 8, 9.
     * @param n The input number.
     * @return The count of prime digits and composite digits
     */
    public int[] primeFactorCompositeCount(int n) {
        int[] count = new int[]{0, 0};
        n = Math.abs(n);

        for (int i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                countDigitsOfPrimeFactor(i, count);
                n /= i;
            }
        }

        if (n > 1) {
            countDigitsOfPrimeFactor(n, count);
        }

        return count;
    }

    /**
     * Converts the prime factor into a string and iterates over each digit.
     * Increments the corresponding count of prime or composite digits.
     * @param primeFactor The prime factor.
     * @param count The array tracking prime and composite digit counts.
     */
    public void countDigitsOfPrimeFactor(int primeFactor, int[] count) {
        String digitsOfPrimeFactor = Integer.toString(primeFactor);
        for (char digit : digitsOfPrimeFactor.toCharArray()) {
            switch (digit) {
                case '2':
                case '3':
                case '5':
                case '7':
                    count[0]++; //increment the prime digit count
                    break;
                case '4':
                case '6':
                case '8':
                case '9':
                    count[1]++; //increment the composite digit count
                    break;
            }
        }
    }
}
