def is_dynamic(s: str) -> bool:
    # Frequency of each character
    freq = sorted(Counter(s).values())
    n = len(freq)

    # Fewer than 3 distinct characters => always dynamic
    if n < 3:
        return True

    # Helper to verify Fibonacci property on a list
    def check(lst):
        for i in range(2, len(lst)):
            if lst[i] != lst[i - 1] + lst[i - 2]:
                return False
        return True

    # Two possible ways: sorted order or first two swapped
    if check(freq):
        return True

    freq[0], freq[1] = freq[1], freq[0]
    return check(freq)


