def traverse_dict(d, path=None, out=None):
    if path is None:
        path = []
    if out is None:
        out = {}

    for k, v in d.items():
        new_path = path + [k]
        if isinstance(v, dict):
            traverse_dict(v, new_path, out)
        elif isinstance(v, (int, float)):
            out['.'.join(new_path)] = v

    return out

