    result = []
    in_quotes = False
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '"':
            result.append(c)
            in_quotes = not in_quotes
            i += 1
        elif in_quotes:
            result.append(c)
            if c == '\\' and i+1 < n and s[i+1] == '"':
                # Escaped quote inside quoted string
                result.append(s[i+1])
                i += 1
            i += 1
        else:
            if c.isalnum() or c.isspace():
                result.append(c)
            i += 1
    return ''.join(result)

