def longest_palindrome(s):
    from collections import Counter
    s = s.lower()
    char_count = Counter(s)
    result = []
    extra_char = ''
    # Build half string
    for char in sorted(char_count.keys()):
        count = char_count[char]
        result.append(char * (count // 2))
        if count % 2 == 1 and not extra_char:
            extra_char = char
    half = ''.join(result)
    return half + extra_char + half[::-1]

def is_palindrome(s):
    s = s.lower()
    return s == s[::-1]

