import functools

def log_execution_time(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        execution_time = end_time - start_time
        print(f"Executing {func.__name__} with args {args} and kwargs {kwargs} took {execution_time:.4f} seconds")
        return result
    return wrapper

