```python
def optimize_arrangement(lst):
    index = -1
    swap_with = -1
    total_swaps = 0
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            index = i
            swap_with = i + 1
            total_swaps += 1
            lst[i], lst[i + 1] = lst[i + 1], lst[i]
            return {'index': index, 'swap_with': swap_with, 'total_swaps': total_swaps}
    return {'index': -1, 'swap_with': -1, 'total_swaps': 0}

