```python
def calculate_weighted_sum(element, weights):
    if isinstance(element, int) or isinstance(element, str):
        return len(str(element)) * weights[type(element)]
    elif isinstance(element, list):
        return sum(calculate_weighted_sum(sub_element, weights) for sub_element in element)
    elif isinstance(element, dict):
        return sum(calculate_weighted_sum(k, weights) + calculate_weighted_sum(v, weights) for k, v in element.items())
    elif isinstance(element, set):
        return sum(calculate_weighted_sum(x, weights) for x in element)
    else:
        return 0

def complex_sort(input_data, n, weights=None):
    if weights is None:
        weights = {int: 1, str: 2, list: 3, dict: 4, set: 5}

    if isinstance(input_data, dict):
        lst = [item for sublist in input_data.values() for item in sublist]
    elif isinstance(input_data, (list, tuple)):
        lst = [item for sublist in input_data for item in sublist]
    else:
        raise TypeError("Unsupported data type for input_data")

    if not 0 <= n < len(lst):
        raise ValueError("Invalid index")

    first_part = lst[:n]
    second_part = lst[n:]
    lst = second_part + first_part

    lst.sort(key=lambda x: calculate_weighted_sum(x, weights))

    return lst
