class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class DoublyLinkedListNode:
    def __init__(self, val=0, prev=None, next=None):
        self.val = val
        self.prev = prev
        self.next = next

def build_tree(node_descriptions):
    n = len(node_descriptions)
    nodes = [None] + [TreeNode(val=desc[0]) for desc in node_descriptions]
    for i, (val, l, r) in enumerate(node_descriptions, 1):
        if l != 0:
            nodes[i].left = nodes[l]
        if r != 0:
            nodes[i].right = nodes[r]
    return nodes[1]  # root

def reverse_inorder_to_doubly_linked_list(root):
    prev_node = None
    head = None
    def convert(node):
        nonlocal prev_node, head
        if not node:
            return
        convert(node.right)
        current_dll_node = DoublyLinkedListNode(node.val)
        if prev_node is None:
            head = current_dll_node
        else:
            current_dll_node.prev = prev_node
            prev_node.next = current_dll_node
        prev_node = current_dll_node
        convert(node.left)
    convert(root)
    return head

def main():
    import sys
    sys.setrecursionlimit(2000)
    n = int(sys.stdin.readline())
    node_descriptions = []
    for _ in range(n):
        vals = list(map(int, sys.stdin.readline().split()))
        node_descriptions.append(tuple(vals))
    root = build_tree(node_descriptions)
    head = reverse_inorder_to_doubly_linked_list(root)
    res = []
    cur = head
    while cur:
        res.append(str(cur.val))
        cur = cur.next
