import sys
import json

def main():
    # Read the input
    data = sys.stdin.read()
    data = json.loads(data)

    name_keys = {'name', 'first name', 'last name', 'fullname'}
    email_keys = {'email', 'e-mail', 'contact email'}

    names = set()
    emails = set()
    seen = set()

    def search(obj):
        # To prevent infinite loops due to circular references
        if isinstance(obj, (dict, list)):
            key_obj = id(obj)
            if key_obj in seen:
                return
            seen.add(key_obj)
        if isinstance(obj, dict):
            for key, value in obj.items():
                lower_key = key.lower()
                if lower_key in name_keys:
                    if isinstance(value, str):
                        names.add(value)
                elif lower_key in email_keys:
                    if isinstance(value, str):
                        emails.add(value)
                # Continue recursion
                search(value)
        elif isinstance(obj, list):
            for item in obj:
                search(item)

    search(data)

    for name in sorted(names):
        print(name)
    print('---')
    for email in sorted(emails):
        print(email)

