        self.right = None

    def is_balanced(self):
        return self._is_balanced_helper()[0]

    def _is_balanced_helper(self):
        left_is_balanced, left_height = self.left._is_balanced_helper() if self.left else (True, -1)
        if not left_is_balanced:
            return False, 0
        right_is_balanced, right_height = self.right._is_balanced_helper() if self.right else (True, -1)
        if not right_is_balanced:
