        if done:
            for u in g[v]:
                if u != parent[v]:
                    size[v] += size[u]
            continue
        if vis[v]:
            continue
        vis[v] = True
        stack.append((v, True))
        for u in g[v]:
            if not vis[u]:
                parent[u] = v
                stack.append((u, False))

    # pre-compute powers of 2 and their inverses up to n
    pow2 = [1]*(n+1)
    for i in range(1, n+1):
        pow2[i] = pow2[i-1]*2 % MOD
    inv2 = pow(2, MOD-2, MOD)
    inv_pow2 = [1]*(n+1)
    for i in range(1, n+1):
        inv_pow2[i] = inv_pow2[i-1]*inv2 % MOD

    ans = 0
    for v in range(1, n+1):
        comps = []                      # sizes of connected components of T \ {v}
        if parent[v] == -1:             # v is root
            for u in g[v]:
                if parent[u] == v:
                    comps.append(size[u])
        else:
            comps.append(n - size[v])   # component containing the root
            for u in g[v]:
                if u != parent[v] and parent[u] == v:
                    comps.append(size[u])

        # probability that all components are empty of black vertices
        prod_p = 1
        sum_t  = 0
        for s in comps:
            prod_p = prod_p * inv_pow2[s] % MOD          # (1/2)^s
            sum_t  = (sum_t + pow2[s] - 1) % MOD         # 2^s - 1

        part = prod_p * (sum_t + 1) % MOD                # probability ≤ 1 component has black
        ev   = (1 - part) % MOD                         # probability ≥ 2 components have black
        ev   = ev * inv2 % MOD                          # multiply by P(v is white) = 1/2
        ans  = (ans + ev) % MOD

