```javascript
/**
 * This function calculates and returns the greatest common divisor of two given integers 
 *
 * @param {Number} x - The first integer 
 * @param {Number} y - The second integer
 * @return {Number} - The greatest common divisor of the two integers
 */
function greatestCommonDivisor(x, y) {
    // The while loop continues until y becomes zero
    while (y) {
        // Inside the loop, we assign y to x and the remainder of x/y to y
        // This operation is based on the mathematical principle for GCD: GCD(x, y) = GCD(y, x mod y)
