import sys
import re

def parse_args(args):
    args_list = []
    temp_arg = ''
    in_quotes = False
    for char in args:
        if char == '"':
            in_quotes = not in_quotes
        elif char == ',' and not in_quotes:
            args_list.append(temp_arg)
            temp_arg = ''
        else:
            temp_arg += char
    args_list.append(temp_arg)

    ordered_dict = OrderedDict()
    i = 0
    while i < len(args_list):
        # Spaces not allowed unless quoted
        if ' ' in args_list[i] and not (args_list[i].startswith('"') and args_list[i].endswith('"')):
            raise ValueError("Invalid input: Spaces must be enclosed in quotes")
        if args_list[i].startswith('"') and args_list[i].endswith('"'):
            args_list[i] = args_list[i][1:-1]
        if args_list[i].startswith('_'):
            key = args_list[i][1:]
            if not re.match('^[a-zA-Z]', key):
                raise ValueError("Invalid input: Flag '{}' contains a special character or a digit as its first character".format(key))
            if i + 1 >= len(args_list):
                raise ValueError("Invalid input: No value provided for flag '{}'".format(key))
            value = args_list[i+1]
            # No explicit value check here, since values can be any alphanumeric or quoted with spaces
            ordered_dict[key] = value
            i += 2
        else:
            raise ValueError("Invalid input: '{}' is not a valid flag".format(args_list[i]))
    if len(ordered_dict) != len(args_list) // 2:
        raise ValueError("Invalid input: The number of flags and values are not equal")
    return ordered_dict

