import math
from typing import List

def find_primes(numbers: List[int]) -> List[int]:
    """
    Return a list containing all prime numbers found in `numbers`.
    Duplicates are preserved and negatives / non-primes are ignored.
    """

    def is_prime(n: int) -> bool:
        """Check if `n` is a prime number."""
        if n <= 1:
            return False
        if n <= 3:
            return True  # 2 and 3 are prime
        if n % 2 == 0:
            return False
        limit = int(math.isqrt(n)) + 1
        for factor in range(3, limit, 2):
            if n % factor == 0:
                return False
        return True

    return [num for num in numbers if is_prime(num)]

