def stable_sort_books(books):
    # Insertion Sort (stable)
    for i in range(1, len(books)):
        key_book = books[i]
        j = i - 1
        while j >= 0 and books[j]['publication_year'] > key_book['publication_year']:
            books[j + 1] = books[j]
            j -= 1
        books[j + 1] = key_book
    return books

