def is_palindrome(s):
    def is_alphanumeric(c):
        # Simple check: only ASCII letters and digits
        return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9')
    def to_lowercase(c):
        # Simple conversion for ASCII
        if 'A' <= c <= 'Z':
            return chr(ord(c) + (ord('a') - ord('A')))
        return c
    left, right = 0, len(s) - 1
    while left < right:
        while left < right and not is_alphanumeric(s[left]):
            left += 1
        while left < right and not is_alphanumeric(s[right]):
            right -= 1
        if left < right:
            if to_lowercase(s[left]) != to_lowercase(s[right]):
                return False
            left += 1
            right -= 1
    return True

