    str1 = input().strip()
    str2 = input().strip()
    prime_positions = [is_prime(i) for i in range(256)]
    m, n = len(str1), len(str2)
    # dp[i][j][k]: length of LCS till str1[0:i], str2[0:j], state k
    # k=0: next should be prime, k=1: next should be non-prime
    dp = [[[0]*2 for _ in range(n+1)] for _ in range(m+1)]
    for i in range(1, m+1):
        for j in range(1, n+1):
            for k in range(2):
                # Take previous value if not using str1[i-1] == str2[j-1]
                dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k], dp[i][j-1][k])
            if str1[i-1] == str2[j-1]:
                ascii_val = ord(str1[i-1])
                # if k==0 we need a prime, k==1 need non-prime
