In the Rust language, we recreate the functionality of the Python code as follows:

```rust
pub fn custom_mix_strings(s1: &str, s2: &str) -> String {
    let mut s1_chars = s1.chars().collect::<Vec<_>>();
    let mut s2_chars = s2.chars().collect::<Vec<_>>();
    s1_chars.reverse();
    s2_chars.reverse();
    let mut first_counter = 0;
    let mut second_counter = 0;
    let mut result = String::new();

    loop {
        while first_counter < s1.len() && !s1_chars[first_counter].is_alphabetic() {
            first_counter += 1;
        }
        if first_counter < s1.len() {
            result.push(s1_chars[first_counter].to_ascii_lowercase());
            first_counter += 1;
        }

        while second_counter < s2.len() && !s2_chars[second_counter].is_alphabetic() {
            second_counter += 1;
        }
        if second_counter < s2.len() {
            result.push(s2_chars[second_counter].to_ascii_lowercase());
            second_counter += 1;
        }

        if first_counter >= s1.len() && second_counter >= s2.len() {
            break;
        }
    }

    result.chars().collect::<String>()
}
