def levenshtein_distance_recursive(str1, str2):
    str1 = str1.lower()
    str2 = str2.lower()
    if len(str1) == 0:
        return len(str2)
    if len(str2) == 0:
        return len(str1)
    if str1[0] == str2[0]:
        return levenshtein_distance_recursive(str1[1:], str2[1:])
    else:
        insert_cost = levenshtein_distance_recursive(str1, str2[1:]) + 1
        delete_cost = levenshtein_distance_recursive(str1[1:], str2) + 1
        replace_cost = levenshtein_distance_recursive(str1[1:], str2[1:]) + 1
        return min(insert_cost, delete_cost, replace_cost)

