def encode(word: str) -> str:
    vowels = {'a', 'e', 'i', 'o', 'u'}
    groups = []            # consecutive groups of vowels / consonants
    cur = []
    cur_type = None        # 'vowel' or 'consonant'

    for ch in word:
        is_vowel = ch.lower() in vowels
        t = 'vowel' if is_vowel else 'consonant'
        if cur_type is None or t == cur_type:
            cur.append(ch)
            cur_type = t
        else:
            groups.append(''.join(cur))
            cur = [ch]
            cur_type = t
    if cur:
        groups.append(''.join(cur))

    out = []
    for i, g in enumerate(groups):
        out.append(g)
        if g[0].lower() in vowels and i != len(groups) - 1:
            out.append('ka')

    return 'ka' + ''.join(out)

