def get_divisors(n):
    i = 1
    divisors = []
    while(i <= n):
        if (n % i == 0):
            divisors.append(i)
        i = i + 1
    return divisors

def calc_weighted_avg(n, nn):
    tot_sum = 0
    tot_counts = 0
    for i in range(n, nn + 1):
        divs = get_divisors(i)
        tot_counts += len(divs)
        tot_sum += i * len(divs)
    return round(tot_sum / tot_counts)

def seq_summation(mean, cnt):
    return ((cnt * (2 * mean + (cnt - 1))) // 2)

def to_custom_base(summation, base):
    if base == 10:
        return str(summation)
    elif base < 10 and base >= 2:
        return decode_base(summation, base)
    else:
        return -1

def decode_base(num, base):
    digits = "0123456789ABCDEF"

    ret = ''
    while num > 0:
        num, remainder = divmod(num, base)
        ret = digits[remainder] + ret
    return "0b" + ret if base == 2 else "0o" + ret

def calc_weighted_avg_custom_base(n, m, base):
    if n > m or base < 2 or base > 10:
        return -1
    mean = calc_weighted_avg(n, m)
    summation = seq_summation(mean, m-n+1)
    return to_custom_base(summation, base)
