def find_smallest_index(arr, target):
    def find_rotation_point(arr):
        left, right = 0, len(arr) - 1
        while left < right:
            mid = (left + right) // 2
            if arr[mid] > arr[right]:
                left = mid + 1
            elif arr[mid] < arr[right]:
                right = mid
            else:
                # When duplicates, can't be sure, reduce right
                right -= 1
        return left

    def binary_search(arr, left, right, target):
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                result = mid
                right = mid - 1
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    n = len(arr)
    if n == 0:
        return -1

    rotation_index = find_rotation_point(arr)

    ans1 = binary_search(arr, 0, rotation_index - 1, target)
    ans2 = binary_search(arr, rotation_index, n - 1, target)
    if ans1 == -1 and ans2 == -1:
        return -1
    if ans1 == -1:
        return ans2
    if ans2 == -1:
        return ans1
    return min(ans1, ans2)

