def is_prime(n):
    if n < 2:
        return False
    if n & 1 == 0:  # Checks if n is even
        return n == 2
    d = 3
    while d * d <= n:
        # Approximate replacement for modulo using subtraction and multiplication
        tmp = n
        while tmp >= d:
            tmp = tmp - d
        if tmp == 0:
            return False
        d += 2
    return True

