class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node
        new_node.prev = last

    def length(self):
        count = 0
        current = self.head
        while current:
            count += 1
            current = current.next
        return count

    def binary_search_recursive(self, key, left, right):
        if right < left:
            return -1
        mid_index = (left + right) // 2
        mid_node = self.get_node_at_index(mid_index)
        if mid_node.data == key:
            return mid_index
        elif key < mid_node.data:
            return self.binary_search_recursive(key, left, mid_index - 1)
        else:
            return self.binary_search_recursive(key, mid_index + 1, right)

    def get_node_at_index(self, index):
        current = self.head
        for _ in range(index):
            current = current.next
        return current

