import math

def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n-1)

def fibonacci(n):
    a, b = 0, 1
    fibonacci_sequence = [0]
    while b <= n:
        fibonacci_sequence.append(b)
        a, b = b, a+b
    return fibonacci_sequence

def process_numbers(numbers):
    result = []
    for number in numbers:
        if number == 0:
            result.append(("undefined operation", 0))
        elif number % 2 == 0:
            result.append(("Even", fibonacci(int(number))))
        else:
            result.append(("Odd", factorial(int(number))))
    return result

numbers = [int(i) for i in input("Please enter the numbers (space separated): ").split()]
