Here's a C++ class design that implies an augmented doubly-linked list with hash map for enhancing search operation efficiency. 

```cpp
#include <iostream>
#include <unordered_map>
using namespace std;

class Node {
public:
    int val;
    Node* prev;
    Node* next;
    Node(int val) : val(val), prev(nullptr), next(nullptr) {}
};

class DoublyLinkedList {
private:
    unordered_map<int, Node*> map;
    Node* head;
    Node* tail;

public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    void insert(int val) {
        Node* node = new Node(val);

        if (head == nullptr) {
            head = tail = node;
        }
        else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }

        map[val] = node;
    }

    bool search(int val) {
        return (map.find(val) != map.end());
    }

    void display() {
        Node* temp = head;
        while (temp != nullptr) {
            cout << temp->val << " ";
            temp = temp->next;
        }
        cout << endl;
    }

    ~DoublyLinkedList(){
        while (head)
        {
            Node* old = head;
            head = head->next;
            delete old;
        }
    }
};
```

In this class `DoublyLinkedList`, we use doubly-linked list to store values. To improve the searching efficiency, we use a hash map where the value is the key and the `Node*` is the stored value. The advantage is that the search time complexity can be reduced to O(1) (the average time complexity of retrieving an item from a hash map).

Objects of type `Node` contain the integer value, and pointers to the previous and next nodes. If a node is the first node in the list, `prev` will be `nullptr`. Similarly, if a node is the last one, `next` will be `nullptr`.

Please note that in reality, you would also have to include deletion mechanisms and handle cases when same value is inserted multiple times which may cause issues with hash map, depending on your use case.

