def read_linked_list():
    N = int(input())
    values = []
    next_indices = []
    for _ in range(N):
        v, p = map(int, input().split())
        values.append(v)
        next_indices.append(p)
    # Create nodes
    nodes = [ListNode(values[i]) for i in range(N)]
    # Set .next pointers
    for i in range(N):
        if next_indices[i] == 0:
            nodes[i].next = None
        else:
            nodes[i].next = nodes[next_indices[i]-1]
    head = nodes[0]
    return head

def detect_cycle(head):
    slow = head
    fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            # Cycle detected. Find entry.
            ptr1 = head
            ptr2 = slow
            while ptr1 != ptr2:
                ptr1 = ptr1.next
                ptr2 = ptr2.next
            return ptr1
    return None

