class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def build_tree_from_level_order(values):
    if not values or values[0] == 'null':
        return None
    root = TreeNode(int(values[0]))
    queue = [root]
    i = 1
    n = len(values)
    while queue and i < n:
        node = queue.pop(0)
        if i < n and values[i] != 'null':
            node.left = TreeNode(int(values[i]))
            queue.append(node.left)
        i += 1
        if i < n and values[i] != 'null':
            node.right = TreeNode(int(values[i]))
            queue.append(node.right)
        i += 1
    return root

def post_order_traversal(root):
    if not root:
        return []
    return post_order_traversal(root.left) + post_order_traversal(root.right) + [root.value]

def main():
    N = int(input())
    level_values = input().split()
    root = build_tree_from_level_order(level_values)
    result = post_order_traversal(root)
    print(' '.join(str(x) for x in result))

