def flatten_json(y, name='', out=None, seen=None):
    if out is None:
        out = {}
    if seen is None:
        seen = set()
    if id(y) in seen:
        out[name[:-1]] = '[Circular Reference]'
        return out
    seen.add(id(y))
    if isinstance(y, dict):
        for a in y:
            flatten_json(y[a], name + a + '.', out, seen)
    elif isinstance(y, list):
        for i, a in enumerate(y):
            flatten_json(a, name + str(i) + '.', out, seen)
    else:
        out[name[:-1]] = y
    seen.remove(id(y))
    return out

