import sys
import heapq

def read_graph():
    n = int(input())
    graph = {}
    for _ in range(n):
        line = input().strip()
        if not line:
            continue
        parts = line.split(':')
        node = parts[0].strip()
        edges = {}
        if len(parts) > 1 and parts[1].strip():
            for pair in parts[1].strip().split():
                if '=' in pair:
                    neighbor, weight = pair.split('=')
                    edges[neighbor.strip()] = int(weight.strip())
        graph[node] = edges
    start, end = input().strip().split()
    return graph, start, end

def dijkstra(graph, start, end):
    heap = [(0, start, [start])]
    best = {start: 0}
    while heap:
        dist, node, path = heapq.heappop(heap)
        if node == end:
            return path, dist
        for neighbor in graph.get(node, {}):
            d = dist + graph[node][neighbor]
            if neighbor not in best or d < best[neighbor]:
                best[neighbor] = d
                heapq.heappush(heap, (d, neighbor, path + [neighbor]))
    return None, 0

def main():
    graph, start, end = read_graph()
    path, dist = dijkstra(graph, start, end)
    if path is None:
        print('No path')
        print(0)
    else:
        print(' '.join(path))
        print(dist)

