def prime_factors(n):
    factors = []
    # Check for factor 2
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    factor = 3
    max_check = int(n ** (1/3)) + 1
    while factor <= max_check:
        extracted = False
        while n % factor == 0:
            extracted = True
            factors.append(factor)
            n //= factor
        factor += 2
        if extracted:
            max_check = int(n ** (1/3)) + 1
    if n > 2:
        factors.append(n)
    return factors if len(factors) > 1 else [n]

