def roman_to_int(s):
    roman_dict = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    valid_subtraction = {
        'IV': 4, 'IX': 9,
        'XL': 40, 'XC': 90,
        'CD': 400, 'CM': 900
    }
    # Validate characters
    for char in s:
        if char not in roman_dict:
            return 0
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in valid_subtraction:
            total += valid_subtraction[s[i:i+2]]
            i += 2
        elif s[i] in roman_dict:
            # Subtraction-like but invalid patterns
            if i + 1 < len(s) and roman_dict[s[i]] < roman_dict[s[i+1]]:
                return 0
            total += roman_dict[s[i]]
            i += 1
        else:
            return 0
    if 1 <= total <= 3999:
        return total
    else:
        return -1

