def sum_of_primes_below(limit):
    is_prime = [True] * limit
    if limit > 0:
        is_prime[0] = False
    if limit > 1:
        is_prime[1] = False
    p = 2
    while p * p < limit:
        if is_prime[p]:
            for i in range(p * p, limit, p):
                is_prime[i] = False
        p += 1
    sum_primes = 0
    for p in range(2, limit):
        if is_prime[p]:
            sum_primes += p
    return sum_primes

