def find_zero_index(arr):
    left = 0          # left edge of current window (with at most one zero)
    last_zero = -1    # index of the single zero inside the window
    max_len = 0       # best window length found so far
    best_index = -1   # index of zero giving that best window

    for right in range(len(arr)):
        if arr[right] == 0:
            # move window so that it contains at most one zero – the current one
            if last_zero != -1:
                left = last_zero + 1
            last_zero = right

        current_len = right - left + 1

        if current_len > max_len:
            max_len = current_len
            best_index = last_zero
        elif current_len == max_len:
            if last_zero > best_index:
                best_index = last_zero

    return best_index


