import random

def cmp(a, b):
    if a < b: return -1
    elif a == b: return 0
    else: return 1

def partition(lst, left, right, pivot_index, cmp_func):
    pivot_value = lst[pivot_index]
    lst[pivot_index], lst[right] = lst[right], lst[pivot_index]
    store_index = left
    for i in range(left, right):
        if cmp_func(lst[i], pivot_value) < 0:
            lst[i], lst[store_index] = lst[store_index], lst[i]
            store_index += 1
    lst[right], lst[store_index] = lst[store_index], lst[right]
    return store_index

def _select(lst, left, right, k, cmp_func):
    if left == right: return lst[left]
    pivot_index = random.randint(left, right)
    pivot_index = partition(lst, left, right, pivot_index, cmp_func)
    if k == pivot_index: return lst[k]
    elif k < pivot_index: return _select(lst, left, pivot_index - 1, k, cmp_func)
    else: return _select(lst, pivot_index + 1, right, k, cmp_func)

def median(l, cmp_func):
