from abc import ABC, abstractmethod
from collections import OrderedDict, deque
from datetime import datetime

class CacheInterface(ABC):
    @abstractmethod
    def get(self, id):
        pass

    @abstractmethod
    def put(self, id, value):
        pass

    @abstractmethod
    def delete(self, id):
        pass


class LRUCache(CacheInterface):
    def __init__(self, capacity):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, id):
        try:
            value = self.cache.pop(id)
            self.cache[id] = value
            return value
        except KeyError:
            return -1

    def put(self, id, value):
        try:
            self.cache.pop(id)
        except KeyError:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
        self.cache[id] = value

    def delete(self, id):
        try:
            self.cache.pop(id)
        except KeyError:
            return -1


class FIFOCache(CacheInterface):
    def __init__(self, capacity):
        self.cache = deque(maxlen=capacity)

    def get(self, id):
        for item in self.cache:
            if item[0] == id:
                return item[1]
        return -1

    def put(self, id, value):
        if len(self.cache) == self.cache.maxlen:
            self.cache.popleft()
        self.cache.append((id, value))

    def delete(self, id):
        self.cache = deque([item for item in self.cache if item[0] != id])


