def is_valid_roman(s):
    # Check for empty input
    if not s:
        return False
    import re
    # Only valid Roman numerals (values < 4000) are accepted
    pattern = (
        r"^M{0,3}"            # thousands (0-3)
        r"(CM|CD|D?C{0,3})"    # hundreds
        r"(XC|XL|L?X{0,3})"    # tens
        r"(IX|IV|V?I{0,3})$"   # ones
    )
    return re.match(pattern, s) is not None

def roman_to_int(s):
    roman_numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not all(c in roman_numerals for c in s):
        return -1
    if not is_valid_roman(s):
        return -1
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_numerals[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    if total >= 4000:
        return -1
    return total

def main():
    s = input().strip()
    print(roman_to_int(s))

