class LinkedListNode:
    def __init__(self, value=0, next_node=None):
        self.value = value
        self.next = next_node

def append_to_list(head, value):
    new_node = LinkedListNode(value)
    if not head:
        return new_node
    curr = head
    while curr.next:
        curr = curr.next
    curr.next = new_node
    return head

def copy_list(head):
    new_head = None
    curr = head
    while curr:
        new_head = append_to_list(new_head, curr.value)
        curr = curr.next
    return new_head

def partition(head):
    pivot = head.value
    less, ge = None, None
    curr = head.next
    while curr:
        if curr.value < pivot:
            less = append_to_list(less, curr.value)
        else:
            ge = append_to_list(ge, curr.value)
        curr = curr.next
    return less, ge, pivot

def quicksort(head):
    if not head or not head.next:
        return head
    less, ge, pivot = partition(head)
    sorted_less = quicksort(less)
    sorted_ge = quicksort(ge)
    pivot_node = LinkedListNode(pivot)
    if sorted_less:
        curr = sorted_less
        while curr.next:
            curr = curr.next
        curr.next = pivot_node
        pivot_node.next = sorted_ge
        return sorted_less
    else:
        pivot_node.next = sorted_ge
        return pivot_node

def find_triplets(head):
    triplets = set()
    i = head
    while i:
        # skip duplicate i
        if i != head and i.value == prev_i:
            i = i.next
            continue
        j = i.next
        seen = set()
        while j:
            complement = -(i.value + j.value)
            k = j.next
            while k:
                if k.value == complement and (j.value, k.value) not in seen:
                    t = tuple(sorted([i.value, j.value, complement]))
                    triplets.add(t)
                    seen.add((j.value, k.value))
                    break
                k = k.next
            j = j.next
        prev_i = i.value
        i = i.next
    return sorted(list(triplets))

def main():
    n = int(input())
    values = list(map(int, input().split()))
    head = None
    for val in values:
        head = append_to_list(head, val)
    head = quicksort(head)
    result = find_triplets(head)
    for triplet in result:
        print('{} {} {}'.format(triplet[0], triplet[1], triplet[2]))

