def flatten_dict(d, parent_key='', sep='.'): 
    items = {} 
    if isinstance(d, list): 
        for idx, element in enumerate(d): 
            new_key = f"{parent_key}{sep if parent_key else ''}{idx}" 
            items.update(flatten_dict(element, new_key, sep)) 
    elif isinstance(d, dict): 
        for k, v in d.items(): 
            new_key = f"{parent_key}{sep if parent_key else ''}{k}" 
            if isinstance(v, dict) or isinstance(v, list): 
                items.update(flatten_dict(v, new_key, sep=sep)) 
            elif isinstance(v, str) and any(c.isspace() for c in v): 
                items[new_key] = v.split() 
            else: 
                items[new_key] = v 
    else: 
        items[parent_key] = d 
    return items

