class TreeNode:
    def __init__(self, key=0):
        self.key = key
        self.left = None
        self.right = None
        self.freq = 1

def insert_bst(root, key):
    if not root:
        return TreeNode(key)
    if key < root.key:
        root.left = insert_bst(root.left, key)
    elif key > root.key:
        root.right = insert_bst(root.right, key)
    else:
        root.freq += 1
    return root

class DoublyListNode:
    def __init__(self, key, freq):
        self.key = key
        self.freq = freq
        self.prev = None
        self.next = None

def bst_to_doubly_ll(root):
    head = None
    prev = None
    def inorder(node):
        nonlocal head, prev
        if not node:
            return
        inorder(node.left)
        new_node = DoublyListNode(node.key, node.freq)
        if not head:
            head = new_node
        if prev:
            prev.next = new_node
            new_node.prev = prev
        prev = new_node
        inorder(node.right)
    inorder(root)
    return head

def print_dll(head):
    curr = head
    while curr:
        print(f"Key: {curr.key}, Frequency: {curr.freq}")
        curr = curr.next

def main():
    n = int(input())
    keys = [int(input()) for _ in range(n)]
    root = None
    for k in keys:
        root = insert_bst(root, k)
    dll_head = bst_to_doubly_ll(root)
    print_dll(dll_head)

