function is_happy($s) {
    if (strlen($s) < 3) {
        return false;
    }
    for ($i = 0; $i < strlen($s)-2; $i++) {
        if ($s[$i] == $s[$i+1] || $s[$i+1] == $s[$i+2] || $s[$i] == $s[$i+2]) {
            return false;
        }
    }
    $letter_counts = array_count_values(str_split($s));
    if (array_filter($letter_counts, function($v) { return $v % 2 != 0; })) {
        return false;
    }
    $frequency_counts = array_count_values($letter_counts);
    if (array_filter($frequency_counts, function($k, $v) { return $k <= 3 && $v > 2; }, ARRAY_FILTER_USE_BOTH)) {
        return false;
    }
    return true;
