def remove_empty(d):
    if not isinstance(d, dict):
        return d
    cleaned = {}
    for k, v in d.items():
        if v == '' or v == {}:
            continue
        elif isinstance(v, dict):
            cleaned_v = remove_empty(v)
            if cleaned_v != {}:
