def flatten_dict(d, prefix=None, result=None):
    if result is None:
        result = {}
    for k, v in d.items():
        new_key = k if prefix is None else prefix + '_' + k
        if isinstance(v, dict):
            flatten_dict(v, new_key, result)
        else:
            result[new_key] = v
    return result

