def decimal_to_binary_recursive(n, depth=7):
    if depth < 0:
        return ''
    bit = n & 1
    n >>= 1
    return decimal_to_binary_recursive(n, depth - 1) + str(bit)

def decimal_to_twos_complement(n):
    if n < 0:
        n = 256 + n  # 8-bit two's complement
    binary_string = decimal_to_binary_recursive(n)
    return binary_string.zfill(8)

