import xml.etree.ElementTree as ET
import json

def parse_xml_element(element):
    parsed = {}
    # Add attributes if any
    if element.attrib:
        parsed['@attributes'] = element.attrib.copy()

    children = list(element)
    # Record children
    if children:
        # To group children by tag lexically
        child_dict = {}
        for child in children:
            child_parsed = parse_xml_element(child)
            if child.tag in child_dict:
                if not isinstance(child_dict[child.tag], list):
                    child_dict[child.tag] = [child_dict[child.tag]]
                child_dict[child.tag].append(child_parsed)
            else:
                child_dict[child.tag] = child_parsed
        parsed.update(child_dict)
        # If element also has text, but text is just whitespace, ignore
        # (common in pretty-printed XML)
    else:
        # Only text, no children
        text = element.text
        parsed = text.strip() if text and text.strip() else ''
        if element.attrib:
            output = {'@attributes': element.attrib.copy()}
            if parsed != '':
                output['#text'] = parsed
            parsed = output
    return parsed

def main():
    mode = input().strip()
    data = input()
    if mode == 'xml':
