def process_json(json_obj):
    def process_item(key, value):
        # Handle key renaming
        if isinstance(key, str) and "special" in key.lower():
            key = "SPECIAL"
        if isinstance(value, list):
            result = {}
            for idx, item in enumerate(value):
                idx_key = f"{key}_{idx}"
                processed = process_item(idx_key, item)
                if isinstance(processed, dict):
                    result.update(processed)
                else:
                    k, v = processed
                    result[k] = v
            return result
        elif isinstance(value, dict):
            result = {}
            for sub_key, sub_value in value.items():
                processed = process_item(sub_key, sub_value)
                if isinstance(processed, dict):
                    result.update(processed)
                else:
                    k, v = processed
                    result[k] = v
            return {key: result}
        else:
            if isinstance(value, str):
                if value.lower() == "null":
                    value = None
                else:
                    value = value.upper()
            return (key, value)
    result = {}
    for key, value in json_obj.items():
        processed = process_item(key, value)
        if isinstance(processed, dict):
            result.update(processed)
        else:
            k, v = processed
