import sys
from itertools import combinations

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    m = int(data[0])
    idx = 1

    # Empty array case
    if m == 0:
        print("No elements to combine")
        return

    # Read the array
    if len(data) < 1 + m:
        raise ValueError("Not enough array elements supplied")
    arr = list(map(int, data[idx:idx + m]))
    idx += m

    # Read n
    if idx >= len(data):
        raise ValueError("Missing value of n")
    n = int(data[idx])

    if n > len(arr) or n <= 0:
        print("No combinations")
        return

    seen = set()
    result = []

    # Use indices so that repeated values occupying different positions are treated separately
    for combo_indices in combinations(range(len(arr)), n):
        values = [arr[i] for i in combo_indices]
        if sum(values) == 0:
            sorted_values = tuple(sorted(values))
            if sorted_values not in seen:
                seen.add(sorted_values)
                result.append(list(sorted_values))

    result.sort()  # lexicographic order

    if not result:
        print("No combinations")
    elif len(result) == 1:
        print(" ".join(map(str, result[0])))
    else:
        for comb in result:
            print(" ".join(map(str, comb)))

