function reverse_even($s) {
    $s = str_split($s); // Convert string to array
    $even_chars = [];
    $odd_chars = [];

    // Separate characters at even and odd positions
    foreach ($s as $i => $ch) {
        if ($i % 2 == 0) {
            array_push($even_chars, $ch);
        } else {
            array_push($odd_chars, $ch);
        }
    }

    // Reverse the even positions
    $even_chars = array_reverse($even_chars);

    // Create an empty array of the same length as the input
    $result = array_fill(0, count($s), '');

    // Assign the reversed even and original odd characters back based on their indices
    for ($i = 0; $i < count($s); $i = $i + 2){
        $result[$i] = array_shift($even_chars);
    }
    for ($i = 1; $i < count($s); $i= $i + 2) {
        $result[$i] = array_shift($odd_chars);
    }
    return implode($result);
}
