def maxDepth(root):
    if not root:
        return 0
    return 1 + max(maxDepth(root.left), maxDepth(root.right))

def build_tree(nodes):
    if not nodes:
        return None
    tree_nodes = [TreeNode(val) for val, _, _ in nodes]
    for idx, (val, left_idx, right_idx) in enumerate(nodes):
        if left_idx != -1:
            tree_nodes[idx].left = tree_nodes[left_idx]
        if right_idx != -1:
            tree_nodes[idx].right = tree_nodes[right_idx]
    return tree_nodes[0]

