def can_split_into_equal_subsets(lst):
    total_sum = sum(lst)
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    dp = [False] * (target_sum + 1)
    dp[0] = True

    for num in lst:
        for j in range(target_sum, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]

