import sys

def normalize_unicode(s):
    return unicodedata.normalize('NFC', s)

def tokenize(s):
    tokens = []
    token = []
    for char in s:
        if char.isspace():
            if token:
                tokens.append(''.join(token))
                token = []
        else:
            token.append(char)
    if token:
        tokens.append(''.join(token))
    return tokens

def levenshtein_distance_with_operations(s1_tokens, s2_tokens):
    len1, len2 = len(s1_tokens), len(s2_tokens)
    dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]
    ops = [[None] * (len2 + 1) for _ in range(len1 + 1)]
    for i in range(len1 + 1):
        dp[i][0] = i
        if i > 0:
            ops[i][0] = 'delete'
    for j in range(len2 + 1):
        dp[0][j] = j
        if j > 0:
            ops[0][j] = 'insert'
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if s1_tokens[i-1] == s2_tokens[j-1]:
                dp[i][j] = dp[i-1][j-1]
                ops[i][j] = 'equal'
            else:
                delete = dp[i-1][j] + 1
                insert = dp[i][j-1] + 1
                replace = dp[i-1][j-1] + 1
                minval = min(delete, insert, replace)
                dp[i][j] = minval
                if minval == replace:
                    ops[i][j] = 'replace'
                elif minval == insert:
                    ops[i][j] = 'insert'
                else:
                    ops[i][j] = 'delete'
    i, j = len1, len2
    sequence = []
    while i > 0 or j > 0:
        op = ops[i][j]
        if op == 'equal':
            i -= 1
            j -= 1
        elif op == 'replace':
            sequence.append(f"Replace '{s1_tokens[i-1]}' with '{s2_tokens[j-1]}'")
            i -= 1
            j -= 1
        elif op == 'insert':
            sequence.append(f"Insert '{s2_tokens[j-1]}'")
            j -= 1
        elif op == 'delete':
            sequence.append(f"Delete '{s1_tokens[i-1]}'")
            i -= 1
    sequence.reverse()
