```csharp
using System;
using System.Linq;

public class Program
{
    public static string GetClosestVowel(string word)
    {
        // Define vowels including uppercase for case sensitivity
        string vowels = "aeiouAEIOU";

        // Reverse the input word to start checking from the right-most character
        string reversedWord = new string(word.Reverse().ToArray());

        // Iterate from the second character (index 1) to the second-to-last character in reversedWord
        for (int i = 1; i < reversedWord.Length - 1; i++)
        {
            char current = reversedWord[i];

            // Check if current character is a vowel and its immediate neighbors are consonants
            if (vowels.Contains(current))
            {
                // Check previous character (i-1) is a consonant
                if (!vowels.Contains(reversedWord[i - 1]))
                {
                    // Check next character (i+1) is also a consonant
                    if (!vowels.Contains(reversedWord[i + 1]))
                    {
                        // Return the found vowel (convert to string to match return type)
                        return current.ToString();
                    }
                }
            }
        }

        // Return empty string if no valid vowel found
        return "";
    }

    // Test cases
    public static void Main()
    {
        Console.WriteLine(GetClosestVowel("yogurt"));  // "u"
        Console.WriteLine(GetClosestVowel("FULL"));    // "U"
        Console.WriteLine(GetClosestVowel("quick"));   // ""
        Console.WriteLine(GetClosestVowel("ab"));      // ""
    }
}
```

### Explanation:
1. **Vowel Definition**: Uses a string with both lowercase and uppercase vowels for case sensitivity.
2. **Reversal**: Uses LINQ's `Reverse()` method to flip the input word, positioning the right-most character at index 0.
3. **Loop Bounds**: The loop starts at index 1 (skipping the first character) and stops before the last character (via `reversedWord.Length -1`) to ensure only internal characters are considered.
4. **Validation Check**: Uses nested checks to confirm both neighboring characters are consonants before returning the vowel.
5. **Edge Handling**: Automatically skips vowels at word boundaries due to loop limits, and returns an empty string if no valid pattern is detected.

