import math

#Function to calculate sum of digits of a number
def sum_digits(n):
    res = 0
    while n:
        res += n % 10
        n //= 10
    return res

#Function to calculate h(n)
def h(n):
    res = 1
    for digit in str(n):
        res *= math.factorial(int(digit))
    return res

#Function to calculate p(i)
def p(i):
    n = 1
    while True:
        if sum_digits(h(n)) == i:
            return n
        n += 1

#Function to calculate sp(i)
def sp(i):
    return sum_digits(p(i))

