import sys
from collections import defaultdict

def main():
    n, m = map(int, sys.stdin.readline().split())
    if m % 2 != 0:
        print("No solution")
        return

    edges = []
    adj = defaultdict(list)
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        edges.append((u, v))
        adj[u].append((v, len(edges)-1))
        adj[v].append((u, len(edges)-1))

    used = [False] * m
    ans = []
    visited = [False] * (n + 1)
    parent = {}
    stack = []

    # depth-first search that tries to build a stack of vertices
    def dfs(u):
        stack.append(u)
        visited[u] = True
        for v, idx in adj[u]:
            if not visited[v]:
                parent[v] = (u, idx)
                dfs(v)
                stack.append(u)
            elif not used[idx] and parent.get(u, (None, None))[0] != v:
                stack.append(v)
                stack.append(u)

    dfs(1)

    # naive attempt to pop triples from the stack
    while stack:
        if len(stack) < 3:
            break
        u = stack.pop()
        v = stack.pop()
        w = stack.pop()
        if v == u:
            ans.append((u, w, stack.pop() if stack else w))
        else:
            ans.append((u, v, w))

    # verify all edges used (they never are in this implementation)
    for idx in range(m):
        if not used[idx]:
            print("No solution")
            return

    for a, b, c in ans:
        print(f"{a} {b} {c}")

