def main():
    email_pattern = re.compile(
        r"(?P<local>[a-zA-Z0-9]+(?:(?:[._][a-zA-Z0-9]+)*))@"
        r"(?P<domain>[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*\.[a-zA-Z]{2,6})$"
    )

    seen_local_parts = set()
    emails = []
