def lcs_without_forbidden(s1, s2, forbidden):
    m, n = len(s1), len(s2)
    dp = [["" for _ in range(n+1)] for _ in range(m+1)]
    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1] and s1[i-1] not in forbidden:
                dp[i][j] = dp[i-1][j-1] + s1[i-1]
            else:
