class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def insert_bst(root, val):
    if not root:
        return TreeNode(val)
    if val < root.val:
        root.left = insert_bst(root.left, val)
    else:
        root.right = insert_bst(root.right, val)
    return root

def closest_value_bst(root, target):
    closest = root.val
    while root:
        if abs(target - root.val) < abs(target - closest) or (abs(target - root.val) == abs(target - closest) and root.val < closest):
            closest = root.val
        if target < root.val:
            root = root.left
        elif target > root.val:
            root = root.right
        else:
            return root.val
    return closest

