def sieve_of_eratosthenes_recursive(n):
    def mark_non_primes(arr, p):
        if p * p > n:
            return arr
        else:
            new_arr = mark_multiples(arr, p * p, p)
            return mark_non_primes(new_arr, p + 1)

    def mark_multiples(arr, start, step):
        if start > n:
            return arr
        else:
            arr[start - 1] = False
            return mark_multiples(arr, start + step, step)

    def filter_primes(arr, index, result):
        if index > n:
            return result
        elif arr[index - 1]:
            return filter_primes(arr, index + 1, result + [index])
        else:
            return filter_primes(arr, index + 1, result)

    if n < 2:
        return []
    initial_arr = [True] * n
    sieve_result = mark_non_primes(initial_arr, 2)
    primes = filter_primes(sieve_result, 2, [])
    return primes

def main():
    n = int(input())
    primes = sieve_of_eratosthenes_recursive(n)
