```Python
def find_divisors(n):
    i = 1
    divisors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            divisors.append(i)
            if n // i != i:
                divisors.append(n // i)
            i += 1
    return sorted(divisors)

