def add(x, y):
    while y:
        carry = x & y
        x = x ^ y
        y = carry << 1
    return x

def subtract(x, y):
    # Assumes x >= y
    while y:
        borrow = (~x) & y
        x = x ^ y
        y = borrow << 1
    return x

def multiply(x, y):
    result = 0
    while y:
        if y & 1:
            result = add(result, x)
        x = x << 1
        y = y >> 1
    return result

def divide(x, y):
    if y == 0:
        return "Error: Division by zero"
    quotient = 0
    remainder = x
    shift = 0
    # find highest bit
    y_bits = y
    while (y_bits <= remainder) and (y_bits != 0):
        y_bits = y_bits << 1
        shift = add(shift, 1)
    if shift > 0:
        shift = subtract(shift, 1)
        y_bits = y_bits >> 1
    while shift >= 0:
        if remainder >= y_bits:
            remainder = subtract(remainder, y_bits)
            quotient |= (1 << shift)
        y_bits = y_bits >> 1
        if shift == 0:
            break
        shift = subtract(shift, 1)
    return quotient

