def flatten_dict(d, parent_key='', sep='.', seen=None):
    if seen is None:
        seen = set()
    if id(d) in seen:
        return {}
    seen.add(id(d))
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else str(k)
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep, seen).items())
        else:
            items.append((new_key, v))
    seen.remove(id(d))
    return dict(items)

