import sys

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    q = int(next(it))
    out_lines = []
    INF = 10**19  # bigger than any possible answer
    for _ in range(q):
        n = int(next(it))
        a = [0]*n
        b = [0]*n
        for i in range(n):
            a[i] = int(next(it))
            b[i] = int(next(it))
        if n == 1:
            out_lines.append('0')
            continue
        # dp[j] — minimal cost up to current board when we add j (0/1/2) units to this board
        dp = [0, b[0], 2*b[0]]
        for i in range(1, n):
            ndp = [INF, INF, INF]
            for add_prev in range(3):
                if dp[add_prev] == INF:
                    continue
                prev_h = a[i-1] + add_prev
                for add_cur in range(3):
                    cur_h = a[i] + add_cur
                    if cur_h != prev_h:
                        cost = dp[add_prev] + add_cur * b[i]
                        if cost < ndp[add_cur]:
                            ndp[add_cur] = cost
            dp = ndp
        out_lines.append(str(min(dp)))
    sys.stdout.write('\n'.join(out_lines))

