    return num_str == num_str[::-1]

def prime_generator(n):
    count = 0
    num = 2
    while count < n:
        if is_prime(num):
            yield num
            count += 1
        num += 1

def palindromic_prime_generator(n):
    count = 0
    num = 2
    while count < n:
        if is_prime(num) and is_palindrome(num):
            yield num
            count += 1
        num += 1

def custom_palindromic_prime_generator(n):
    def is_custom_prime(num):
        if num < 2:
            return False
        for i in range(2, num):
            if num % i == 0:
                return False
        return True

    def is_custom_palindrome(num):
        num_str = str(num)
        start, end = 0, len(num_str) - 1
        while start <= end:
            if num_str[start] != num_str[end]:
                return False
            start += 1
            end -= 1
        return True

    count = 0
    num = 2
    while count < n:
        if is_custom_prime(num) and is_custom_palindrome(num):
            yield num
            count += 1
        num += 1

