import ast
from typing import Any, Dict, Tuple

def _safe_literal_eval(node: ast.AST) -> Any:
    """
    Safely evaluate an AST node that should represent a literal.
    Falls back to ``None`` if the node cannot be evaluated with
    ``ast.literal_eval`` (e.g., contains a call or operation).
    """
    try:
        return ast.literal_eval(node)
    except Exception:
        return None


def _extract_from_target(
    target: ast.AST,
    value_obj: Any,
    interesting: Tuple[str, str],
    out: Dict[str, Any],
) -> None:
    """
    Recursively inspect assignment targets and store values for
    variable names that match the interesting substrings.
    """
    if isinstance(target, ast.Name):
        if any(key in target.id for key in interesting):
            out[target.id] = value_obj
    elif isinstance(target, (ast.Tuple, ast.List)):
        # Handle unpacking assignments such as:
        # napoleon_use_param, napoleon_use_rtype = True, False
        if isinstance(value_obj, (tuple, list)) and len(value_obj) == len(target.elts):
            for sub_t, sub_v in zip(target.elts, value_obj):
                _extract_from_target(sub_t, sub_v, interesting, out)


def extract_documented_settings(config_code: str) -> dict:
    """
    Extract settings related to parameter and return-type documentation
    from a configuration string.

    Only variables whose names contain either
    ``'napoleon_use_param'`` or ``'napoleon_use_rtype'`` are returned.

    Parameters
    ----------
    config_code : str
        The text of the configuration file (Python code).

    Returns
    -------
    dict
        Mapping from setting names to their literal values.
        If a value cannot be evaluated safely it is stored as ``None``.
    """
    interesting_keys = ("napoleon_use_param", "napoleon_use_rtype")
    extracted: Dict[str, Any] = {}

    try:
        tree = ast.parse(config_code, mode="exec")
    except SyntaxError:
        # If the supplied code cannot be parsed, return empty dict.
        return extracted

    for node in tree.body:
        if isinstance(node, ast.Assign):
            literal_value = _safe_literal_eval(node.value)
            for tgt in node.targets:
                _extract_from_target(tgt, literal_value, interesting_keys, extracted)

    return extracted

class Stack:
    def __init__(self):
        self.items = []
    def push(self, item):
        self.items.append(item)
    def pop(self):
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self.items.pop()
    def peek(self):
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self.items[-1]
    def is_empty(self):
        return len(self.items) == 0

def main():
    s = Stack()
    while True:
        try:
            line = input()
        except EOFError:
