from collections import deque
import sys

def build_tree(level_order):
    if not level_order or level_order[0] == 'null':
        return None
    root = TreeNode(int(level_order[0]))
    queue = deque([root])
    i = 1
    while queue and i < len(level_order):
        current = queue.popleft()
        # Left child
        if i < len(level_order):
            if level_order[i] != 'null':
                current.left = TreeNode(int(level_order[i]))
                queue.append(current.left)
            i += 1
        # Right child
        if i < len(level_order):
            if level_order[i] != 'null':
                current.right = TreeNode(int(level_order[i]))
                queue.append(current.right)
            i += 1
    return root

class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def max_sum_level(root):
    if not root:
        return 0
    queue = [root]
    max_sum = float('-inf')
    level_with_max_sum = 0
    current_level = 0
    while queue:
        level_sum = 0
        next_queue = []
        for node in queue:
            level_sum += node.value
            if node.left:
                next_queue.append(node.left)
            if node.right:
                next_queue.append(node.right)
        if level_sum > max_sum:
            max_sum = level_sum
            level_with_max_sum = current_level
        queue = next_queue
        current_level += 1
    return level_with_max_sum

def main():
    level_order = sys.stdin.read().strip().split()
    root = build_tree(level_order)
    print(max_sum_level(root))

if __name__ == "__main__":
    main()

