def next_permutation(nums):
    n = len(nums)
    if n <= 1:
        return
    k = n - 2
    while k >= 0 and nums[k] >= nums[k + 1]:
        k -= 1
    if k >= 0:
        l = n - 1
        while nums[l] <= nums[k]:
            l -= 1
        nums[k], nums[l] = nums[l], nums[k]
    start, end = k + 1, n - 1
    while start < end:
        nums[start], nums[end] = nums[end], nums[start]
        start += 1
        end -= 1

