def serialize_blog_post(blog_post):
    def convert_to_str(v):
        if isinstance(v, (list, dict)):
            return json.dumps(v)
        elif isinstance(v, datetime):
            return v.isoformat()
        return str(v)
    def serialize(obj):
        if isinstance(obj, dict):
            serialized_dict = []
            for k, v in obj.items():
                key = k
                if k.startswith('multimedia'):
                    v = encode_multimedia(v)
                elif k.startswith('meta_'):
                    key = '_' + k  # rename metadata keys
                serialized_dict.append(f"'{key}': {serialize(v)}")
            return "{" + ", ".join(serialized_dict) + "}"
        elif isinstance(obj, (list, tuple)):
            return "[" + ", ".join(serialize(item) for item in obj) + "]"
        else:
            return f"'{convert_to_str(obj)}'"
    return serialize(blog_post)

