class MIDINote:
    def __init__(self, pitch, duration):
        self.pitch = pitch
        self.duration = duration
        self.semitone = self.note_to_semitones(pitch)

    def note_to_semitones(self, pitch):
        notes = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B']
        # Support for A4, C#4, etc.
        if len(pitch) == 2:  # e.g. C4
            note, octave = pitch[0], int(pitch[1])
            accidental = ''
        elif len(pitch) == 3:  # e.g. C#4
            note, accidental, octave = pitch[0], pitch[1], int(pitch[2])
            note += accidental
        else:
            raise ValueError(f"Invalid pitch format: {pitch}")
        return (octave + 1) * 12 + notes.index(note)

    def transpose(self, semitones):
        return self.semitone + semitones


