def tree_to_doubly_linked_list(root):
    def convert(node):
        nonlocal last, head
        if not node:
            return
        convert(node.left)
        if last:
            last.right = node
            node.left = last
        else:
            head = node
        last = node
        convert(node.right)
    last, head = None, None
    convert(root)
    return head

