import ast
import operator
import sys

def main():
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
    }
    try:
        expr = input().strip()
        n = int(input())
        variables = {}
        for _ in range(n):
            line = input().strip()
            if '=' not in line:
                raise ValueError('Invalid variable assignment')
            var, val = line.split('=', 1)
            var = var.strip()
            val = val.strip()
            try:
                if '.' in val:
                    variables[var] = float(val)
                else:
                    variables[var] = int(val)
            except:
                raise ValueError('Invalid variable value')

        def eval_node(node):
            if isinstance(node, ast.Num):
                return node.n
            elif hasattr(ast, 'Constant') and isinstance(node, ast.Constant):
                if isinstance(node.value, (int, float)):
                    return node.value
                raise TypeError('Invalid constant type')
            elif isinstance(node, ast.BinOp):
                left = eval_node(node.left)
                right = eval_node(node.right)
                op_type = type(node.op)
                if op_type in operators:
                    return operators[op_type](left, right)
                else:
                    raise TypeError('Invalid operator')
            elif isinstance(node, ast.UnaryOp):
                operand = eval_node(node.operand)
                op_type = type(node.op)
                if op_type in operators:
                    return operators[op_type](operand)
                else:
                    raise TypeError('Invalid unary operator')
            elif isinstance(node, ast.Name):
                if node.id in variables:
                    return variables[node.id]
                else:
                    raise NameError(f"Name '{node.id}' not found in the provided variables.")
            else:
                raise TypeError('Invalid node')
        tree = ast.parse(expr, mode='eval')
        result = eval_node(tree.body)
        if isinstance(result, float) and result == int(result):
            result = int(result)
        print(result)
    except Exception:
        print('Invalid expression')

