import sys
import time

class Node:
    def __init__(self, value, timestamp):
        self.value = value
        self.timestamp = timestamp
        self.next = None
        self.prev = None

class KeyValueStore:
    def __init__(self):
        self.store = {}

    def set_key(self, key, value):
        now = time.time()
        new_node = Node(value, now)
        if key in self.store:
            current_head = self.store[key]
            new_node.next = current_head
            current_head.prev = new_node
        self.store[key] = new_node

    def get_key(self, key):
        if key not in self.store:
            return None
        node = self.store[key]
        return node.value

    def delete_key(self, key):
        if key in self.store:
            del self.store[key]

    def keys_above_threshold(self, threshold):
        current_time = time.time()
        ten_minutes_ago = current_time - 10 * 60
        res = []
        for key, node in self.store.items():
            n = node
            while n:
                if n.timestamp >= ten_minutes_ago and n.value > threshold:
                    res.append((key, n.timestamp))
                    break  # Only consider a key once, using its most recent adequate value
                n = n.next
        res.sort(key=lambda x: x[1], reverse=True)
        return [key for key, _ in res]


def main():
