            store.set_key(key, val)
        elif tokens[0] == 'get' and len(tokens) == 2:
            key = tokens[1]
            val = store.get_key(key)
            print(val if val is not None else 'None')
        elif tokens[0] == 'delete' and len(tokens) == 2:
            key = tokens[1]
            store.delete_key(key)
        elif tokens[0] == 'keys_above' and len(tokens) == 2:
            threshold = int(tokens[1])
            result = store.keys_above_threshold(threshold)
            for key in result:
