    params = {'q': query, 'key': api_key, 'maxResults': 1}

    try:
        response = requests.get(base_url, params=params, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        return {'error': f"API request failed: {str(e)}. Ensure your API key's validity and signature."}

    data = response.json()
    if 'error' in data:
        return {'error': f"API returned error: {data['error']['message']} (check query or signature)."}
    elif not data.get('items'):
        return {'error': "Book not found with the provided search query."}

    book_info = data['items'][0]['volumeInfo']
    parsed_info = {
        'title': book_info.get('title', 'N/A'),
        'author': ', '.join(book_info.get('authors', ['N/A'])),
        'publisher': book_info.get('publisher', 'N/A'),
        'publication_year': book_info.get('publishedDate', 'N/A')[:4],
        'isbn': 'N/A'
    }

    # Extract ISBN_13 or ISBN_10
    for identifier in book_info.get('industryIdentifiers', []):
        if identifier['type'] == 'ISBN_13':
            parsed_info['isbn'] = identifier['identifier']
            break
    if parsed_info['isbn'] == 'N/A':
        for identifier in book_info.get('industryIdentifiers', []):
