def convert_case(input_str: str, target_case: str) -> str:
    """
    Convert `input_str` (which is in camel, snake or kebab case) to `target_case`.

    Parameters
    ----------
    input_str : str
        The original string.
    target_case : str
        Desired case format: 'camel', 'snake', or 'kebab'.

    Returns
    -------
    str
        The converted string, or an empty string if `target_case` is invalid.
    """

    # -------------------- helpers -------------------- #
    def detect_case(s: str) -> str:
        """Detect current case of the string (assumes valid input)."""
        if "_" in s:
            return "snake"
        if "-" in s:
            return "kebab"
        return "camel"  # default / fall-back

    def split_camel(s: str) -> list[str]:
        """Split a camelCase string into constituent lowercase words."""
        words, current = [], ""
        for ch in s:
            if ch.isupper():
                if current:
                    words.append(current)
                current = ch.lower()
            else:
                current += ch
        if current:
            words.append(current)
        return words
    # ------------------------------------------------- #

    target_case = target_case.lower()
    if target_case not in {"camel", "snake", "kebab"}:
        return ""

    current_case = detect_case(input_str)
    if current_case == target_case:
        return input_str  # already in desired format

    # Break input into individual lowercase words
    if current_case == "snake":
        words = input_str.split("_")
    elif current_case == "kebab":
        words = input_str.split("-")
    else:  # camel
        words = split_camel(input_str)

    # Build output in the requested format
    if target_case == "snake":
        return "_".join(words)
    if target_case == "kebab":
        return "-".join(words)
    # target_case == "camel"
    return words[0] + "".join(w.capitalize() for w in words[1:])

