def stack_operations(operations):
    """
    Execute a sequence of stack operations provided as (command, value) tuples.

    operations : list[tuple[str, Any]]
        Each tuple is either ('push', value) or ('pop', None).
    Returns
    -------
    list
        The results of every pop operation, in the order they were executed.
        If a pop is attempted on an empty stack, None is appended for that pop.
    """

    class Node:
        __slots__ = ("value", "next")

        def __init__(self, value, next_node=None):
            self.value = value
            self.next = next_node

    class Stack:
        def __init__(self):
            self._top = None  # Reference to the top Node

        def push(self, value):
            self._top = Node(value, self._top)

        def pop(self):
            if self._top is None:
                return None
            node = self._top
            self._top = node.next
            return node.value

    stack = Stack()
    pop_results = []

    for cmd, val in operations:
        if cmd == 'push':
            stack.push(val)
        elif cmd == 'pop':
            pop_results.append(stack.pop())
        else:
            raise ValueError(f"Unknown command: {cmd}")

    return pop_results

def can_form_palindrome(string):
    # Convert the string to lowercase and remove non-alphabetic characters
    cleaned_string = ''.join(char.lower() for char in string if char.isalnum())

    # Count the frequency of each character
    char_count = {}
    for char in cleaned_string:
        char_count[char] = char_count.get(char, 0) + 1

    # Check if at most one character has an odd count
    odd_count = sum(count % 2 for count in char_count.values())
    return odd_count <= 1

