First, we need a function to check the precedence of the operators:

```python
def precedence(op):
    if op == '+' or op == '-':
        return 1
    if op == '*' or op == '/':
        return 2
    if op == '^':
        return 3
    return 0
```

Next, we need a function to perform the operators function:

```python
def applyOperator(operators, values):
    op = operators[-1]
    operators.pop()
    val1 = values[-1]
    values.pop()
    val2 = values[-1]
    values.pop()

    if op == '+':
        values.append(val2 + val1)
    elif op == '-':
        values.append(val2 - val1)
    elif op == '*':
        values.append(val2 * val1)
    elif op == '^':
        values.append(val2**val1)
    else:
        if val1 == 0:
            print("ERROR: Division by zero!")
            values.append(0)
        else:
            values.append(float(val2) / float(val1))
```

Now, we create the main function to convert infix to prefix and evaluate:

```python
def evaluateExpression(expression):
    values = []
    operators = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        elif expression[i] == '(':
            operators.append(expression[i])
        elif expression[i].isdigit():
            j = i
            while j<len(expression) and expression[j].isdigit():
                j+=1
            values.append(int(expression[i:j]))
            i = j-1
        elif expression[i] == ')':
            while len(operators)!= 0 and operators[-1] != '(':
                applyOperator(operators, values)
            operators.pop()
        else:
            while (len(operators) != 0 and
                precedence(operators[-1]) >= precedence(expression[i])):
                applyOperator(operators, values)
            operators.append(expression[i])
        i += 1

    while len(operators) != 0:
        applyOperator(operators, values)

    return values[-1]
```
