    graph = {}
    nodes = []
    for _ in range(n):
        line = input().strip().split()
        node, num_neighbors = line[0], int(line[1])
        neighbors = line[2:] if num_neighbors > 0 else []
        graph[node] = neighbors
        nodes.append(node)

    visited = set()
    rec_stack = set()
    cycles = set()

    def dfs(v, path):
        visited.add(v)
        rec_stack.add(v)
        path.add(v)
        for neighbor in graph[v]:
            if neighbor in rec_stack:
                # Found a cycle, all nodes in path participate.
                cycles.update(path)
            elif neighbor not in visited:
                dfs(neighbor, path)
        rec_stack.remove(v)
        path.remove(v)

    for node in nodes:
        if node not in visited:
            dfs(node, set())

    if cycles:
        print('Has cycle: True')
        print('Cycle nodes: ' + ' '.join(sorted(cycles)))
    else:
        print('Has cycle: False')
