    nums = list(map(int, sys.stdin.read().strip().split()))
    result = []

    def backtrack(start):
        if start == len(nums):
            result.append(nums[:])
        else:
            seen = set()
            for i in range(start, len(nums)):
                if nums[i] in seen:
                    continue
                seen.add(nums[i])
                nums[start], nums[i] = nums[i], nums[start]
                backtrack(start + 1)
                nums[start], nums[i] = nums[i], nums[start]

    nums.sort()
    backtrack(0)
    for perm in result:
