import ast
from typing import Union

def is_expression_true(expression: str) -> bool:
    """
    Evaluate a boolean expression that may contain the literals
    True / False and the operators and / or / not plus parentheses.

    The evaluation is performed through a tiny interpreter built
    on Python's `ast` module, so no arbitrary Python code can be
    executed.

    Parameters
    ----------
    expression : str
        A syntactically-valid boolean expression.

    Returns
    -------
    bool
        True  – if the expression simplifies to True
        False – otherwise
    """

    # Parse the string to an AST in *expression* mode
    tree: ast.Expression = ast.parse(expression, mode='eval')

    def eval_node(node: ast.AST) -> bool:
        # BoolOp  -> "and" / "or"
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                # short-circuit AND
                for val_node in node.values:
                    if not eval_node(val_node):
                        return False
                return True

            elif isinstance(node.op, ast.Or):
                # short-circuit OR
                for val_node in node.values:
                    if eval_node(val_node):
                        return True
                return False

            else:
                raise ValueError("Unsupported boolean operator")

        # UnaryOp -> "not"
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return not eval_node(node.operand)
            raise ValueError("Unsupported unary operator")

        # Literals (Python 3.8+: ast.Constant, older: ast.NameConstant)
        if isinstance(node, ast.Constant):
            if isinstance(node.value, bool):
                return node.value
            raise ValueError("Only boolean literals are allowed")

        if hasattr(ast, "NameConstant") and isinstance(node, ast.NameConstant):
            if isinstance(node.value, bool):
                return node.value
            raise ValueError("Only boolean literals are allowed")

        # Fallback for older versions where True/False might arrive as ast.Name
        if isinstance(node, ast.Name):
            if node.id == "True":
                return True
            if node.id == "False":
                return False
            raise ValueError(f"Unknown identifier {node.id!r}")

        # Anything else is disallowed
        raise ValueError(f"Unsupported syntax element: {type(node).__name__}")

    # `ast.parse(..., mode='eval')` wraps the real expression in `Expression`
    return eval_node(tree.body)

