import sys
import json

def find_employees_under_manager(structure, manager_name):
    result = {manager_name: []}
    if not isinstance(structure, dict):
        return result

    def search_hierarchy(teams, manager):
        for team_name, team_content in teams.items():
            if isinstance(team_content, dict):
                if 'manager' in team_content and team_content['manager'] == manager:
                    # Collect employees directly under this manager
                    result[manager_name].append({
                        team_name: team_content.get('employees', [])
                    })
                # Recursively search in sub-teams
                search_hierarchy(team_content, manager)
            elif isinstance(team_content, list):
                # If the content is a list, it might be a direct list of employees
                continue
    search_hierarchy(structure, manager_name)
    # Clean up empty sub-teams entries
    result[manager_name] = [entry for entry in result[manager_name] if entry]
    return result

def main():
    lines = sys.stdin.read().split('\n')
    manager_name = lines[0].strip()
    json_text = '\n'.join(lines[1:]).strip()
    if not json_text:
        print(json.dumps({manager_name: []}, indent=4))
        return
    structure = json.loads(json_text)
    result = find_employees_under_manager(structure, manager_name)
    print(json.dumps(result, indent=4))

