class TernaryMinHeap:
    def __init__(self, arr):
        self.heap = arr[:]
        self.build_heap()

    def build_heap(self):
        for i in range(len(self.heap) // 3, -1, -1):
            self.heapify(i)

    def heapify(self, i):
        smallest = i
        left = 3 * i + 1
        middle = 3 * i + 2
        right = 3 * i + 3

        if left < len(self.heap) and self.heap[left] < self.heap[smallest]:
            smallest = left
        if middle < len(self.heap) and self.heap[middle] < self.heap[smallest]:
            smallest = middle
        if right < len(self.heap) and self.heap[right] < self.heap[smallest]:
            smallest = right

        if smallest != i:
            self.heap[i], self.heap[smallest] = self.heap[smallest], self.heap[i]
            self.heapify(smallest)

    def extract_min(self):
        if len(self.heap) == 0:
            return None
        if len(self.heap) == 1:
            return self.heap.pop()
        root = self.heap[0]
        self.heap[0] = self.heap.pop()
        self.heapify(0)
        return root

    def insert(self, to_insert):
        self.heap.append(to_insert)
        self.lift_up(len(self.heap) - 1)

    def lift_up(self, index):
        parent = (index - 1) // 3
        if parent >= 0 and self.heap[parent] > self.heap[index]:
            self.heap[parent], self.heap[index] = self.heap[index], self.heap[parent]
            self.lift_up(parent)

