class Circle {
  constructor(x, y, radius) {
    this.x = x;
    this.y = y;
    this.radius = radius;
  }

  // Getter for x-coordinate
  get getX() {
    return this.x;
  }

  // Getter for y-coordinate
  get getY() {
    return this.y;
  }

  // Getter for radius
  get getRadius() {
    return this.radius;
  }

  // Setter for x-coordinate
  set setX(newX) {
    this.x = newX;
  }

  // Setter for y-coordinate
  set setY(newY) {
    this.y = newY;
  }

  // Setter for radius
  set setRadius(newRadius) {
    this.radius = newRadius;
  }

  // Method to calculate area of the circle
  calculateArea() {
    return Math.PI * Math.pow(this.radius, 2);
  }

  // Method to calculate perimeter of the circle
  calculatePerimeter() {
    return 2 * Math.PI * this.radius;
  }

  // Method to check if a point is inside the circle or not
  isInsideCircle(x, y) {
    let distance = Math.sqrt(Math.pow((x - this.x), 2) + Math.pow((y - this.y), 2));
    return distance <= this.radius;
  }
}
