def find_closest(nums, target):
    left, right = 0, len(nums) - 1
    closest = None
    while left <= right:
        mid = (left + right) // 2
        # Update the closest value
        if closest is None or abs(nums[mid] - target) < abs(closest - target) or (abs(nums[mid] - target) == abs(closest - target) and nums[mid] < closest):
            closest = nums[mid]
        if nums[mid] == target:
            return nums[mid]
        elif nums[mid] < target:
