using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public int NonOverlappingSubsequences(string str, string substring)
    {
        int count = 0;
        int start = 0;

        while (true)
        {
            start = str.IndexOf(substring, start) + 1; // IndexOf is the C# equivalent of Python's find method

            // char.IsDigit checks if a character is a digit
            // Any method checks if any elements in the collection satisfy the condition
            if (start > 0 && substring.Any(char.IsDigit)) 
            {
                count++;
            }
            else
            {
                return count;
            }
        }
    }

    public List<Tuple<string, int>> FindSubstringsWithKDistinctChars(string str, int k)
    {
        var substrings = new List<Tuple<string, int>>();
        var vowels = "aeiouAEIOU";

        for (int i = 0; i < str.Length; i++)
        {
            for (int j = i + k; j <= str.Length; j++)
            {
                var substring = str.Substring(i, j - i); // Substring method is the C# equivalent of Python's slice

                // To create a set in C#, we use the HashSet<T> class.
                // Count property returns the number of elements in the collection
                if (new HashSet<char>(substring).Count == k) 
                {
                    // Count method counts how many elements in the collection satisfy the condition
                    var vowel_count = substring.Count(c => vowels.Contains(c));
                    substrings.Add(new Tuple<string, int>(substring, vowel_count));
                }
            }
        }

        // OrderBy method sorts the list by the condition - in this case, the string part of the tuple.
        substrings = substrings.OrderBy(t => t.Item1).ToList(); 

        return substrings;
    }
}
```

Notes:
- Python slices and the C# Substring method behave differently. In Python, `string[i:j]` retrieves characters from index `i` up to but not including index `j`, but in C# `string.Substring(i, j)` retrieves `j` characters starting from index `i`, hence `j - i` in the `Substring` call.
- The HashSet class in C# is equivalent to the set function in Python, providing a collection of unique elements.
- The C# `Count` method acts like the Python `len` function when no arguments are given. When a predicate is supplied, it acts similar to Python's list comprehension, counting the number of elements that satisfy the condition.
- `OrderBy` in C# is similar to the sorting mechanism in Python; it sorts the collection based on the provided key. `ToList` is then used to convert the result back into a list.

