Here is the equivalent code in Swift that performs the same calculations. 

Note: In Swift, functions cannot be stored directly in a dictionary like Python. Hence, we use a switch case here to determine which operation to perform. 

```swift
import Foundation

func areaOfSquare(side: Double) -> Double {
    return pow(side, 2)
}

func perimeterOfSquare(side: Double) -> Double {
    return 4 * side
}

func areaOfRectangle(length: Double, width: Double) -> Double {
    return length * width
}

func perimeterOfRectangle(length: Double, width: Double) -> Double {
    return 2 * (length + width)
}

func doGeometricCalculation(operations: [String], figures: [Any]) -> Double {
    var calculations: Double = 0

    for (index, operation) in operations.enumerated() {
        var figure = figures[index]
        // Convert the figure to tuple if it's not
        if !(figure is (Double, Double)) {
            figure = (figure as! Double, 0.0)
        }

        switch operation {
        case "A_s":
            calculations += areaOfSquare(side: (figure as! (Double, Double)).0)
        case "P_s":
            calculations += perimeterOfSquare(side: (figure as! (Double, Double)).0)
        case "A_r":
            calculations += areaOfRectangle(length: (figure as! (Double, Double)).0, width: (figure as! (Double, Double)).1)
        case "P_r":
            calculations += perimeterOfRectangle(length: (figure as! (Double, Double)).0, width: (figure as! (Double, Double)).1)
        default:
            print("Error: The operation \(operation) cannot be applied to the figure \(figure)")
        }
    }

    return calculations
}
```

