As per the ECMAScript specification, the rules for naming JavaScript identifiers (variables, function names, and other identifiers) are as follows:

1. The first character must be a letter, an underscore (_), or a dollar sign ($).
2. Subsequent characters can be letters, digits (0-9), underscores, or dollar signs.
3. They cannot be a reserved word.

Here is how we could implement a JavaScript function to check whether a given text string is a valid JavaScript identifier according to these rules:

```javascript
// list of reserved words in JavaScript
const RESERVED_WORDS = [
  'await', 'break', 'case', 'catch', 'class', 'const', 'continue', 'debugger',
  'default', 'delete', 'do', 'else', 'export', 'extends', 'finally', 'for',
  'function', 'if', 'import', 'in', 'instanceof', 'new', 'return',
  'super', 'switch', 'this', 'throw', 'try', 'typeof', 'var', 'void',
  'while', 'with', 'yield', 'enum', 'implements', 'interface', 'let',
  'package', 'private', 'protected', 'public', 'static', 'null', 'true', 'false'
];

function isValidIdentifier(identifier) {
  // check if the identifier is not empty
  if (!identifier) {
    return false;
  }
  // check that the first character is a letter, underscore, or dollar sign
  if (/^[^a-zA-Z_$]/.test(identifier[0])) {
    return false;
  }
  // check that the remaining characters are valid
  if (/[^a-zA-Z0-9_$]/.test(identifier.slice(1))) {
    return false;
  }
  // check that the identifier is not a reserved word
  if (RESERVED_WORDS.includes(identifier)) {
    return false;
  }
  return true;
}
```

You can use this function by calling it with the identifier as an argument. For example, the call `isValidIdentifier("myVariable")` would return true, while the call `isValidIdentifier("2ndVariable")` would return false, because 2ndVariable does not start with a letter, underscore, or dollar sign. Similarly, `isValidIdentifier("var")` would return false because 'var' is a reserved word in JavaScript.

