from typing import Any, Dict, List, Tuple
from collections import Counter

def compareDicts(a: List[Dict[str, Any]], b: List[Dict[str, Any]]) -> bool:
    """
    Compare two lists of dictionaries for equality (ignoring order) after removing
    every key named 'Id'.  Returns True if they contain the same dictionaries
    with the same multiplicities, otherwise False.
    """

    def make_hashable(obj: Any) -> Any:
        """
        Recursively turn an arbitrary Python object into something that is
        hashable and has a canonical representation, so it can be used as a
        key in a Counter.
        """
        if isinstance(obj, dict):
            # Sort items by key to make the representation deterministic
            return tuple((k, make_hashable(v)) for k, v in sorted(obj.items()))
        elif isinstance(obj, (list, tuple)):
            return tuple(make_hashable(item) for item in obj)
        elif isinstance(obj, set):
            # Sets are unordered; sort their hashable representations
            return tuple(sorted(make_hashable(item) for item in obj))
        # For anything else, fall back to the object itself if hashable;
        # otherwise use its string representation.
        try:
            hash(obj)
        except TypeError:
            return str(obj)
        return obj

    def preprocess(lst: List[Dict[str, Any]]) -> Counter:
        """
        Remove 'Id' from each dictionary, convert to a hashable canonical form,
        and return a multiset (Counter) of the processed dictionaries.
        """
        processed = []
        for d in lst:
            # Create a shallow copy minus the 'Id' key
            new_d = {k: v for k, v in d.items() if k != 'Id'}
            processed.append(make_hashable(new_d))
        return Counter(processed)

    return preprocess(a) == preprocess(b)

