import sys

class LRUCache(OrderedDict):
    def __init__(self, maxsize=100000):
        super().__init__()
        self.maxsize = maxsize

    def __setitem__(self, key, value):
        if key in self:
            self.move_to_end(key)
        super().__setitem__(key, value)
        if len(self) > self.maxsize:
            self.popitem(last=False)

def lru_cache_for_fibonacci(maxsize=100000):
    cache = LRUCache(maxsize=maxsize)
    def decorator(func):
        def wrapper(n):
            if n in cache:
                return cache[n]
            result = func(n)
            cache[n] = result
            return result
        return wrapper
    return decorator

@lru_cache_for_fibonacci(maxsize=100000)
def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

