class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.parent = None

def build_tree(n, nodes_info):
    nodes = [None] + [Node(0) for _ in range(n)]  # 1-based index
    # Fill in values first
    for i in range(1, n+1):
        val, left, right, parent = nodes_info[i-1]
        nodes[i].val = val
    # Link children and parents
    for i in range(1, n+1):
        val, left, right, parent = nodes_info[i-1]
        if left:
            nodes[i].left = nodes[left]
        if right:
            nodes[i].right = nodes[right]
        if parent:
            nodes[i].parent = nodes[parent]
    root = None
    for i in range(1, n+1):
        val, left, right, parent = nodes_info[i-1]
        if parent == 0:
            root = nodes[i]
            break
    return root

def tree_to_circular_doubly_linked_list(root):
    if not root:
        return None
    first, last = None, None
    def convert(node):
        nonlocal first, last
        if not node:
            return
        convert(node.left)
        if last:
            last.right = node
            node.left = last
        else:
            first = node
        last = node
        convert(node.right)
    convert(root)
    # Make it circular
    last.right = first
    first.left = last
    return first

