            is_cycle = True
            while queue:
                cur = queue.popleft()
                if deg[cur] != 2:
                    is_cycle = False
                for nxt in adj[cur]:
                    if not visited[nxt]:
                        visited[nxt] = True
                        queue.append(nxt)
            if is_cycle:
