import sys
import re

def clean_string(s):
    # Remove HTML-like tags
    s = re.sub(r'<[^>]*>', '', s)
    # Remove content within any type of bracket (handles nesting)
    def remove_bracketed(text):
        stack = []
        to_remove = [False] * len(text)
        pairs = {'(': ')', '[': ']', '{': '}'}
        opens = set(pairs.keys())
        closes = set(pairs.values())
        brackets = pairs.copy()
        brackets.update({v: k for k, v in pairs.items()})
        for i, ch in enumerate(text):
            if ch in opens:
                stack.append((ch, i))
            elif ch in closes:
                for j in range(len(stack) - 1, -1, -1):
                    if pairs.get(stack[j][0], None) == ch:
                        # Mark from opening to closing as remove
                        open_br, open_idx = stack[j]
                        for k in range(open_idx, i+1):
                            to_remove[k] = True
                        stack.pop(j)
                        break
        return ''.join(c for i, c in enumerate(text) if not to_remove[i])
    s = remove_bracketed(s)
    # Keep only alphanumeric characters, ignoring case, and respecting unicode
    s = ''.join(c.lower() for c in s if c.isalnum())
    return s

def main():
    s = sys.stdin.read().rstrip('\n')
    cleaned_s = clean_string(s)
