    // Method to calculate the LCM
    public static int lcm(int num1, int num2) {
        int lcm = (num1 > num2) ? num1 : num2;

        while(true) {
            if( lcm % num1 == 0 && lcm % num2 == 0 ) {
                break;
            }
            ++lcm;
        }
        return lcm;
    }
}
