def is_valid_email(email):
    # Standard email pattern, simplified
    pattern = re.compile(r'^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$')
    if not pattern.match(email):
        return False
    local = email.split('@')[0]
    if local.startswith('.'):  # Leading dot
        return False
    if '..' in local:  # Consecutive dots in local
        return False
    if '..' in email:  # Consecutive dots anywhere (should not be in domain either)
        return False
    return True

