sub convert_to_base {
    # Perl do not have functions like bin, oct, hex in Python
    # We use sprintf to convert to binary, octal and hexadecimal
    my ($arg, $base) = @_;
    my @conversion_functions = ('%b', '', '', '', '', '', '', '', '%o', '', '%x');
    return sprintf($conversion_functions[$base], $arg);
}

sub operation_result {
    my ($a, $b, $start, $operation, $base) = @_;

    # Check the validity of the arguments
    if ($a > $b || $start < 0 || $base < 2 || $base > 10 || ($operation ne '+' and $operation ne '*')) {
