import sys

def is_perfectly_balanced(s: str) -> bool:
    # Collect distinct characters appearing in s
    uniq = sorted(set(s))

    # Strings with only one distinct character are always balanced
    if len(uniq) == 1:
        return True

    # For every unordered pair (u, v) of distinct characters in s
    for i in range(len(uniq)):
        for j in range(i + 1, len(uniq)):
            u, v = uniq[i], uniq[j]
            prev = None  # previous occurrence among u or v
            for c in s:
                if c == u or c == v:
                    if c == prev:      # same as previous → two consecutive equal letters after filtering
                        return False   # violates the condition
                    prev = c
    return True

