            int index = c - 'a';
            if(pCrawl.children[index] == null)
                return false;

            pCrawl = pCrawl.children[index];
        }

        if(pCrawl != null && pCrawl.isEndOfWord) {
            pCrawl.isEndOfWord = false;
            return true;
        }

        return false;
    }

