class Node:
    def __init__(self, data):
        self.data = data
        self.next = None
        self.prev = None

class NumberList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def add(self, number):
        new_node = Node(number)
        if not self.head:
            self.head = new_node
            self.tail = new_node
        else:
            self.tail.next = new_node
            new_node.prev = self.tail
            self.tail = new_node
        self.size += 1

    def get(self, index):
        if index < 0 or index >= self.size:
            raise IndexError()
        current = self.head
        for _ in range(index):
            current = current.next
        return current.data

