Given a JSON object (Python dictionary) that may contain nested dictionaries and lists, write a program to flatten it into a one-dimensional dictionary. The flattened dictionary should use dot notation to indicate nesting. If a key contains a list, the index of the element in the list becomes part of the key, separated by a dot. For example:

Input:
{'a': [1, {'b': 2}]}

Output:
{'a.0': 1, 'a.1.b': 2}

Input Format:
- The input is a single line containing a JSON object.

Output Format:
- Output a single line containing the flattened dictionary using Python's standard dictionary string representation.

Examples:
Input:
{"a": [1, {"b": 2}]}

Output:
{'a.0': 1, 'a.1.b': 2}

Input:
{"a": {"b": {"c": 3}}, "d": 4}

Output:
{'a.b.c': 3, 'd': 4}

import json
import sys

def flatten_dict(d, parent_key='', sep='.'):  # d is always a dict
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        elif isinstance(v, list):
            for i, elem in enumerate(v):
                if isinstance(elem, dict):
                    items.extend(flatten_dict(elem, f"{new_key}.{i}", sep=sep).items())
                else:
                    items.append((f"{new_key}.{i}", elem))
        else:
            items.append((new_key, v))
    return dict(items)

def main():
    input_line = sys.stdin.read().strip()
    data = json.loads(input_line)
    flat = flatten_dict(data)
    print(flat)

if __name__ == "__main__":
    main()

