function decomposeAndSort(arr, sizes) {
    if (!Array.isArray(arr) || !Array.isArray(sizes)) {
        throw new Error("Both inputs should be arrays.");
    }

    if (sizes.some(size => size <= 0)) {
        throw new Error("Sizes should be greater than 0.");
    }

    const flattenedArr = [].concat(...arr);

    if (flattenedArr.some(element => typeof element !== 'number')) {
        throw new Error("All array elements should be numbers.");
    }

    let result = [];
    let index = 0;

    for(let i = 0; i < sizes.length; i++){
        let subset = flattenedArr.slice(index, index + sizes[i]);
        subset.sort((a, b) => b - a);

        if (subset.length !== sizes[i]) {
            throw new Error("Size of the subset and given size don't match. Check your input.");
        }

        result.push(subset);
        index += sizes[i];
    }

    return result;
}
```
