import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_carmichael(n):
    if is_prime(n) or n <= 1:
        return False
    # For Carmichael numbers (Korselt's criterion is optimal, but for a few inputs a naive check suffices)
    # For large n, this is very slow, but for the problem's constraints (<=100 numbers), we keep this demo.
    for a in range(2, min(n, 100)):
        if math.gcd(a, n) == 1 and pow(a, n-1, n) != 1:
            return False
    return True

