class Warrior:
    def __init__(self):
        self.experience = 100
        self.achievements = []

    @property
    def level(self):
        # level 1 for 100 exp; +1 level every additional 100 exp
        return min(100, (self.experience - 100) // 100 + 1)

    @property
    def rank(self):
        ranks = [
            "Pushover", "Novice", "Fighter", "Warrior", "Veteran",
            "Sage", "Elite", "Conqueror", "Champion", "Master", "Greatest"
        ]
        return ranks[self.level // 10]

    def _add_exp(self, amount):
        self.experience = min(10000, self.experience + amount)

    # ---------------- battle -----------------
    def battle(self, enemy_level):
        if not 1 <= enemy_level <= 100:
            return "Invalid level"

        my_level = self.level
        my_rank  = my_level // 10
        enemy_rank = enemy_level // 10

        if enemy_rank > my_rank and enemy_level - my_level >= 5:
            return "You've been defeated"

        # experience calculation
        if enemy_level == my_level:
            gained = 10
        elif enemy_level == my_level - 1:
            gained = 5
        elif enemy_level <= my_level - 2:
            gained = 0
        else:  # enemy stronger
            diff = enemy_level - my_level
            gained = 20 * diff * diff

        self._add_exp(gained)

        # message
        curr_level = self.level  # after exp update
        if curr_level >= enemy_level + 2:
            return "Easy fight"
        elif curr_level >= enemy_level:
            return "A good fight"
        else:
            return "An intense fight"

    # ---------------- training ---------------
    def training(self, info):
        desc, exp_gain, min_level = info
        if self.level >= min_level:
            self._add_exp(exp_gain)
            self.achievements.append(desc)
            return desc
        else:
            return "Not strong enough"

# --------------- I/O handling ----------------

def main():
    import sys
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    Q = int(lines[0].strip())
    w = Warrior()
    out_lines = []
    for i in range(1, Q + 1):
        line = lines[i].rstrip("\n")
        if line.startswith("battle"):
            # format: battle L
            _, lvl_str = line.split()
            res = w.battle(int(lvl_str))
            out_lines.append(res)
        elif line.startswith("training"):
            # format: training;description;exp;min_level
            parts = line.split(';', 3)
            if len(parts) != 4:
                out_lines.append("Invalid training command")
                continue
            _, desc, exp_str, lvl_req_str = parts
            res = w.training([desc, int(exp_str), int(lvl_req_str)])
            out_lines.append(res)
        else:
            out_lines.append("Invalid command")
    sys.stdout.write("\n".join(out_lines) + "\n")

