Here is C++ code to calculate the Standard Deviation and Interquartile Range:

```c++
#include<iostream>
#include<cmath>
#include<vector>
#include<algorithm>
using namespace std;

double calc_median(vector<int> numbers){
    int n = numbers.size();
    sort(numbers.begin(), numbers.end());
    if(n % 2 != 0) 
        return (double)numbers[n / 2]; 
    else
        return (double)(numbers[(n - 1) / 2] + numbers[n / 2]) / 2.0; 
}

void calculate_ranges(vector<int> integers){
    int n = integers.size();
    if (n == 0){
        cout << "Standard Deviation and IQR cannot be calculated for an empty array." << endl;
        return;
    }

    double mean = accumulate(integers.begin(), integers.end(), 0) / n ;
    double sum_deviation = 0.0;
    for(int i = 0; i < n; ++i)
       sum_deviation += (integers[i] - mean) * (integers[i] - mean);

    double SD = sqrt(sum_deviation / n); 
    cout << "Standard Deviation : " << SD << endl;

    vector<int> lower_half;
    vector<int> upper_half;

    sort(integers.begin(), integers.end());

    if(n%2 != 0){
        lower_half = vector<int>(integers.begin(), integers.begin() + n/2);
        upper_half = vector<int>(integers.begin() + n/2 + 1, integers.end());
    } else {
        lower_half = vector<int>(integers.begin(), integers.begin() + n/2);
        upper_half = vector<int>(integers.begin() + n/2, integers.end());
    }
    double IQR = calc_median(upper_half) - calc_median(lower_half);  
    cout << "Interquartile Range : " << IQR << endl;
}

int main(){
    //Test the function on a vector.
    vector<int> numbers = {1,3,4,5,5,6,7,8,10,12,13,14,15,16,17};
    calculate_ranges(numbers);
    return 0;
}
```

