Next is how to update a customer's status based on their transaction history. We'll need a function to make that happen:

```javascript
const updateCustomerStatus = async (customerId) => {
  const customer = await Customer.findByPk(customerId);
  const transactions = await customer.getTransactions();
  const totalAmount = transactions.reduce((total, transaction) => total + transaction.purchase_amount, 0);
  const now = new Date();

  if (totalAmount > VIP_LIMIT) {
    customer.status = 'VIP';
  } else if (transactions[transactions.length - 1].purchase_date < now.setMonth(now.getMonth() - 1)) {
    customer.status = 'inactive';
  } else if (transactions.length > RECENT_LIMIT) {
    customer.status = 'active';
  } else {
    customer.status = 'recent';
  }

  await customer.save();
}
