We can achieve this by transforming the expression into a Reverse Polish Notation (RPN) form and then evaluate it. RPN is a mathematical notation in which every operator follows all of its operands.

Here is the Python solution:

```python
from __future__ import division
from collections import deque
import re

def parse(expr):
    tokens = deque(re.findall(r'\d+|\+|\-|\*|\/|\(|\)', expr))
    output = []
    operators = {'+': 0, '-': 0, '*': 1, '/': 1}
    stack = []
    for token in tokens:
        if re.match(r'\d+', token):
            output.append(int(token))
        elif token in operators:
            while stack and stack[-1]!='(' and operators[token] <= operators[stack[-1]]:
                output.append(stack.pop())
            stack.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack[-1]!='(':
                output.append(stack.pop())
            stack.pop()
    while stack:
        output.append(stack.pop())
    return output

def calc(expr):
    rpn = parse(expr)
    stack = []
    for token in rpn:
        if type(token) == int:
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a+b)
            elif token == '-':
                stack.append(a-b)
            elif token == '*':
                stack.append(a*b)
            elif token == '/':
                stack.append(a/b)
    return stack[0]

# Test cases
print(calc("3 + 4 * 9")) # 39
print(calc("3 * (4 + 9)")) # 39
print(calc("10 + 5 * 6")) # 40
print(calc("(3 + 4) * 9")) # 63
print(calc("2 * (4 + 5) - 3")) # 15
```

In this script, the `calc` function converts the expression into Reverse Polish Notation using the `parse` function first, then it applies all the operations from the resulting list.

It is worth noting that the division is the "true" division. For floor division, change the "/" case in the calc function to `stack.append(a//b)`.

