def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

import sys

def process_card_input(card_str):
    cleaned = []
    i = 0
    length = len(card_str)
    # Only digit '1', digits, '(', ')' remain in cleaned
    while i < length:
        ch = card_str[i]
        if ch == '1' or ch.isdigit() or ch in '()':
            cleaned.append(ch)
        i += 1
    cleaned_str = ''.join(cleaned)
    # Collapse consecutive '1's into a single '1'
    result = []
    i = 0
    while i < len(cleaned_str):
        if cleaned_str[i] == '1':
            result.append('1')
            while i + 1 < len(cleaned_str) and cleaned_str[i+1] == '1':
                i += 1
            i += 1
        else:
            result.append(cleaned_str[i])
            i += 1
    # Now, parse result into digits/parentheses groups
    digits = []
    i = 0
    while i < len(result):
        if result[i] == '(':  # start of parenthesis
            j = i + 1
            while j < len(result) and result[j] != ')':
                j += 1
            if j < len(result):
                digits.append('(' + ''.join(result[i+1:j]) + ')')
                i = j + 1
            else:
                # unmatched '(' - just ignore
                i += 1
        else:
            digits.append(result[i])
            i += 1
    return digits

def get_digit(dig):
    if dig.isdigit():
        return int(dig)
    elif dig.startswith('(') and dig.endswith(')'):
        try:
            num = int(dig[1:-1])
            return num if is_prime(num) else 0
        except:
            return 0
    return 0

def luhn_algorithm(digits):
    nums = [get_digit(d) for d in digits]
    n = len(nums)
    total = 0
    odd = n % 2 == 0  # if even length, double even indexed
    for i in range(n):
        num = nums[i]
        if ((i % 2 == 0) == odd):
            doubled = num * 2
            total += doubled if doubled < 10 else doubled - 9
        else:
            total += num
    return total % 10 == 0

def main():
    card_str = sys.stdin.readline().rstrip('\n')
    digits = process_card_input(card_str)
    if luhn_algorithm(digits):
        print('True')
    else:
        print('False')

