def case_insensitive_compare(a, b):
    a_lower = ""
    b_lower = ""
    for ch in a:
        if 'A' <= ch <= 'Z':
            a_lower += chr(ord(ch) + 32)
        else:
            a_lower += ch
    for ch in b:
        if 'A' <= ch <= 'Z':
            b_lower += chr(ord(ch) + 32)
        else:
            b_lower += ch
    # Manual lex comparison
    i = 0
    while i < len(a_lower) and i < len(b_lower):
        if a_lower[i] < b_lower[i]:
            return -1
        elif a_lower[i] > b_lower[i]:
            return 1
        i += 1
    if len(a_lower) < len(b_lower):
        return -1
    elif len(a_lower) > len(b_lower):
        return 1
    return 0

