def flatten_dict(d: dict) -> dict:
    """
    Flatten a nested dictionary.  

    Keys in the resulting dictionary represent the
    path from the root to each value in the original dictionary,
    separated by '/'.

    • Scalar values (str, int, etc.) become the leaf values.  
    • If a value is an empty dictionary, it is kept as an empty‐dict value
      in the flattened result.  

    Example
    -------
    >>> data = {
    ...     "a": 1,
    ...     "b": {
    ...         "c": 2,
    ...         "d": {
    ...             "e": 3
    ...         },
    ...         "f": {}
    ...     }
    ... }
    >>> flatten_dict(data)
    {'a': 1, 'b/c': 2, 'b/d/e': 3, 'b/f': {}}
    """
    flat = {}

    def _walk(curr: dict, prefix: str = "") -> None:
        for key, value in curr.items():
            path = key if prefix == "" else f"{prefix}/{key}"
            if isinstance(value, dict):
                if value:               # non-empty dict → keep walking
                    _walk(value, path)
                else:                   # empty dict → record it as a value
                    flat[path] = {}
            else:
                flat[path] = value

    _walk(d)
    return flat

def three_sum(nums):
    nums.sort()
    triplets = []
    n = len(nums)
    for i in range(n-2):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == 0:
                triplets.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return triplets

