def is_bipartite(graph):
    color = {}
    def dfs(node):
        for neighbor in graph[node]:
            if neighbor in color:
                if color[neighbor] == color[node]:
                    return False
            else:
                color[neighbor] = 1 - color[node]
                if not dfs(neighbor):
                    return False
        return True
    for node in graph:
        if node not in color:
            color[node] = 0
            if not dfs(node):
                return False
    return True

