def factorial(n, depth=0):
    prefix = '  ' * depth
    if not isinstance(n, int):
        print(f"{prefix}Error: Non-integer input")
        return "Error: Non-integer input"
    if n < 0:
        print(f"{prefix}Error: Negative input")
        return "Error: Negative input"
    if n == 0 or n == 1:
        print(f"{prefix}factorial({n}) = 1")
        return 1
    else:
        print(f"{prefix}factorial({n}) = {n} * factorial({n - 1})")
        result = (n * factorial(n - 1, depth + 1)) % MOD
        print(f"{prefix}Returning {result} for factorial({n})")
        return result

