import json

def flatten(d, parent_key='', sep='_'):
    items = {}
    for k, v in d.items():
        new_key = parent_key + sep + k if parent_key else k
        if isinstance(v, dict):
            items.update(flatten(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

def main():
    import sys
    s = sys.stdin.read().strip()
    if not s:
        print('{}')
        return
    obj = json.loads(s)
    flat = flatten(obj)
    print(json.dumps(flat, separators=(',', ':')))

