class BinaryTreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(root_list):
    if not root_list:
        return None
    root_val = root_list[0]
    if root_val == -1:
        return None
    root = BinaryTreeNode(root_val)
    queue = [root]
    index = 1
    while queue and index < len(root_list):
        current_node = queue.pop(0)
        # Left child
        if index < len(root_list):
            left_val = root_list[index]
            if left_val != -1:
                current_node.left = BinaryTreeNode(left_val)
                queue.append(current_node.left)
            index += 1
        # Right child
        if index < len(root_list):
            right_val = root_list[index]
            if right_val != -1:
                current_node.right = BinaryTreeNode(right_val)
                queue.append(current_node.right)
            index += 1
    return root

def BFS(root):
    if not root:
        return []
    queue = [(root, 0)]
    res = []
    while queue:
        node, level = queue.pop(0)
        if node.val < 0:
            return []
        if len(res) == level:
            res.append([])
        res[level].append(node.val)
        if node.left:
            queue.append((node.left, level + 1))
        if node.right:
            queue.append((node.right, level + 1))
    return res

def main():
    line = input()
    if not line.strip():
        print([])
        return
    vals = [int(x) for x in line.strip().split()]
    root = build_tree(vals)
    res = BFS(root)
    print(res)

if __name__ == '__main__':
