class SimpleCalculator:
    def __init__(self):
        self.history = []

    def _add_to_history(self, a, b, operation, result):
        self.history.append((a, b, operation, result))
        if len(self.history) > 5:
            self.history.pop(0)

    def add(self, a, b):
        result = a + b
        self._add_to_history(a, b, '+', result)
        return result

    def subtract(self, a, b):
        result = a - b
        self._add_to_history(a, b, '-', result)
        return result

    def multiply(self, a, b):
        result = a * b
        self._add_to_history(a, b, '*', result)
        return result

    def divide(self, a, b):
        if b == 0:
            self._add_to_history(a, b, '/', None)
            print('Cannot divide by zero')
            return None
        result = a / b
        self._add_to_history(a, b, '/', result)
        return result

    def get_history(self):
        return self.history

def main():
    calc = SimpleCalculator()
    while True:
        try:
            line = input().strip()
        except EOFError:
            break
        if line == 'exit':
            break
        if line == 'history':
            for a, b, op, res in calc.get_history():
                print(f"{a} {op} {b} = {res}")
            continue
        parts = line.split()
        if len(parts) != 3:
            print('Invalid command')
            continue
        cmd, x, y = parts
        try:
            if '.' in x or '.' in y:
                a = float(x)
                b = float(y)
            else:
                a = int(x)
                b = int(y)
        except ValueError:
            print('Invalid operands')
            continue
        if cmd == 'add':
            print(calc.add(a, b))
        elif cmd == 'subtract':
            print(calc.subtract(a, b))
        elif cmd == 'multiply':
            print(calc.multiply(a, b))
        elif cmd == 'divide':
            res = calc.divide(a, b)
            if res is not None:
                print(res)
        else:
            print('Invalid command')

