from fractions import Fraction

def power(base: float, exp: float) -> float:
    """
    Recursively computes base ** exp without using the ** operator or any of the
    built-in exponentiation helpers (pow, math.pow …).  Works for

        • positive / negative integer exponents
        • positive / negative rational exponents (exp given as float)

    Real results are returned.  
    For fractional exponents the algorithm converts the exponent into a
    (reasonably small) Fraction  a/b  and evaluates

            base ** (a / b)  =  (base ** a) ** (1 / b)
                              =  b-th-root( base ** a )

    The b-th root is obtained with Newton’s method.
    """
    # ───────────────────────────── helpers ──────────────────────────────
    def int_power(x: float, k: int) -> float:
        """Exponentiation-by-squaring for (possibly large) integer k."""
        if k == 0:
            return 1.0
        if k == 1:
            return x
        if k % 2 == 0:
            half = int_power(x, k // 2)
            return half * half
        return x * int_power(x, k - 1)

    def nth_root(value: float, n: int, tol: float = 1e-12, max_iter: int = 10_000) -> float:
        """
        Newton iteration for the real n-th root.
        Raises ValueError for even roots of negative numbers.
        """
        if n <= 0:
            raise ValueError("Root order must be positive.")
        if value == 0:
            return 0.0
        if value < 0:
            if n % 2 == 0:
                raise ValueError("Even root of negative number is not real.")
            # odd root of negative number:  root(-a) = -root(a)
            return -nth_root(-value, n, tol, max_iter)

        # initial guess: anything > 0 works; heuristically:
        x = value / n if value > 1 else 1.0

        for _ in range(max_iter):
            prev = x
            # x_{k+1} = ((n-1)*x_k + value / x_k^{n-1}) / n
            x = ((n - 1) * x + value / int_power(x, n - 1)) / n
            if abs(x - prev) < tol:
                break
        return x

    # ───────────────────────── main routine ────────────────────────────
    # special cases involving zero
    if exp == 0:
        return 1.0
    if base == 0:
        if exp > 0:
            return 0.0
        raise ValueError("0 cannot be raised to a non-positive power.")

    # handle negative exponent via reciprocal
    if exp < 0:
        return 1.0 / power(base, -exp)

    # integer exponent -----------------------------
    if float(exp).is_integer():
        return int_power(base, int(exp))

    # fractional/real exponent ---------------------
    # approximate the exponent as a rational number a/b
    frac = Fraction(exp).limit_denominator(1000)    # adjustable accuracy
    a, b = frac.numerator, frac.denominator

    # step 1: raise to the integer numerator
    num_result = int_power(base, a)

    # step 2: take the b-th root
    return nth_root(num_result, b)

