def median(l: list):
    """Returns the median of the elements in the list l without sorting it. 
    It should take care of duplicates, even and odd number of elements, invalid inputs, negative numbers and large numbers.
    """

    if not l:
        raise ValueError("List cannot be empty")

    for el in l:
        if not isinstance(el, (int, float)):
            raise TypeError("Invalid input")

    l = list(set(l))   # Remove duplicates
    l_len = len(l)

    if l_len == 1:
