double median(const std::vector<double>& vec) {

    if (vec.empty()) {
        throw std::invalid_argument("Vector cannot be empty");
    }

    std::set<double> s(vec.begin(), vec.end());
    std::vector<double> l(s.begin(), s.end());

    int l_len = l.size();

    if (l_len == 1) {
        return l[0];
    }

    std::sort(l.begin(), l.end());

    double median;

    if (l_len % 2 == 0) {
        double median1 = l[l_len/2];
        double median2 = l[l_len/2 - 1];
        median = (median1 + median2)/2;
    } else {
        median = l[l_len/2];
    }

    return median;
}
