def lucas_number(n, memo={}):
    if n in memo:
        return memo[n]
    if n == 0:
        return 2
    elif n == 1:
        return 1
    memo[n] = lucas_number(n - 1, memo) + lucas_number(n - 2, memo)
    return memo[n]

