function heron_triangle_area(a, b, c) {
    let s = (a + b + c) / 2;
    let area = Math.sqrt(s * (s - a) * (s - b) * (s - c));
    return area;
}

function triangle_perimeter(a, b, c) {
    return a + b + c;
}

function triangle_inradius(a, b, c) {
    let area = heron_triangle_area(a, b, c);
    let perimeter = triangle_perimeter(a, b, c);
    let inradius = 2 * area / perimeter;
    return inradius;
