        self.val = value
        self.left = None
        self.right = None

def build_tree(node_descriptions):
    n = len(node_descriptions)
    if n == 0:
        return None
    nodes = [Node(value) for value, l, r in node_descriptions]
    for idx, (value, l, r) in enumerate(node_descriptions):
        if l != -1:
            nodes[idx].left = nodes[l]
        else:
            nodes[idx].left = None
        if r != -1:
            nodes[idx].right = nodes[r]
        else:
            nodes[idx].right = None
    return nodes[0]

def tree_to_circular_doubly_linked_list(root):
    if not root:
        return None
    def _helper(node):
        nonlocal head, tail
        if not node:
            return
        _helper(node.left)
        if tail is None:
            head = node
        else:
            node.left = tail
            tail.right = node
        tail = node
        _helper(node.right)
    head, tail = None, None
    _helper(root)
    tail.right = head
    head.left = tail
    return head

