def count_distinct_lower(s):
    def is_prime(n):
        """helper function to check if a number is prime"""
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    lower_set = set()
    vowels = set('aeiou')
    for i in range(len(s)):
        if is_prime(i) and s[i].islower() and s[i] not in vowels:
            lower_set.add(s[i])
    return len(lower_set)

