import json

def serialize(tree):
    if not tree:
        return "null"
    result, queue = [], [tree]
    while queue:
        node = queue.pop(0)
        if node is None:
            result.append("null")
        else:
            result.append(str(node['value']))
            queue.append(node.get('left'))
            queue.append(node.get('right'))
    while result and result[-1] == "null":
        result.pop()
    return ",".join(result)

def deserialize(data):
    if data == "null":
        return None
    data = data.split(",")
    root = {"value": int(data[0]), "left": None, "right": None}
    queue = [root]
    i = 1
    while i < len(data):
        parent = queue.pop(0)
        if data[i] != "null":
            parent["left"] = {"value": int(data[i]), "left": None, "right": None}
            queue.append(parent["left"])
        i += 1
        if i < len(data) and data[i] != "null":
            parent["right"] = {"value": int(data[i]), "left": None, "right": None}
            queue.append(parent["right"])
        i += 1
    return root

def main():
