def search(lst, target, path=None):
    if path is None:
        path = []
    if lst == target:
        return path
    if isinstance(lst, list):
        for i, value in enumerate(lst):
            result = search(value, target, path + [i])
            if result != -1:
                return result
    elif isinstance(lst, tuple):
        for i, value in enumerate(lst):
            result = search(value, target, path + [i])
            if result != -1:
                return result
    elif isinstance(lst, dict):
        for key, val in lst.items():
            result = search(val, target, path + [key])
            if result != -1:
                return result
    elif hasattr(lst, '__dict__'):
        for key, val in lst.__dict__.items():
            result = search(val, target, path + [key])
            if result != -1:
                return result
    if lst == target:
        return path
    return -1

