def generate_concept_diagram(concept_connections):
    # Create a dictionary to store the parent-child relationships
    relationships = {}

    # Iterate through the connections and build the relationships dictionary
    for parent, child in concept_connections:
        if parent not in relationships:
            relationships[parent] = []
        relationships[parent].append(child)

    # Function to generate the diagram recursively
    def generate_diagram(concept, indent=''):
        diagram = f"{indent}{concept}\n"
        if concept in relationships:
            children = relationships[concept]
            for child in children:
                diagram += f"{indent} └── {generate_diagram(child, indent + ' │   ')}"
        return diagram

    # Generate the diagram for the root concept (the one without a parent)
    root_concept = None
    for concept in relationships:
        if not any(concept in children for children in relationships.values()):
            root_concept = concept
            break

    if root_concept is None:
        return "No valid root concept found"

    diagram = generate_diagram(root_concept)
    return diagram

