class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def detect_and_break_cycle(head):
    if not head or not head.next:
        return head
    slow, fast = head, head
    has_cycle = False
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            has_cycle = True
            break
    if not has_cycle:
        return head
    slow = head
    while slow != fast:
        slow = slow.next
        fast = fast.next
    last_node = slow
    while last_node.next != slow:
        last_node = last_node.next
    last_node.next = None
    return head

def reverse_tail(current, prev=None):
    if not current:
        return prev
    next_node = current.next
    current.next = prev
    return reverse_tail(next_node, current)

def print_list(head):
    vals = []
    while head:
        vals.append(str(head.val))
        head = head.next
    print(' '.join(vals))

def build_linked_list(n, vals, cycle_at):
    if n == 0:
        return None
    nodes = []
    head = ListNode(vals[0])
    nodes.append(head)
    current = head
    for val in vals[1:]:
        node = ListNode(val)
        current.next = node
        current = node
        nodes.append(node)
    if cycle_at != -1 and 0 <= cycle_at < n:
        current.next = nodes[cycle_at]
    return head

def main():
