class Node:
    def __init__(self, value, min_value):
        self.value = value
        self.min_value = min_value
        self.prev = None
        self.next = None

class MinStack:
    def __init__(self):
        self.top = None
        self.bottom = None
        self.size = 0
        self.min_value = float('inf')

    def push(self, item):
        new_min = min(item, self.min_value)
        new_node = Node(item, new_min)
        if not self.top:
            self.top = self.bottom = new_node
        else:
            new_node.prev = self.top
            self.top.next = new_node
            self.top = new_node
        self.min_value = new_min
        self.size += 1

    def pop(self):
        if not self.top:
            return 'Empty'
        item = self.top.value
        self.top = self.top.prev
        if self.top:
            self.top.next = None
            self.min_value = self.top.min_value
        else:
            self.min_value = float('inf')
            self.bottom = None
        self.size -= 1
        return str(item)

    def peek(self):
        if not self.top:
            return 'Empty'
        return str(self.top.value)

    def isEmpty(self):
        return str(self.size == 0)

    def getMin(self):
        if self.size == 0:
            return 'Empty'
        return str(self.min_value)

    def popMin(self):
        if not self.top:
            return 'Empty'
        if self.min_value == float('inf'):
            return 'Empty'
        temp_stack = []
        target_min = self.min_value
        while self.top and self.top.value != target_min:
            temp_stack.append(self.pop())
        min_element = self.pop()  # Remove the actual min element
        for item in reversed(temp_stack):
            self.push(int(item))
        return str(min_element)

    def getSize(self):
        return str(self.size)

def main():
