def find_common_elements_recursive(l1, l2, idx=0, seen=None, res=None):
    if seen is None:
        seen = []
    if res is None:
        res = []
    if idx == len(l1):
        return res
    elem = l1[idx]
    # Check if elem in l2 (no set, no loops) and not in seen
    def in_list(lst, v, i=0):
        if i == len(lst):
            return False
        if lst[i] == v:
            return True
        return in_list(lst, v, i+1)
    if in_list(l2, elem) and not in_list(seen, elem):
        seen.append(elem)
        res.append(elem)
    return find_common_elements_recursive(l1, l2, idx+1, seen, res)

