class Node:
    def __init__(self, value, cumsum, minval, next_node):
        self.value = value
        self.cumulative_sum = cumsum
        self.min_value = minval
        self.next = next_node

class CumulativeStack:
    def __init__(self):
        self.top = None
        self.stack_size = 0

    def push(self, value):
        if self.top is None:
            node = Node(value, value, value, None)
        else:
            node = Node(value, self.top.cumulative_sum + value, min(value, self.top.min_value), self.top)
        self.top = node
        self.stack_size += 1

    def pop(self):
        if self.top is None:
            print("Stack is empty")
        else:
            print(self.top.value)
            self.top = self.top.next
            self.stack_size -= 1

    def peek(self):
        if self.top is None:
            print("Stack is empty")
        else:
            print(self.top.value)

    def size(self):
        print(self.stack_size)

    def get_cumulative_sum(self):
        print(self.top.cumulative_sum if self.top is not None else 0)

    def get_min_value(self):
        if self.top is None:
            print("Stack is empty")
        else:
            print(self.top.min_value)

