def partition(arr, low, high):
    mid = (low + high) // 2
    trio = [arr[low], arr[mid], arr[high]]
    pivot = sorted(trio)[1]
    # Find actual index of pivot in the range
    for k in (low, mid, high):
        if arr[k] == pivot:
            pivot_index = k
            break
    arr[pivot_index], arr[high] = arr[high], arr[pivot_index]
