```python
from collections import deque

def isCompleteAndValidBST(root):
    isComplete, nodes, idx = True, deque([(root, 1)]), 0

    def helper(node, lower = float('-inf'), upper = float('inf')):
        if not node:
            return True
        val = node.val
        if val <= lower or val >= upper:
            return False

        if not helper(node.left, lower, val):
            return False
        if not helper(node.right, val, upper):
            return False
        return True

    while idx < len(nodes):
        node, v = nodes[idx]
        idx += 1
        if node:
            nodes.append((node.left, 2 * v))
            nodes.append((node.right, 2 * v + 1))

    if nodes[-1][1] != len(nodes): 
        isComplete = False
    return isComplete and helper(root)
```

At the end if `isComplete` is true and the BST validation returns true, only then the function will return true.

