def create_schedule(residents, my_hours):
    schedule = {}
    total_available_hours = sum(hours for _, hours in residents)

    if my_hours > total_available_hours:
        my_hours = total_available_hours

    for name, available_hours in residents:
        schedule[name] = min(available_hours, my_hours // len(residents))
        my_hours -= schedule[name]

    remaining_hours = my_hours
    for name, _ in sorted(residents, key=lambda x: x[1], reverse=True):
        if remaining_hours == 0:
            break
        if schedule[name] < residents[residents.index((name, _))][1]:
            schedule[name] += 1
            remaining_hours -= 1

    return schedule

