class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class CircularDoublyLinkedList:
    def __init__(self):
        self.head = None

    def add(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            self.head.next = self.head
            self.head.prev = self.head
        else:
            tail = self.head.prev
            tail.next = new_node
            new_node.prev = tail
            new_node.next = self.head
            self.head.prev = new_node

    def remove(self, value):
        if not self.head:
            return
        current = self.head
        while current.data != value:
            current = current.next
            if current == self.head:
                return
        # Found the node to delete:
        if current.next == current:
            self.head = None
        else:
            prev_node = current.prev
            next_node = current.next
            prev_node.next = next_node
            next_node.prev = prev_node
            if current == self.head:
                self.head = next_node

    def display(self):
        if not self.head:
            print("List is empty")
            return
        current = self.head
        elems = []
        while True:
            elems.append(str(current.data))
            current = current.next
            if current == self.head:
                break
        print(' '.join(elems))

