// Helper function to calculate Area of a triangle
func triangleArea(x1, y1, x2, y2, x3, y3 float64) float64 {
	return math.Abs((x1*(y2-y3) + x2*(y3-y1) + x3*(y1-y2))) / 2.0
}

// Function to calculate Area of a complex shape
func complexShapeArea(coordinates []Coordinate) float64 {
	area := 0.0
	n := len(coordinates)  // number of vertices

	for i := 0; i < n; i++ {
		x1, y1 := coordinates[i].X, coordinates[i].Y
		x2, y2 := coordinates[(i+1)%n].X, coordinates[(i+1)%n].Y // the "% n" wraps index around
		x3, y3 := coordinates[(i+2)%n].X, coordinates[(i+2)%n].Y
		area += triangleArea(x1, y1, x2, y2, x3, y3)
	}
	return area
}

