import sys
from datetime import datetime, timedelta

class BankAccount:
    def __init__(self):
        self.balance = 0
        self.transaction_log = []
        self.transaction_id = 0
        self._fake_time = datetime(2023,12,1,10,0,0)  # For deterministic output
    def _next_time(self):
        t = self._fake_time
        self._fake_time += timedelta(minutes=5)
        return t
    def deposit(self, amount):
        self.balance += amount
        self.transaction_id += 1
        self.transaction_log.append({
            'id': self.transaction_id,
            'type': 'deposit',
            'amount': amount,
            'timestamp': self._next_time()
        })
    def withdraw(self, amount):
        if self.balance - amount < 0:
            return False
        self.balance -= amount
        self.transaction_id += 1
        self.transaction_log.append({
            'id': self.transaction_id,
            'type': 'withdrawal',
            'amount': -amount,
            'timestamp': self._next_time()
        })
        return True
    def get_balance(self):
        return self.balance
    def get_transaction_log(self):
        return sorted(self.transaction_log, key=lambda x: x['timestamp'])

