def recursive_min_max(sublist):
    if len(sublist) == 1:
        return sublist[0], sublist[0], 1, 1
    elif len(sublist) == 2:
        if sublist[0] < sublist[1]:
            return sublist[0], sublist[1], 1, 1
        elif sublist[0] > sublist[1]:
            return sublist[1], sublist[0], 1, 1
        else:
            return sublist[0], sublist[1], 2, 2
    mid = len(sublist) // 2
    min1, max1, count_min1, count_max1 = recursive_min_max(sublist[:mid])
    min2, max2, count_min2, count_max2 = recursive_min_max(sublist[mid:])
    if min1 < min2:
        min_value, count_min = min1, count_min1
    elif min1 > min2:
        min_value, count_min = min2, count_min2
    else:
        min_value, count_min = min1, count_min1 + count_min2
    if max1 > max2:
        max_value, count_max = max1, count_max1
    elif max1 < max2:
        max_value, count_max = max2, count_max2
    else:
        max_value, count_max = max1, count_max1 + count_max2
    return min_value, max_value, count_min, count_max

