from itertools import groupby

def is_happy(s):    
    # Rule 1: at least three characters
    if len(s) < 3:
        return False
    # Rule 2: All groups of three consecutive characters are distinct
    if len(set(s[i:i+3] for i in range(len(s)))) < len(s) - 2:
        return False
    # Rule 3: Each character recurs at least three times
    counter = Counter(s)
    if any(value < 3 for value in counter.values()):
        return False
    # Rule 4: No character appears four times successively
    if any(len(list(group)) >= 4 for key, group in groupby(s)):
        return False
    # Rule 5: Each character must alternate with at least two different characters
    for key in counter.keys():
        if len(set(s[i+1] for i in range(len(s) - 1) if s[i] == key)) < 2:
            return False
    return True

Here is how you would write the same function in javascript:

```javascript
function is_happy(s) {
    // Rule 1: at least three characters
    if (s.length < 3) {
        return false;
    }

    // Rule 2: All groups of three consecutive characters are distinct
    let distinctGroups = new Set();
    for (let i = 0; i < s.length - 2; i++) {
        distinctGroups.add(s.substr(i, 3));
    }
    if (distinctGroups.size < s.length - 2) {
        return false;
    }

    // Rule 3: Each character recurs at least three times
    let counter = {};
    for (let i = 0; i < s.length; i++) {
        if (!counter[s[i]]) {
            counter[s[i]] = 0;
        }
        counter[s[i]]++;
    }
    for (let key in counter) {
        if (counter[key] < 3) {
            return false;
        }
    }

    // Rule 4: No character appears four times successively
    for (let i = 0; i < s.length - 3; i++) {
        if (s[i] === s[i+1] && s[i+1] === s[i+2] && s[i+2] === s[i+3]) {
            return false;
        }
    }

    // Rule 5: Each character must alternate with at least two different characters
    for (let key in counter) {
        let adc = new Set();
        for (let i = 0; i < s.length; i++) {
            if (s[i] === key && s[i+1]) {
                adc.add(s[i+1]);
            }
        }
        if (adc.size < 2) {
            return false;
        }
    }
    return true;
}
```
