class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None

def build_list(vals, pos):
    if not vals:
        return None
    head = ListNode(vals[0])
    nodes = [head]
    current = head
    for v in vals[1:]:
        current.next = ListNode(v)
        current = current.next
        nodes.append(current)
    if pos != -1:
        current.next = nodes[pos]
    return head

def hasCycle(head):
    if not head or not head.next:
        return False
    slow, fast = head, head.next
    while slow != fast:
        if not fast or not fast.next:
            return False
        slow = slow.next
        fast = fast.next.next
    return True

