def fib_pair(n):
    """Return (F(n), F(n+1)) modulo MOD using fast-doubling."""
    if n == 0:
        return 0, 1
    a, b = fib_pair(n // 2)          # a = F(k), b = F(k+1)
    c = (a * ((2 * b - a) % MOD)) % MOD  # F(2k)
    d = (a * a + b * b) % MOD            # F(2k+1)
    if n % 2 == 0:
        return c, d
    else:
