def insert_bst(root, x):
    if not root:
        return TreeNode(x)
    if x < root.val:
        root.left = insert_bst(root.left, x)
    else:
        root.right = insert_bst(root.right, x)
    return root

def find_node(root, val):
    while root:
        if val == root.val:
            return root
        elif val < root.val:
            root = root.left
        else:
            root = root.right
    return None

def inorderSuccessor(root, p):
    successor = None
    current = root
    while current:
        if p.val < current.val:
            successor = current
            current = current.left
        elif p.val >= current.val:
            current = current.right
    return successor

