def build_tree(levels):
    if not levels or levels[0] == 'null':
        return None
    root = TreeNode(int(levels[0]))
    queue = [root]
    i = 1
    while queue and i < len(levels):
        current = queue.pop(0)
        if i < len(levels) and levels[i] != 'null':
            current.left = TreeNode(int(levels[i]))
            queue.append(current.left)
        i += 1
        if i < len(levels) and levels[i] != 'null':
            current.right = TreeNode(int(levels[i]))
            queue.append(current.right)
        i += 1
    return root

def zigzagLevelOrder(root):
    if not root:
        return []
    result, queue = [], [(root, 0)]
    while queue:
        level = []
        next_queue = []
        for node, depth in queue:
            level.append((node.val, depth))
            if node.left:
                next_queue.append((node.left, depth + 1))
            if node.right:
                next_queue.append((node.right, depth + 1))
        if len(result) % 2 == 1:
            level.reverse()
        result.append(level)
        queue = next_queue
    return result

