            insert(&((*root)->right), value);
        } 
    }
}

int inBST(BSTNode *root, int value) {
    if (root == NULL) {
        return 0;
    }
    if (root->value == value) {
        return 1;
    } else if (value < root->value) {
        return inBST(root->left, value);
    } else {
        return inBST(root->right, value);
    }
}

// Call this function to set the root to NULL first time before inserting any nodes
void initBST(BSTNode **root){
    *root = NULL;
}
```
In short, this code provides an implementation for a Binary Search Tree (BST) with integers as node values. There are three main functions - insert to add a new value to the tree, inBST to check if a value exists in the tree, and initBST to initialize the BST.

The insert function first checks if the root is NULL (indicating that the tree is empty), in which case it creates a new node and assigns it to the root. If the tree is not empty, it compares the new value with the value at the root, and based on this comparison it recursively calls the insert function for the left or right subtree.

The inBST function checks whether a certain value is in the tree. It performs a search operation similar to the insert function.

The initBST function is used to create an instance of an empty BST.

