import sys
import ast

def flatten_dict(d, parent_key='', seen=None):
    if seen is None:
        seen = set()
    if id(d) in seen:
        raise ValueError("Circular reference detected")
    seen.add(id(d))
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}.{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, seen=seen).items())
        elif isinstance(v, list):
            for i, elem in enumerate(v):
                elem_key = f"{new_key}[{i}]"
                if isinstance(elem, dict):
                    items.extend(flatten_dict(elem, elem_key, seen=seen).items())
                else:
                    items.append((elem_key, elem))
        else:
            items.append((new_key, v))
    seen.remove(id(d))
    return dict(items)

