    if isinstance(item, dict):
        for k, v in item.items():
            if k == key:
                yield v
            if isinstance(v, (dict, list)):
                yield from find_field(v, key)
    elif isinstance(item, list):
        for elem in item:
            yield from find_field(elem, key)

