def classify_url(url):
    spam_keywords = {"promo", "gift", "free", "win"}
    trusted_subdomains = {"example", "legit"}

    # Extract subdomain
    url_body = url.split('//')[-1]
    subdomain = url_body.split('.')[0]

    # Count occurrences of spam keywords
    keyword_count = sum(1 for keyword in spam_keywords if keyword in url)

    is_trusted = any(trusted in subdomain for trusted in trusted_subdomains)

    if keyword_count > 1:
        return "spam"
    elif keyword_count == 1 and is_trusted:
        return "not spam"
    elif keyword_count > 0:
        return "spam"
    else:
        return "not spam"

