def string_xor_alternating_subseq(a: str, b: str) -> str:
    result = []
    for i in range(len(a)):
        result.append(str(int(a[i]) ^ int(b[i])))
    result = ''.join(result)

    longest_subseq = ''
    current_subseq = ''
    prev_char = None

    for char in result:
        if prev_char != char:
            current_subseq += char
        else:
            if len(current_subseq) > len(longest_subseq):
                longest_subseq = current_subseq
            current_subseq = char
        prev_char = char

    if len(current_subseq) > len(longest_subseq):
        longest_subseq = current_subseq

    return longest_subseq

