public class MainClass {
    public static void Main() {
        Console.WriteLine(BelowZero(new List<object>{1, 2, 3}));  // false
        Console.WriteLine(BelowZero(new List<object>{1, 2, -4, 5}));  // true
        Console.WriteLine(BelowZero(new List<object>{1, 2, -3.5}, true));  // true
