    public static bool BelowZero(List<object> operations, bool handleFloat = false) {
        double balance = 0;

        foreach (object op in operations) {
            // If handleFloat == false and op is float, skip the operation
            if (!handleFloat && op is double)
                continue;

            // Add op into balance
            balance += Convert.ToDouble(op);

            // If balance < 0, return true
            if (balance < 0) 
                return true;
        }

        return false;
    }
}
