class Library:
    def __init__(self):
        self.books = []

    def add_book(self, title, author, year):
        if not any(book[0].lower() == title.lower() and book[1].lower() == author.lower() for book in self.books):
            self.books.append((title, author, year))

    def remove_book(self, title):
        self.books = [book for book in self.books if book[0].lower() != title.lower()]

    def search_by_title(self, title):
        return [book for book in self.books if title.lower() in book[0].lower()]

    def search_by_author(self, author):
        return [book for book in self.books if author.lower() in book[1].lower()]

    def list_books(self):
        return sorted(self.books, key=lambda book: book[0].lower())

    def list_books_after_year(self, year):
        return [book for book in self.books if book[2] > year]

def main():
    library = Library()
    while True:
        try:
            line = input()
        except EOFError:
            break
        if not line:
            continue
        cmd = line.strip()
        if cmd == 'EXIT':
            break
        elif cmd.startswith('ADD '):
            args = cmd[4:].split(';')
            if len(args) == 3:
                title = args[0].strip()
                author = args[1].strip()
                year = int(args[2].strip())
                library.add_book(title, author, year)
        elif cmd.startswith('REMOVE '):
            title = cmd[7:].strip()
            library.remove_book(title)
        elif cmd.startswith('SEARCH_TITLE '):
            title_sub = cmd[13:].strip()
            for book in library.search_by_title(title_sub):
                print(f"{book[0]};{book[1]};{book[2]}")
        elif cmd.startswith('SEARCH_AUTHOR '):
            author_sub = cmd[14:].strip()
            for book in library.search_by_author(author_sub):
                print(f"{book[0]};{book[1]};{book[2]}")
        elif cmd == 'LIST':
            for book in library.list_books():
                print(f"{book[0]};{book[1]};{book[2]}")
        elif cmd.startswith('LIST_AFTER '):
            try:
                year = int(cmd[11:].strip())
                for book in library.list_books_after_year(year):
                    print(f"{book[0]};{book[1]};{book[2]}")
