from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(nodes):
    if not nodes:
        return None
    tree_nodes = [None if node is None else TreeNode(node[0]) for node in nodes]
    for idx, (val, l_idx, r_idx) in enumerate(nodes):
        if l_idx != -1:
            tree_nodes[idx].left = tree_nodes[l_idx]
        if r_idx != -1:
            tree_nodes[idx].right = tree_nodes[r_idx]
    return tree_nodes[0]

def level_order(root):
    if not root:
        return []
    result = []
    queue = deque([root])
    while queue:
        level_size = len(queue)
        current_level = []
        for _ in range(level_size):
            node = queue.popleft()
            current_level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(current_level)
    return result

def main():
    import sys
    input_lines = sys.stdin.read().splitlines()
    if not input_lines:
        print([])
        return
    N = int(input_lines[0])
    if N == 0:
        print([])
        return
    nodes = []
    for line in input_lines[1:N+1]:
        vals = list(map(int, line.strip().split()))
        nodes.append(vals)
    root = build_tree(nodes)
