```cpp
#include <iostream>
#include <cmath>
using namespace std;

// checking if the number is prime
bool isPrime(int num) {
    if (num <= 1)
        return false;
    if (num == 2)
        return true;
    if (num % 2 == 0)
        return false;
    for(int i = 3; i <= sqrt(num); i += 2) {
        if(num % i == 0)
            return false;
    }
    return true;
}

//calculate factorial
long long factorial(int num) {
    if(num > 1)
        return num * factorial(num - 1);
    else
        return 1;
}

int main() {
    for(int i = 1; i <= 100; i++) {
        if(isPrime(i)) {
            cout << i << " is a prime number, and its factorial is: " << factorial(i) << endl;
        }
    }
    return 0;
}
