def is_isogram(s: str) -> bool:
    # must be a string and not empty
    if not isinstance(s, str):
        return False
    if len(s) == 0:
        return False

    # keep only letters, case-insensitive
    letters = [c for c in s.lower() if c.isalpha()]

    if not letters:  # no letters at all → vacuously every letter occurs the same number of times
        return True

    counts = {}
    for ch in letters:
        counts[ch] = counts.get(ch, 0) + 1

    values = list(counts.values())
    first = values[0]
    return all(v == first for v in values)


