def remove_html_tags(html):
    result = []
    tag_stack = []
    script_tag_counter = 0
    buffer = []
    i = 0
    while i < len(html):
        char = html[i]
        if char == '<':
            buffer_text = ''.join(buffer)
            if script_tag_counter == 0:
                result.append(buffer_text)
            buffer.clear()
            if i + 1 < len(html) and html[i + 1] == '/':
                is_closing_tag = True
                start_tag_end_index = i + 2
            else:
                is_closing_tag = False
                start_tag_end_index = i + 1
            j = start_tag_end_index
            while j < len(html) and html[j] not in ('>', ' ', '\t', '\n', '\r'):
                j += 1
            tag_name = html[start_tag_end_index:j].lower()
            if tag_name == 'script':
                if is_closing_tag:
                    if script_tag_counter > 0:
                        script_tag_counter -= 1
                else:
                    script_tag_counter += 1
            while j < len(html) and html[j] != '>':
                j += 1
            i = j
        else:
            buffer.append(char)
        i += 1
    buffer_text = ''.join(buffer)
    if script_tag_counter == 0:
        result.append(buffer_text)
    return ''.join(result).replace('\n', '').replace('\t', '').replace('\r', '')

