def can_form_target(words, target):
    n = len(words)
    memo = {}
    def backtrack(pos, used_mask, path):
        if pos == len(target):
            return path
        if (pos, used_mask) in memo:
            return None
        for i in range(n):
            if (used_mask >> i) & 1 == 0 and target.startswith(words[i], pos):
                res = backtrack(pos + len(words[i]), used_mask | (1 << i), path + [i])
                if res is not None:
                    return res
        memo[(pos, used_mask)] = None
        return None

    res = backtrack(0, 0, [])
    if res is not None:
        print('YES')
        print(' '.join(map(str, res)))
    else:
        print('NO')

