In Go, you can solve this problem by iterating through each digit in the number, and then checking if it is a prime number or a composite number. In this problem, we will classify 2, 3, 5, 7 as prime numbers and 4, 6, 8, 9 as composite numbers:

```go
func PrimeCompositeCount(num int) [2]int {
    if num < 0 {  // For negative numbers, we simply find the positive counterparts.
        num = -num
    }
    strNum := strconv.Itoa(num)
    var primeCount, compositeCount int

    for _, c := range strNum {
        digit := int(c - '0')
        switch digit {
        case 2, 3, 5, 7:  // prime numbers
            primeCount++
        case 4, 6, 8, 9:  // composite numbers
            compositeCount++
        }
    }
    return [2]int{primeCount, compositeCount}
}
```

