Here is the C version of the code:

```c
#include <stdio.h>
#include <stdlib.h>

void swap(int *x, int *y) {
    int temp = *x;
    *x = *y;
    *y = temp;
}

void sort(int arr[], int n) {
    int i, j, min_idx;
    for (i = 0; i < n - 1; i++) {
        min_idx = i;
        for (j = i + 1; j < n; j++)
            if (arr[j] < arr[min_idx])
                min_idx = j;
        swap(&arr[min_idx], &arr[i]);
    }
}

char* exchange(int lst1[], int lst2[], int n) {
    sort(lst1, n);
    sort(lst2, n);
    for (int i = 0; i < n; i++) {
        if (lst1[i] % 2 == 1) {
            for (int j = 0; j < n; j++) {
                if (lst2[j] % 2 == 0) {
                    swap(&lst1[i], &lst2[j]);
                    break;
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (lst1[i] % 2 == 1) {
            return "NO";
        }
    }
    return "YES";
}

int main() {
    int lst1[] = {1, 2, 3, 4};
    int lst2[] = {1, 2, 3, 4};
    printf("%s\n", exchange(lst1, lst2, 4));

    int lst3[] = {1, 2, 3, 4};
    int lst4[] = {1, 2, 5, 4};
    printf("%s\n", exchange(lst3, lst4, 4));

    return 0;
}
```

This program first sorts the arrays using selection sort, then for every odd number in the first list, if there exists an even number in the second list, they swap places. It then checks if all numbers in the first list are even, if any odd number is found it returns "NO", else "YES".

Please note that we are modifying arrays `lst1` and `lst2` in place in the function call `exchange(lst1, lst2, 4)` which means the next call to `exchange(lst3, lst4, 4)` is independent of the previous call. If we had directly reused `lst1` and `lst2`, it would not have generated expected output.

