def flatten_array(arr):
    result = []
    seen = set()
    def recurse(array):
        if id(array) in seen:
            return
        seen.add(id(array))
        for element in array:
            if isinstance(element, list):
                recurse(element)
            else:
                result.append(element)
    recurse(arr)
    return result

