    negative_words = {'terrible', 'awful', 'horrible', 'bad', 'poor', 'worst'}
    sarcastic_prefixes = {"I'm not", "Actually", "Saying that"}

    t = text.strip()
    sarcastic = any(t.startswith(prefix) for prefix in sarcastic_prefixes)
