def levenshtein_distance(s1, s2):
    if len(s1) > len(s2):
        s1, s2 = s2, s1
    len_s1, len_s2 = len(s1), len(s2)
    prev_row = range(len_s1 + 1)
    for i, char2 in enumerate(s2):
        curr_row = [i + 1]
        for j, char1 in enumerate(s1):
            cost = 0 if char1 == char2 else 1
            curr_row.append(min(
                curr_row[-1] + 1,    # Insertion
                prev_row[j + 1] + 1, # Deletion
                prev_row[j] + cost   # Substitution
            ))
        prev_row = curr_row
    return prev_row[-1]

