def build_query_string(obj, parent_key='', key_list=None):
    if key_list is None:
        key_list = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            new_key = f"{parent_key}[{key}]" if parent_key else key
            build_query_string(value, new_key, key_list)
    elif isinstance(obj, list):
        for index, value in enumerate(obj):
            new_key = f"{parent_key}[{index}]"
            build_query_string(value, new_key, key_list)
    else:
        key_list.append(f"{parent_key}={obj}")
    return '&'.join(key_list) if parent_key == '' else None

