def modular_division(a: int, b: int, n: int) -> int:
    assert n > 1
    assert a > 0
    assert greatest_common_divisor(a, n) == 1
    def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
        if b == 0:
            return (a, 1, 0)
        else:
            (d, p, q) = extended_gcd(b, a % b)
            return (d, q, p - q * (a // b))
    (d, t, s) = extended_gcd(n, a)
    x = (b * s) % n
    return x

def greatest_common_divisor(a: int, b: int) -> int:
    if a < b:
        a, b = b, a
    while a % b != 0:
        a, b = b, a % b
    return b

class BankAccount:
    def __init__(self, interest_rate=0.0):
        self.balances = {}
        self.interest_rate = interest_rate

    def deposit(self, amount, currency):
        if amount < 0:
            print("Error: Deposit amount cannot be negative")
            return
        if currency not in self.balances:
            self.balances[currency] = 0
        self.balances[currency] += amount
        print(f"Deposited {amount} {currency}. New balance: {self.balances[currency]} {currency}")

    def withdraw(self, amount, currency):
        if amount < 0:
            print("Error: Withdrawal amount cannot be negative")
            return
        if currency not in self.balances:
            print(f"Error: No balance in {currency}")
            return
        if self.balances[currency] < amount:
            print(f"Error: Insufficient funds for withdrawal of {amount} {currency}")
            return
        self.balances[currency] -= amount
        print(f"Withdrew {amount} {currency}. New balance: {self.balances[currency]} {currency}")

    def balance_inquiry(self, currency):
        if currency not in self.balances:
            print(f"Error: No balance in {currency}")
        else:
            print(f"Balance in {currency}: {self.balances[currency]} {currency}")

    def accrue_interest(self):
        for currency in self.balances:
            interest = self.balances[currency] * self.interest_rate
            self.balances[currency] += interest
            print(f"Accrual of interest for {currency}: {interest}, New balance: {self.balances[currency]} {currency}")

