sub find_mod_max {
    my @numbers = @{$_[0]};
    my $mod_max = undef;
    my $unique_digit_count = 0;
    for my $num (@numbers) {
        next unless $num =~ /^-?\d+$/; # skip if not an integer
        my %digits = map { $_ => 1 } split //, abs($num);
        my $current_unique_digits = keys %digits;
        if ($current_unique_digits > $unique_digit_count) {
            $unique_digit_count = $current_unique_digits;
            $mod_max = $num;
        }
    }
    return $mod_max;
}

