                first_occurrence = mid
                right = mid - 1
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return first_occurrence

    def find_last_occurrence():
        left, right = 0, len(arr) - 1
        last_occurrence = -1
        while left <= right:
            mid = left + (right - left) // 2
            if arr[mid] == target:
                last_occurrence = mid
                left = mid + 1
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return last_occurrence

    first = find_first_occurrence()
    last = find_last_occurrence()
    return first, last

