from typing import Tuple

def validate_ssh_connection(string: str) -> Tuple[str, str, int]:
    """
    Validate an SSH connection string of the form 'user@host:port'.

    Parameters
    ----------
    string : str
        The SSH connection string.

    Returns
    -------
    Tuple[str, str, int]
        (user, host, port) if the string is valid, otherwise an empty tuple.
    """
    # Basic sanity checks
    if not isinstance(string, str):
        return ()
    s = string.strip()

    # Must contain at least one '@' and one ':' in that order
    if '@' not in s or ':' not in s:
        return ()

    # Split once at the last ':' to separate port
    try:
        user_host_part, port_part = s.rsplit(':', 1)
    except ValueError:  # no ':' found (should not happen due to check above)
        return ()

    # Split once at the first '@' to separate user and host
    try:
        user_part, host_part = user_host_part.split('@', 1)
    except ValueError:  # no '@' found (should not happen)
        return ()

    # Validate user and host are non-empty and contain no extra separators
    if (
        not user_part or
        not host_part or
        ':' in user_part or
        ':' in host_part or
        '@' in host_part
    ):
        return ()

    # Validate port is an integer in the valid range 1–65535
    if not port_part.isdigit():
        return ()
    port_int = int(port_part)
    if not (1 <= port_int <= 65535):
        return ()

    return (user_part, host_part, port_int)

