First, let's develop the algorithm to check whether a number is prime or not using the Miller-Rabin primality test. This test is more efficient for larger numbers than traditional methods such as checking divisibility:

Note: C does not natively support 18-digit numbers (more than what a 64-bit integer can hold). You would need to use a library like GMP that allows for arbitrary precision arithmetic if you want to check primality for numbers larger than what a 64-bit integer can handle. Here we assume that the numbers can be stored in a 'long long int'.

```c
#include <stdbool.h>
#include <stdint.h>

// Function to calculate (a * b) % mod
uint64_t modulo_mul(uint64_t a, uint64_t b,uint64_t mod){
  uint64_t res = 0; 
  a = a % mod;
  while (b > 0){
    if (b % 2 == 1){
      res = (res + a) % mod;
    }
    a = (a * 2) % mod;
    b /= 2;
  }
  return res % mod;
}

// Function to calculate (base^exponent) % mod
uint64_t modulo_exp(uint64_t base, uint64_t exp, uint64_t mod){
  uint64_t res = 1;
  while(exp > 0){
    if(exp % 2 == 1) res = modulo_mul(res, base, mod);
    exp = exp >> 1;
    base = modulo_mul(base, base, mod);
  }
  return res % mod;
}

// Function that does the Miller-Rabin algorithm
bool miller_rabin(uint64_t n, int iteration){
  if (n < 2) return false;
  if (n != 2 && n % 2 == 0) return false;

  uint64_t d = n - 1;
  while(d % 2 == 0) d /= 2;

  for(int i = 0; i < iteration; i++){
    uint64_t a = rand() % (n - 1) + 1;
    uint64_t x = modulo_exp(a, d, n);
    while((d != n-1) && (x != 1) && (x != n - 1)){
      x = modulo_mul(x, x, n);
      d *= 2;
    }
    if (x != n-1 && d % 2 == 0) return false;
  }
  return true;
}
```

