import heapq

def construct_graph(roads):
    graph = defaultdict(dict)
    for start, end, bidirectional, time in roads:
        graph[start][end] = time
        if bidirectional == 'True':
            graph[end][start] = time
    return graph

def shortest_path_with_time(graph, start, end):
    pq = [(0, [start])]
    shortest_times = {start: 0}
    while pq:
        current_time, path = heapq.heappop(pq)
        current_city = path[-1]
        if current_city == end:
            return path, current_time
        for neighbor, travel_time in graph[current_city].items():
            new_time = current_time + travel_time
            if neighbor not in shortest_times or new_time < shortest_times[neighbor]:
                shortest_times[neighbor] = new_time
                heapq.heappush(pq, (new_time, path + [neighbor]))
    return None, float('inf')

