import json
from typing import Dict
from xml.dom import minidom


def get_pretty_body(headers: Dict[str, str], body: str) -> str:
    """
    Pretty-print an HTTP body according to its declared Content-Type.

    If Content-Type is “application/xml”  → pretty-print XML.
    If Content-Type is “application/json” → pretty-print JSON.
    Otherwise the body is returned unchanged.

    Any parsing/formatting errors fall back to returning the body untouched.
    """
    if body is None:
        return body

    # Fetch the header in a case-insensitive way
    content_type = None
    for key, value in headers.items():
        if key.lower() == 'content-type':
            content_type = (value or '').lower()
            break

    if content_type is None:
        return body  # No Content-Type header

    # Remove any optional parameters such as "; charset=utf-8"
    media_type = content_type.split(';', 1)[0].strip()

    try:
        if media_type == 'application/json':
            # JSON pretty print
            parsed = json.loads(body)
            return json.dumps(parsed, indent=4, ensure_ascii=False)

        elif media_type == 'application/xml':
            # XML pretty print
            xml_dom = minidom.parseString(body)
            # minidom.toprettyxml() adds new lines between nodes;
            # strip empty lines for cleaner output.
            pretty_xml = xml_dom.toprettyxml()
            return '\n'.join(line for line in pretty_xml.splitlines() if line.strip())

    except Exception:
        # Any error in parsing/formatting → return original body
        pass

    return body

