def factorial(n, counts):
    # Error handling for edge cases
    if not isinstance(n, int): 
        raise TypeError("Factorial is only defined for integers.")
    elif n < 0:
        raise ValueError("Factorial is not defined for negative integers.")

    # Counts function calls
    counts["factorial_calls"] += 1  

    # Base case
    if n == 0 or n == 1:
        return 1
    # Recursive case
    else:
        return n*factorial(n-1, counts)


def fibonacci(n, counts):
    # Error handling for edge cases
    if not isinstance(n, int): 
        raise TypeError("Fibonacci sequence is only defined for integers.")
    elif n < 0:
        raise ValueError("Fibonacci sequence is not defined for negative integers.")

    # Counts function calls
    counts["fibonacci_calls"] += 1  

    # Base cases
    if n == 0:
        return 0
    elif n == 1:
        return 1
    # Recursive case
    else:
        return fibonacci(n-1, counts) + fibonacci(n-2, counts)


