  return Array.from(str).reduce((acc, char) => char + acc, '');
}
console.log(reverseString2("hello 🌍!"));
```

**Method 3: Using a traditional loop**
This method goes through the string characters from the end to the beginning in order to handle special Unicode characters.
```javascript
function reverseString3(str) {
  let reversedStr = '';
  // Use of Array.from to handle Unicode characters
  let arr = Array.from(str);
  for(let i = arr.length - 1; i >= 0; i--) {
    reversedStr += arr[i];
  }
  return reversedStr;
}
