def simulate_random_event(outcomes, probabilities):
    import random

    # Check if the sum of probabilities is 1
    if sum(probabilities) != 1:
        raise ValueError("Probabilities must sum up to 1")

    # Create a cumulative probability distribution
    cumulative_probs = [sum(probabilities[:i+1]) for i in range(len(probabilities))]

    # Generate a random number between 0 and 1
    random_num = random.random()

    # Find the corresponding outcome based on the random number
    for i, prob in enumerate(cumulative_probs):
        if random_num < prob:
            return outcomes[i]

