    import sys
    input_lines = []
    while True:
        try:
            line = input()
            input_lines.append(line)
        except EOFError:
            break
        if len(input_lines) >= 3:
            try:
                n = int(input_lines[2])
                if len(input_lines) == 3 + n:
                    break
            except Exception:
                continue

    s1 = input_lines[0]
    s2 = input_lines[1]
    n = int(input_lines[2])
    collation_table = dict()
    for i in range(3, 3 + n):
        codepoint_str, key_str = input_lines[i].split()
        codepoint = int(codepoint_str)
        key = int(key_str)
        collation_table[codepoint] = key

    s1 = preprocess(s1)
    s2 = preprocess(s2)
    len_s1, len_s2 = len(s1), len(s2)
    dp = [[0] * (len_s2 + 1) for _ in range(len_s1 + 1)]
    longest_len = 0
    substrings = set()
    for i in range(1, len_s1 + 1):
        for j in range(1, len_s2 + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                substr_len = dp[i][j]
                if substr_len > longest_len:
