                    substrings = {s1[i - substr_len:i]}
                elif substr_len == longest_len:
                    substrings.add(s1[i - substr_len:i])
            else:
                dp[i][j] = 0
    for substr in sorted(substrings, key=lambda s: collation_key(s, collation_table), reverse=True):
