def custom_compare(book1, book2):
    # Compare by publication year
    if book1['publication_year'] != book2['publication_year']:
        return book1['publication_year'] - book2['publication_year']

    # Compare by author's last name (lexicographically)
    author_last_name1 = book1['author'].split()[-1]
    author_last_name2 = book2['author'].split()[-1]

    if author_last_name1 != author_last_name2:
        if author_last_name1 < author_last_name2:
            return -1
        else:
            return 1

    # Compare by title in descending order
    if book1['title'] != book2['title']:
        if book1['title'] > book2['title']:
            return -1
        else:
            return 1

    # If all are the same, consider them equal
    return 0

def merge_sort_books(books, compare_func):
    if len(books) <= 1:
        return books

    mid = len(books) // 2
    left_half = merge_sort_books(books[:mid], compare_func)
    right_half = merge_sort_books(books[mid:], compare_func)

    return merge(left_half, right_half, compare_func)

def merge(left, right, compare_func):
    sorted_books = []
    left_index, right_index = 0, 0
    while left_index < len(left) and right_index < len(right):
        comparison_result = compare_func(left[left_index], right[right_index])
        if comparison_result <= 0:
            sorted_books.append(left[left_index])
            left_index += 1
        else:
            sorted_books.append(right[right_index])
            right_index += 1
    sorted_books.extend(left[left_index:])
    sorted_books.extend(right[right_index:])
    return sorted_books

