    books = []
    for _ in range(n):
        title = input().rstrip('\n')
        author = input().rstrip('\n')
        publication_year = int(input())
        books.append({'title': title, 'author': author, 'publication_year': publication_year})
    sorted_books = merge_sort_books(books, custom_compare)
    for book in sorted_books:
