from collections import deque

def build_tree(nodes):
    if not nodes or nodes[0] == 'null':
        return None
    root = TreeNode(int(nodes[0]))
    queue = deque([root])
    i = 1
    n = len(nodes)
    while queue and i < n:
        node = queue.popleft()
        if i < n and nodes[i] != 'null':
            node.left = TreeNode(int(nodes[i]))
            queue.append(node.left)
        i += 1
        if i < n and nodes[i] != 'null':
            node.right = TreeNode(int(nodes[i]))
            queue.append(node.right)
        i += 1
    return root

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def main():
    import sys
    nodes = sys.stdin.readline().strip().split()
    root = build_tree(nodes)
    if not root:
        print("True")
        return
    queue = deque([(root, float('-inf'), float('inf'))])
    while queue:
        node, lb, ub = queue.popleft()
        if node.val <= lb or node.val >= ub:
            print("False")
            return
        if node.left:
            queue.append((node.left, lb, node.val))
        if node.right:
            queue.append((node.right, node.val, ub))
    print("True")

