    for i in lst:
        if i == item:
            return True
    return False


def append_to_list(lst: list, item):
    """Appends item to list if not already in the list"""
    if not is_in_list(lst, item):
        lst.append(item)
        return True
    return False


def sort_list(lst: list):
    """Sorts the list"""
    for i in range(len(lst)):
        for j in range(i+1, len(lst)):
            if lst[i] > lst[j]:
                lst[i], lst[j] = lst[j], lst[i]
    return lst


def common(l1: list, l2: list, l3: list):
    common_elements = []
    for i in l1:
        if is_in_list(l2, i) and is_in_list(l3, i):
            append_to_list(common_elements, i)
    return sort_list(common_elements)


