Here is a Java program that calculates the least common multiple (LCM) of two integers.

```java
import java.util.InputMismatchException;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            System.out.print("Enter first positive integer: ");
            int num1 = scanner.nextInt();
            System.out.print("Enter second positive integer: ");
            int num2 = scanner.nextInt();
            if (num1 <= 0 || num2 <= 0) {
                System.out.println("Error: Both numbers must be positive. Please try again.");
            } else {
                System.out.println("The least common multiple (LCM) of " + num1 + " and " + num2 + " is " + lcm(num1, num2));
            }
        } catch (InputMismatchException e) {
            System.out.println("Error: Input is not a valid integer. Please try again.");
        }
    }

    // function to calculate the least common multiple (LCM)
    public static int lcm(int num1, int num2) {
        return (num1 * num2) / gcd(num1, num2);
    }

    // function to calculate the greatest common divisor (GCD)
    public static int gcd(int num1, int num2) {
        if (num2 == 0) {
            return num1;
        } else {
            return gcd(num2, num1 % num2);
        }
    }
}
