def generate_primes(n):
    if n < 2:
        return []
    elif n == 2:
        return [2]
    limit = (n - 1) // 2
    primes = [True] * (limit + 1)
    primes[0] = False
    for i in range(1, int((n ** 0.5 - 1) / 2) + 1):
        if primes[i]:
            start = 2 * i * (i + 1)
            step = 2 * i + 1
            for j in range(start, limit + 1, step):
                primes[j] = False
    return [2] + [2 * i + 1 for i in range(1, limit + 1) if primes[i]]

def main():
