```cpp
#include <iostream>
#include <vector>
using namespace std;

void checkEvenOdd(vector<int> nums) {  
    for(int i=0; i<=nums.size(); i++) { 
        if(nums[i]%2 = 0)             
            cout << nums[i] << " is even" << endl;
        else 
            cout << nums[i] << " is odd" << endl;
