class TreeNode:
    def __init__(self, val=0):
        self.val = val
        self.left = None
        self.right = None

def build_tree(nodes):
    if not nodes:
        return None
    node_objs = [TreeNode(val) for val, l, r in nodes]
    for idx, (val, l, r) in enumerate(nodes):
        if l != -1:
            node_objs[idx].left = node_objs[l]
        if r != -1:
            node_objs[idx].right = node_objs[r]
    return node_objs[0]

def is_balanced(root):
    if not root:
        return True
    stack = [(root, False)]
    depth_cache = {}
    while stack:
        node, visited = stack.pop()
        if not node:
            continue
        if visited:
            left_depth = depth_cache.get(node.left, 0)
            right_depth = depth_cache.get(node.right, 0)
            if abs(left_depth - right_depth) > 1:
                depth_cache[root] = -float('inf')
                return False
            depth_cache[node] = max(left_depth, right_depth) + 1
        else:
            stack.append((node, True))
            if node.right:
                stack.append((node.right, False))
            if node.left:
                stack.append((node.left, False))
    return True

def main():
    n = int(input())
    nodes = []
    for _ in range(n):
        val, l, r = map(int, input().split())
        nodes.append((val, l, r))
    root = build_tree(nodes)
    print(str(is_balanced(root)))

