import math

def calculate_average_distance(landmarks):
    distances = []
    for i in range(len(landmarks)):
        for j in range(i + 1, len(landmarks)):
            x1, y1, z1 = landmarks[i]
            x2, y2, z2 = landmarks[j]
            distance = math.sqrt((x2 - x1)**2 + (y2 - y1)**2 + (z2 - z1)**2)
