            time += 0.01;

            var yOffset = centerY + Math.sin(time) * radius;
            var xOffset = centerX + Math.cos(time) * radius;
            var rad = radius * (1 + 0.5 * Math.sin(time));
            var color = getTransitionColor(time);

            ctx.beginPath();
            ctx.ellipse(xOffset, yOffset, rad, rad / 2, 0, 0, Math.PI * 2);
            ctx.fillStyle = color;
            ctx.closePath();
            ctx.fill();

            requestAnimationFrame(draw);
