        function getTransitionColor(time) {
            var redVal = parseInt(255 * Math.max(Math.cos(time), 0), 10);
            var blueVal = parseInt(255 * Math.max(Math.sin(time), 0), 10);
            return 'rgb(' + redVal + ',0,' + blueVal + ')';
        }

        draw();
