    dp = [[0] * (n + 1) for _ in range(2)]
    count = [[1] * (n + 1) for _ in range(2)]

    for i in range(1, m + 1):
        curr, prev = i % 2, (i - 1) % 2
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[curr][j] = dp[prev][j - 1] + 1
                count[curr][j] = count[prev][j - 1]
            else:
                if dp[prev][j] > dp[curr][j - 1]:
                    dp[curr][j] = dp[prev][j]
                    count[curr][j] = count[prev][j]
                elif dp[curr][j - 1] > dp[prev][j]:
                    dp[curr][j] = dp[curr][j - 1]
                    count[curr][j] = count[curr][j - 1]
                else:
                    dp[curr][j] = dp[prev][j]
                    count[curr][j] = count[prev][j] + count[curr][j - 1]
                    if dp[curr][j] != 0:
                        count[curr][j] -= count[prev][j - 1]
        # Reset the older row's counts to 1 for safety (to prepare for next iteration)
        for j in range(n+1):
            count[prev][j] = 1
    lcs_length = dp[m % 2][n]
    lcs_count = count[m % 2][n] if lcs_length != 0 else 0
