using System;
using System.Collections.Generic;
using System.Linq;

public class SubsequenceSort 
{
    public Dictionary<string, int> CanArrange(int[] arr, Tuple<int, int> bracket) 
    {
        int lower = bracket.Item1;
        int upper = bracket.Item2;

        List<int> subset = arr.Skip(lower).Take(upper - lower + 1).ToList();
        List<int> sortedSubset = new List<int>(subset);
        sortedSubset.Sort();

        for (int i = 0; i < subset.Count; i++) 
        {
            if (subset[i] != sortedSubset[i]) 
            {
                int swapIndex = subset.IndexOf(sortedSubset[i]);
                return new Dictionary<string, int> 
                {
                    { "index", lower + i },
                    { "swap_with", lower + swapIndex }
                };
            }
        }

        return new Dictionary<string, int> 
        {
            { "index", -1 },
            { "swap_with", -1 }
        };
    }
} 
```
