async fn fetch_data(query: &str) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Set up authentication
    let auth = oauth2::service_account_authenticator_from_json(
        "path/to/service-account-key.json",
        &["https://www.googleapis.com/auth/bigquery"],
    )
    .await?;
    let client = BigqueryClient::new(auth);

    // Execute BigQuery
    let request = client
        .jobs()
        .query(google_bigquery2::api::QueryRequest {
            query: query.to_string(),
            use_legacy_sql: false.into(),
            ..Default::default()
        });
    let resp = request.doit().await?;

    // Convert rows to DataFrame
    let data = resp
        .rows
        .unwrap_or_default()
        .into_iter()
        .map(|row| {
            row.f
                .unwrap_or_default()
                .into_iter()
                .map(|cell| cell.v.unwrap_or_default())
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    let df = DataFrame::from(&data);

    // Clean data
    let cleaned = df.dropna()?.drop_duplicates()?;

    Ok(cleaned)
}
