        try:
            with open(file_path, 'w') as file:
                file.write(content)
                self._update_access_count(file_path)
        except Exception as e:
            print(f"An error occurred: {e}")

    def append_to_file(self, file_path, content):
        try:
            with open(file_path, 'a') as file:
                file.write(content)
                self._update_access_count(file_path)
        except Exception as e:
            print(f"An error occurred: {e}")

    def get_access_count(self, file_path):
        return self.access_counts.get(file_path, 0)

    def _update_access_count(self, file_path):
        if file_path in self.access_counts:
            self.access_counts[file_path] += 1
        else:
            self.access_counts[file_path] = 1

