class VendingMachine:
    def __init__(self, items):
        self.items = items
        self.coins_inserted = 0.0

    def insert_coin(self, coin_value):
        self.coins_inserted += coin_value
        print(f"Total coins inserted: ${self.coins_inserted:.2f}")

    def display_items(self):
        print("Available items:")
        for index, item in enumerate(self.items):
            if item["quantity"] > 0:
                print(f"{index}: {item['name']} - ${item['price']:.2f} (Quantity: {item['quantity']})")
            else:
                print(f"{index}: {item['name']} - ${item['price']:.2f} (Quantity: 0)")

    def select_item(self, item_index):
        if item_index < 0 or item_index >= len(self.items):
            print("Invalid selection.")
            return

        item = self.items[item_index]
        if item["quantity"] == 0:
            print(f"Sorry, {item['name']} is out of stock.")
            return

        if self.coins_inserted < item["price"]:
            print(f"Not enough coins inserted. You need an additional ${item['price'] - self.coins_inserted:.2f}.")
            return

        self.dispense_item(item_index)

    def dispense_item(self, item_index):
        item = self.items[item_index]
        item["quantity"] -= 1
        change = self.coins_inserted - item["price"]
        print(f"Dispensing {item['name']}.")
        if change > 0:
            print(f"Returning change: ${change:.2f}")
        self.coins_inserted = 0.0

    def return_coins(self):
        print(f"Returning coins: ${self.coins_inserted:.2f}")
        self.coins_inserted = 0.0


