```python
import math

class Tetrahedron:

    def __init__(self, edge):
        if edge <= 0:
            raise ValueError("Edge length must be a positive number")
        self.edge = edge

    def volume(self):
        return (self.edge ** 3) / (6 * math.sqrt(2))

    def surface_area(self):
        return math.sqrt(3) * (self.edge ** 2)

    def compare(self, other_tetrahedron):
        if not isinstance(other_tetrahedron, Tetrahedron):
