class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def insert_bst(root, key):
    if root is None:
        return Node(key)
    if key < root.data:
        root.left = insert_bst(root.left, key)
    else:
        root.right = insert_bst(root.right, key)
    return root

def concatenate(first, second):
    if not first:
        return second
    if not second:
        return first
    last_of_first = first.left
    last_of_second = second.left
    last_of_first.right = second
    second.left = last_of_first
    last_of_second.right = first
    first.left = last_of_second
    return first

def tree_to_doubly_list(root):
    if root is None:
        return None
    left = tree_to_doubly_list(root.left)
    right = tree_to_doubly_list(root.right)
    root.left = root.right = root
    head = concatenate(left, root)
    head = concatenate(head, right)
    return head

def display(head):
    res = []
    it = head
    if head is not None:
        while True:
            res.append(str(it.data))
            it = it.right
            if it == head:
                break
    print(' '.join(res))

def main():
    n = int(input())
    vals = [int(input()) for _ in range(n)]
    root = None
    for v in vals:
        root = insert_bst(root, v)
    head = tree_to_doubly_list(root)
    display(head)

