import sys
import unicodedata

def preprocess_string(s):
    # Normalize string to remove accents and convert to lowercase
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(char.lower() for char in s if char.isalnum())
    return s

def expand_around_center(s, left, right):
    while left >= 0 and right < len(s) and s[left] == s[right]:
        left -= 1
        right += 1
    return s[left+1:right]

def longest_palindrome_substring(s):
    longest_palindrome = ""
    for i in range(len(s)):
        # Odd length
        p1 = expand_around_center(s, i, i)
        if len(p1) > len(longest_palindrome):
            longest_palindrome = p1
        # Even length
        p2 = expand_around_center(s, i, i+1)
        if len(p2) > len(longest_palindrome):
            longest_palindrome = p2
    return longest_palindrome

def main():
    s = sys.stdin.readline().rstrip('\n')
    normalized = preprocess_string(s)
    if not normalized:
        print("")
        print("")
        return
    # First output: the normalized string if it's a palindrome, else the longest palindrome
    if normalized == normalized[::-1]:
        print(normalized)
    else:
        print(longest_palindrome_substring(normalized))
    # Second output: always the longest nested palindrome substring (could be the same)
    print(longest_palindrome_substring(normalized))

