    # Basic regex for email with at least one subdomain
    pattern = r'^[\w\.-]+@([\w\-]+\.)+[\w\-]+\.[a-zA-Z]{2,}$'
    if re.match(pattern, email):
        # Split by @, then split domain part
        local, _, domain = email.partition('@')
        parts = domain.split('.')
        # There must be at least 3 components: subdomain, domain, tld
        if len(parts) >= 3:
            return True
    return False

