import sys
import xml.etree.ElementTree as ET
import json

def parse_xml(element):
    node = {}
    if element.attrib:
        node["@attributes"] = element.attrib
    text = element.text.strip() if element.text and element.text.strip() else ""
    children = list(element)
    if children:
        children_tags = [child.tag for child in children]
        for child in children:
            child_node = parse_xml(child)
            if children_tags.count(child.tag) > 1:
                if child.tag in node:
                    node[child.tag].append(child_node)
                else:
                    node[child.tag] = [child_node]
            else:
                node[child.tag] = child_node
        if text:
            node["#text"] = int(text) if text.isdigit() else text
        return node
    else:
        if text:
            return int(text) if text.isdigit() else text
        else:
            return node

def main():
    xml_string = sys.stdin.read()
    xml_string = xml_string.strip()
    root = ET.fromstring(xml_string)
    result = parse_xml(root)
    # result may be a dict or value
    if isinstance(result, dict):
        output = json.dumps(result, separators=(",", ":"))
    else:
        output = json.dumps({root.tag: result}, separators=(",", ":"))
    print(output)

