def can_form(target: str, source: str) -> bool:
    """Return True if target can be obtained from source by keeping an equally spaced subsequence."""
    m = len(target)
    n = len(source)
    if n < m:
        return False

    # Try every possible starting position
    for start in range(n):
        # Remaining characters after start (inclusive) = n - start
        # To fit m characters with step d we need: start + (m-1)*d < n
        max_d = (n - 1 - start) // (m - 1) if m > 1 else n  # avoid division by zero for m == 1
        if max_d == 0:  # not enough room even for d == 1
            continue
        for d in range(1, max_d + 1):
            ok = True
            for k in range(m):
                pos = start + k * d
                if pos >= n or source[pos] != target[k]:
                    ok = False
                    break
            if ok:
                return True
    return False


