def median(lst):
    n = len(lst)
    if n % 2 == 1:
        return findKthLargest(lst, n // 2)
    else:
        return 0.5 * (findKthLargest(lst, n // 2 - 1) + findKthLargest(lst, n // 2))

def findKthLargest(nums, k):
    pivot = nums[len(nums) // 2]
    left = [x for x in nums if x < pivot]
    mid = [x for x in nums if x == pivot]
    right = [x for x in nums if x > pivot]

    if k < len(left):
        return findKthLargest(left, k)
    elif k < len(left) + len(mid):
        return nums[k]
    else:
        return findKthLargest(right, k - len(left) - len(mid))

def quartiles(l):
    n = len(l)
    if n % 2 == 1:
        return (findKthLargest(l, n // 4), findKthLargest(l, n * 3 // 4))
    else:
        return (0.5 * (findKthLargest(l, n // 4 - 1) + findKthLargest(l, n // 4)),
                0.5 * (findKthLargest(l, n * 3 // 4 - 1) + findKthLargest(l, n * 3 // 4)))
```

