def apply_operator(ops, values):
    op = ops.pop()
    right = values.pop()
    left = values.pop()
    if op == '+':
        values.append(left + right)
    elif op == '-':
        values.append(left - right)
    elif op == '*':
        values.append(left * right)
    elif op == '/':
        values.append(left / right)

