def digits_after_decimal(A: int, B: int) -> int:
    # Reduce the fraction A / B to its lowest terms
    g = math.gcd(A, B)
    D = B // g  # only the denominator matters for termination

    # Count powers of 2 and 5 in D
    twos = 0
    while D % 2 == 0:
        D //= 2
        twos += 1

    fives = 0
    while D % 5 == 0:
        D //= 5
        fives += 1

    # If after removing all 2s and 5s nothing remains, the decimal terminates
    if D == 1:
        return max(twos, fives)
    else:
        return -1


