```

Alternatively, you can handle it with `Application_BeginRequest` method in `Global.asax.cs`.

```csharp
protected void Application_BeginRequest(Object sender, EventArgs e)
{
    string url = Request.Url.AbsolutePath;

    if (UrlNeedsReplacing(url))
    {
        string newUrl = ReplaceUrl(url);
        Response.RedirectPermanent(newUrl);
    }
}

private bool UrlNeedsReplacing(string url) {
    // check if the url contains uppercase characters, or underscores
    return Regex.IsMatch(url, @"[A-Z]|\_");
}

private string ReplaceUrl(string url) {
    // replace underscores with hyphens, and convert to lowercase
    return Regex.Replace(url, "([A-Z])", "-$1", RegexOptions.Compiled).Trim().ToLower();
}
```

However, doing it this way will apply it to every single URL which might not be what you want.

