def find_first_occurrence(nums, target):
    left, right = 0, len(nums) - 1
    first_occurrence = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            first_occurrence = mid
            right = mid - 1
    return first_occurrence

def find_last_occurrence(nums, target):
    left, right = 0, len(nums) - 1
    last_occurrence = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            last_occurrence = mid
            left = mid + 1
    return last_occurrence

