def unique_permutations(s):
    def backtrack(path, used):
        if len(path) == len(s):
            print(''.join(path))
            return
        for i in range(len(s)):
            if used[i]:
                continue
            if i > 0 and s[i] == s[i-1] and not used[i-1]:
                continue
            used[i] = True
            path.append(s[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    s = ''.join(sorted(s))
    used = [False] * len(s)
    backtrack([], used)

