    n = len(prices)
    if n < 2:
        return (-1, -1)

    # Calculate the moving averages
    moving_averages = []
    for i in range(n - window + 1):
        avg = sum(prices[i:i+window]) / window
        moving_averages.append(avg)

    # Find the best buy and sell days
    buy_day = -1
    sell_day = -1
    max_profit = 0
    for i in range(n - window + 1):
        if prices[i] < moving_averages[i]:
            for j in range(i+window, n):
                if prices[j] > moving_averages[j-i]:
                    profit = prices[j] - prices[i]
