```javascript
function factorial(n) {
    // Check if input is a number
    if (isNaN(n)) {
        return "Invalid Input! Please enter a number.";
    }

    // Handling 0 as input
    if (n === 0) {
        return "The factorial of 0 is 1.";
    }

    // Handling negative integers
    if (n < 0) {
        return "Invalid Input! Factorial for negative numbers is not defined.";
    }

    // Performance concerns for numbers greater than 25
    if (n > 25) {
        return "Sorry, the calculation for numbers larger than 25 is not supported due to performance concerns.";
    }

    // Recursive function to calculate factorial
    let fact = 1;
    for (let i = 1; i <= n; i++) {
        fact *= i;
    }

    return "The factorial of " + n + " is " + fact;
}

