from typing import Tuple, Dict, Union

def parse_prediction_key(key: str) -> Tuple[str, Dict[str, Union[str, int, float]]]:
    """
    Parse a predictor key of the form:
        Name(Detail1=Value1, Detail2=Value2, ...)
    and return a tuple (name, details_dict).

    If no parentheses are present, returns (key, {}).

    Parameters
    ----------
    key : str
        The predictor key string to parse.

    Returns
    -------
    Tuple[str, Dict[str, Union[str, int, float]]]
        A tuple containing the name and a dictionary of details.
    """

    # Helper to convert string numbers to int or float if possible.
    def _convert(value: str) -> Union[str, int, float]:
        value = value.strip()
        # Try integer conversion
        try:
            return int(value)
        except ValueError:
            pass
        # Try float conversion
        try:
            return float(value)
        except ValueError:
            return value  # Keep as string if numeric conversion fails

    # Locate '(' that starts the detail section
    try:
        start = key.index('(')
        end = key.rindex(')')
    except ValueError:
        # No parentheses found => only name
        return key.strip(), {}

    name = key[:start].strip()
    details_str = key[start + 1:end].strip()

    # Empty parentheses
    if not details_str:
        return name, {}

    details: Dict[str, Union[str, int, float]] = {}

    # Split by commas at the top level (no nested parentheses per problem statement)
    for part in details_str.split(','):
        part = part.strip()
        if not part:
            continue
        if '=' not in part:
            # Defensive: skip malformed parts (though spec says input is well-formed)
            continue
        k, v = part.split('=', 1)
        k = k.strip()
        v = _convert(v)
        details[k] = v

    return name, details

