        mid = (low + high) // 2
        if arr[mid] < target:
            low = mid + 1
        elif arr[mid] > target:
            high = mid - 1
        else:
            result = mid
            high = mid - 1
    return result

def binary_search_right(arr, target, low, high):
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] < target:
            low = mid + 1
        elif arr[mid] > target:
            high = mid - 1
        else:
            result = mid
            low = mid + 1
    return result

