Here is a Python program that will generate the nth Fibonacci number using the recursive and iterative approaches, then optimizes the recursive approach with memoization.

```python
def fibonacci_recursive(n):
    if n <= 0:
        return "Invalid input. Please enter a positive integer."
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

def fibonacci_iterative(n):
    if n <= 0:
        return "Invalid input. Please enter a positive integer."
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return a

memory = {}        
def fibonacci_recursive_optimized(n):
    if n <= 0:
        return "Invalid input. Please enter a positive integer."
    if n in memory:
        return memory[n]
    elif n == 1:
        value = 0
    elif n == 2:
        value = 1
    else:
        value = fibonacci_recursive_optimized(n-1) + fibonacci_recursive_optimized(n-2)
    memory[n] = value
    return value

print(fibonacci_recursive(10))       # output: 34
print(fibonacci_iterative(10))       # output: 34
print(fibonacci_recursive_optimized(10))  # output: 34
```
