class Node:
    def __init__(self, node_id, value):
        self.id = node_id
        self.value = value
        self.children = [None, None, None]

def build_tree(node_data):
    n = len(node_data)
    nodes = {}
    for d in node_data:
        id_, value, _, _, _ = d
        nodes[id_] = Node(id_, value)
    for d in node_data:
        id_, value, c1, c2, c3 = d
        node = nodes[id_]
        node.children[0] = nodes.get(c1) if c1 != 0 else None
        node.children[1] = nodes.get(c2) if c2 != 0 else None
        node.children[2] = nodes.get(c3) if c3 != 0 else None
    return nodes[1]  # root

def max_depth_recursive(node):
    if not node:
        return (0, [])
    max_depth = 1
    max_paths = []
    for child in node.children:
        if child:
            depth, path = max_depth_recursive(child)
            if depth + 1 > max_depth:
                max_depth = depth + 1
                max_paths = [path]
            elif depth + 1 == max_depth:
                max_paths.append(path)
    if not max_paths:
        return (1, [node.value])
    else:
        # If multiple, choose lexicographically smallest path
        min_path = min(max_paths)
        return (max_depth, [node.value] + min_path)

def max_depth_iterative(node):
    if not node:
        return (0, [])
    stack = [(node, 1, [node.value])]
    max_depth = 0
    paths = []
    while stack:
        current, depth, path = stack.pop()
        children_present = [c for c in current.children if c]
        if not children_present:
            if depth > max_depth:
                max_depth = depth
                paths = [path]
            elif depth == max_depth:
                paths.append(path)
        else:
            # Reverse to preserve left-to-right order (since stack pops from end)
            for i in reversed(range(3)):
                child = current.children[i]
                if child:
                    stack.append((child, depth+1, path+[child.value]))
    min_path = min(paths) if paths else []
    return (max_depth, min_path)

def main():
    n = int(input())
    node_data = []
    for _ in range(n):
        parts = input().split()
        id_ = int(parts[0])
        value = int(parts[1])
        c1 = int(parts[2])
        c2 = int(parts[3])
        c3 = int(parts[4])
        node_data.append((id_, value, c1, c2, c3))
    root = build_tree(node_data)
    rec_depth, rec_path = max_depth_recursive(root)
    iter_depth, iter_path = max_depth_iterative(root)
    print(rec_depth)
    print(' '.join(str(x) for x in rec_path))
    print(iter_depth)
    print(' '.join(str(x) for x in iter_path))

