    current = dummy
    for val in arr:
        current.next = ListNode(val)
        current = current.next
    return dummy.next

def shell_sort_linked_list(head):
    if not head or not head.next:
        return head
    # Copy linked list to an array for easier gap sorting
    nodes = []
    current = head
    while current:
        nodes.append(current)
        current = current.next
    n = len(nodes)
    # Find highest power of 2 less than n
    gap = 1
    while gap < n // 2:
        gap *= 2
    while gap > 0:
        for i in range(gap, n):
            temp = nodes[i].val
            j = i
            while j >= gap and nodes[j - gap].val > temp:
                nodes[j].val = nodes[j - gap].val
                j -= gap
            nodes[j].val = temp
        gap //= 2
    return head

def print_linked_list(head):
    arr = []
    current = head
    while current:
        arr.append(str(current.val))
        current = current.next
    print(' '.join(arr))

