    float vec[] = {1.2, 3.5, 4.1, 6.7, 7.9, 9.0, 11.2, 14.3, 15.8, 18.4, 22.5, 27.0};

    int n = sizeof(vec) / sizeof(vec[0]);

    //Sort the array
    sort(vec, vec+n);

    //Find the median
    float median = 0;
    if(n % 2 != 0)
        median = vec[n/2];
    else
        median = (vec[(n-1)/2] + vec[n/2])/2;

