using namespace std;

string encrypt(string s){
    string encryptedString = "";

    for (int i = 0; i < s.length(); i++){
        int asciiVal = (int)s[i];
        if(asciiVal >= 97 && asciiVal <= 122){
            int rotationMultiplier = i + 1;
            int newAsciiVal = ((asciiVal - 97 + rotationMultiplier) % 26) + 97;
            encryptedString += char(newAsciiVal);
        }
        else{
            encryptedString += s[i];
        }
    }

    return encryptedString;
}

