def min_swaps(s1: str, s2: str) -> int:
    # If lengths differ it is impossible (should not happen per constraints)
    if len(s1) != len(s2):
        return -1

    # Total number of 'x' must be even, otherwise impossible
    if (s1.count('x') + s2.count('x')) % 2 == 1:
        return -1

    xy = yx = 0  # mismatches of type "x in s1, y in s2" and vice-versa
    for c1, c2 in zip(s1, s2):
        if c1 == 'x' and c2 == 'y':
            xy += 1
        elif c1 == 'y' and c2 == 'x':
            yx += 1

    # Each pair of the same type needs one swap; a leftover of one xy and one yx needs 2 swaps
    return (xy // 2) + (yx // 2) + 2 * (xy % 2)


