def generate_todo_list(items: List[str], actions: List[str]) -> Dict[str, str]:
    """
    Generates a dictionary-based to-do list from two parallel lists:
      - items:   a list of to-do list subjects (strings)
      - actions: a list of actions to perform (strings)

