class MinStack:
    def __init__(self):
        self.items = []
        self.min_stack = []

    def push(self, item):
        self.items.append(item)
        if not self.min_stack or item <= self.min_stack[-1]:
            self.min_stack.append(item)

    def pop(self):
        if self.isEmpty():
            print("Error")
            return
        item = self.items.pop()
        if item == self.min_stack[-1]:
            self.min_stack.pop()

    def peek(self):
        if self.isEmpty():
            print("Error")
        else:
            print(self.items[-1])

    def isEmpty(self):
        return len(self.items) == 0

    def print_is_empty(self):
        print("True" if self.isEmpty() else "False")

    def print_min(self):
        if self.isEmpty():
            print("Error")
        else:
            print(self.min_stack[-1])

def main():
