class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree_from_level_order(values):
    if not values or values[0] == 'null':
        return None
    nodes = []
    for v in values:
        if v == 'null':
            nodes.append(None)
        else:
            nodes.append(TreeNode(int(v)))
    kids = nodes[::-1]
    root = kids.pop()
    for node in nodes:
        if node:
            if kids:
                node.left = kids.pop()
            if kids:
                node.right = kids.pop()
    return root

def find_second_minimum_value(root):
    first_min = root.val
    second_min = None
    current = root
    while current:
        if not current.left:
            if current.val != first_min:
                if second_min is None or current.val < second_min:
                    second_min = current.val
            current = current.right
        else:
            pre = current.left
            while pre.right and pre.right != current:
                pre = pre.right
            if not pre.right:
                pre.right = current
                current = current.left
            else:
                pre.right = None
                if current.val != first_min:
                    if second_min is None or current.val < second_min:
                        second_min = current.val
                current = current.right
    if second_min is None:
        return -1
    return second_min

if __name__ == "__main__":
    values = input().strip().split()
    root = build_tree_from_level_order(values)
    print(find_second_minimum_value(root))

