import re
import sys
try:
    import idna
except ImportError:
    idna = None

def is_valid_url(url):
    EU_SLDs = {
        "at", "be", "bg", "hr", "cy", "cz", "dk", "ee", "fi", "fr", "de", "el", "hu", "ie", "it", "lv", "lt", "lu",
        "mt", "nl", "pl", "pt", "ro", "sk", "si", "es", "se", "ch"
    }

    # HTTP/HTTPS Scheme
    if not (url.startswith("http://") or url.startswith("https://")):
        return "Invalid"

    # Strip scheme
    rest = url.split('://', 1)[1]
    # Next, get the domain part
    path_start = rest.find('/')
    if path_start == -1:
        domain = rest
        path = ''
    else:
        domain = rest[:path_start]
        path = rest[path_start:]

    # IP address detection
    if re.match(r'^(\d{1,3}\.){3}\d{1,3}$', domain):
        return "Invalid"

    # Attempt IDNA conversion
    try:
        # Only attempt if there are non-ASCII chars
        if any(ord(c) > 127 for c in domain):
            if idna is None:
                return "Invalid"
            domain_ascii = idna.encode(domain).decode('ascii')
        else:
            domain_ascii = domain
    except Exception:
        return "Invalid"

    # Check SLD + .eu
    domain_parts = domain_ascii.lower().split('.')
    if len(domain_parts) < 3:
        return "Invalid"
    if domain_parts[-1] != 'eu':
        return "Invalid"
    if domain_parts[-2] not in EU_SLDs:
        return "Invalid"
    # Only one label before SLD
    if len(domain_parts) != 3:
        return "Invalid"

    # Check for consecutive slashes in path (other than after scheme)
    p = path if path else ''
    if '//' in p:
        return "Invalid"
    # Also make sure there is no '//' before the path (in the domain, which could indicate a typo)
    if '//' in domain:
        return "Invalid"
    # The original url except for scheme can also not contain '//' outside the scheme
    scheme_len = url.find('://') + 3
    trailing = url[scheme_len:]
    if '//' in trailing and trailing.find('//') != 0:
        return "Invalid"

    # Query part check
    if '?' in url:
        q = url.split('?',1)[1]
        q = q.split('#',1)[0] # not relevant but just in case
        if len(q) > 20:
            return "Invalid"
    return "Valid"

def main():
    url = sys.stdin.readline().strip()
    print(is_valid_url(url))

if __name__ == "__main__":
    main()

