import threading

class FibonacciThread(threading.Thread):
    def __init__(self, num):
        threading.Thread.__init__(self)
        self.num = num
        self.fib_series = [0, 1]

    def run(self):
        try:
            if self.num <= 0:
                raise ValueError("Input must be a positive integer.")
            elif self.num == 1:
                self.fib_series = [0]
            else:
                for i in range(2, self.num):
                    next_number = self.fib_series[i-1] + self.fib_series[i-2]
                    self.fib_series.append(next_number)
        except Exception as e:
            print(str(e))

    def get_sequence(self):
        return self.fib_series

    def get_number_at_position(self, pos):
        try:
            if pos < 0 or pos >= len(self.fib_series):
                raise ValueError("Position is outside the sequence.")
            return self.fib_series[pos]
        except Exception as e:
            print(str(e))

def test_fibonacci_thread():
    num = 10
    fib_thread = FibonacciThread(num)
    fib_thread.start()
    fib_thread.join()  # wait for the thread to finish

    print("Fibonacci sequence: ", fib_thread.get_sequence())
    print("Number at position 7 in the sequence: ", fib_thread.get_number_at_position(7))

test_fibonacci_thread()
```
Here, we create a new thread for each calculation of the Fibonacci series up to a specified limit. The Fibonacci series is stored in an array (list in Python), which has O(1) retrieval time. In terms of exception handling, we check if the input is a positive integer or not, as well as whether position we want to retrieve from series is within range.

