# Bit positions for vowels: a=0, e=1, i=2, o=3, u=4
def main():
    data = sys.stdin.read().splitlines()
    idx = 0
    T = int(data[idx]); idx += 1
    for _ in range(T):
        N = int(data[idx]); idx += 1
        freq = [0]*32  # frequency for each vowel mask (2^5)
        for _ in range(N):
            s = data[idx].strip(); idx += 1
            mask = 0
            for ch in set(s):
                if ch == 'a':
                    mask |= 1
                elif ch == 'e':
                    mask |= 2
                elif ch == 'i':
                    mask |= 4
                elif ch == 'o':
                    mask |= 8
                elif ch == 'u':
                    mask |= 16
            freq[mask] += 1
        total = 0
        for m1 in range(32):
            if not freq[m1]:
                continue
            for m2 in range(m1, 32):
                if not freq[m2]:
                    continue
                if (m1 | m2) == 31:
                    if m1 == m2:
                        total += freq[m1]*(freq[m1]-1)//2
