def count_target_in_matrix(mat, target):
    def helper(row, col):
        if row >= len(mat) or col < 0:
            return 0
        if mat[row][col] == target:
            return 1 + helper(row + 1, col) + helper(row, col - 1)
        elif mat[row][col] < target:
            return helper(row + 1, col)
        else:
            return helper(row, col - 1)
    return helper(0, len(mat[0]) - 1)

