def isPalindrome(s):
    s = ''.join(c for c in s if c.isalnum()).lower()
    return s == s[::-1]

class TestIsPalindrome(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(isPalindrome(""))

    def test_single_character(self):
        self.assertTrue(isPalindrome("a"))
        self.assertTrue(isPalindrome("Z"))

    def test_simple_palindromes(self):
        self.assertTrue(isPalindrome("radar"))
        self.assertTrue(isPalindrome("level"))
        self.assertTrue(isPalindrome("deified"))

    def test_non_palindromes(self):
        self.assertFalse(isPalindrome("hello"))
        self.assertFalse(isPalindrome("world"))
        self.assertFalse(isPalindrome("python"))

    def test_palindromes_with_spaces_and_different_cases(self):
        self.assertTrue(isPalindrome("A man a plan a canal Panama"))
        self.assertTrue(isPalindrome("No lemon no melon"))
        self.assertTrue(isPalindrome("Was it a car or a cat I saw"))

    def test_palindromes_with_punctuation(self):
        self.assertTrue(isPalindrome("Madam, in Eden, I'm Adam"))
        self.assertTrue(isPalindrome("Able was I, I saw Elba"))
        self.assertTrue(isPalindrome("Step on no pets"))

    def test_long_string_performance(self):
        long_str = "a" * 10000 + "b" + "a" * 10000
        self.assertTrue(isPalindrome(long_str))

    def test_non_alphanumeric_characters(self):
        self.assertTrue(isPalindrome("!@#$%^&*()_+"))
        self.assertFalse(isPalindrome("!@#$%^&*()_+A"))

    def test_large_varied_character_set(self):
