import math

class Point3D:
    def __init__(self, x=0, y=0, z=0):
        self.x = x
        self.y = y
        self.z = z

    def distance_to(self, other):
        return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2 + (self.z - other.z) ** 2)

    def angle_between(self, other):
        if self == other:
            return None
        vector_x = other.x - self.x
        vector_y = other.y - self.y
        vector_z = other.z - self.z
        vector_length = math.sqrt(vector_x ** 2 + vector_y ** 2 + vector_z ** 2)
        x_component = vector_x / vector_length
        y_component = vector_y / vector_length
        z_component = vector_z / vector_length
        angle = math.atan2(math.sqrt(y_component**2 + z_component**2), x_component)
        return angle

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y and self.z == other.z

def main():
