def is_valid_email(email):
    # Very simplified validation: one @, non-empty local and domain, no spaces
    if "@" not in email or email.count("@") != 1:
        return False
    local, domain = email.split("@", 1)
    if not local or not domain:
        return False
    # Check local part
    allowed_local = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!#$%&'*+/=?^_`{|}~.-")
    for ch in local:
        if ch not in allowed_local and not ch.isalnum():
            # allow unicode letters/digits
            if not (u'\u0080' <= ch <= u'\uffff'):
                return False
    # Check for leading/trailing dot or double dots in local
    if local[0] == '.' or local[-1] == '.' or '..' in local:
        return False
    # Check domain labels
    domain_labels = domain.split('.')
    if len(domain_labels) < 2:
        return False
    for label in domain_labels:
        if not label or label[0] == '-' or label[-1] == '-':
            return False
        for ch in label:
            if not (ch.isalnum() or ch == '-' or (u'\u0080' <= ch <= u'\uffff')):
                return False
    # Domain part must not have double dots
    if '..' in domain:
        return False
    return True

def main():
    email = input().strip()
    print(str(is_valid_email(email)))

