class FibonacciMemo:
    def __init__(self):
        self.memo = [0, 1]

    def get(self, n):
        if n < len(self.memo):
            return self.memo[n]
        return None

    def set(self, n, value):
        while len(self.memo) <= n:
            self.memo.append(None)
        self.memo[n] = value

def fibonacci(n, memo=None):
    if memo is None:
        memo = FibonacciMemo()
    if n == 0:
        return 0
    elif n == 1:
        return 1
    fib_n = memo.get(n)
    if fib_n is not None:
        return fib_n
    fib_n = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    memo.set(n, fib_n)
    return fib_n

def generate_fibonacci_sequence(n):
    seq = []
    for i in range(n):
        seq.append(fibonacci(i))
    return seq

def main():
