class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def sortedArrayToBST(nums):
    if not nums:
        return None
    dummy_root = TreeNode()
    queue = [(0, len(nums)-1, dummy_root, True)]
    while queue:
        low, high, parent, is_left_child = queue.pop(0)
        mid = (low + high) // 2
        node = TreeNode(nums[mid])
        if is_left_child:
            parent.left = node
        else:
            parent.right = node
        if low <= mid - 1:
            queue.append((low, mid-1, node, True))
        if mid + 1 <= high:
            queue.append((mid+1, high, node, False))
    return dummy_root.left

def print_level_order(root):
    if not root:
        print()
        return
    queue = [root]
    result = []
    while queue:
        node = queue.pop(0)
        result.append(str(node.val))
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    print(' '.join(result))

def main():
    n = int(input())
    if n == 0:
        print()
        return
    arr = list(map(int, input().split()))
    root = sortedArrayToBST(arr)
    print_level_order(root)

