def merge_in_zigzag(l1, l2):
    if not l1:
        return l2
    if not l2:
        return l1
    head = l1
    tail = l1
    l1 = l1.next
    turn = True
    while l1 and l2:
        if turn:
            tail.next = l2
            l2 = l2.next
        else:
            tail.next = l1
            l1 = l1.next
        turn = not turn
        tail = tail.next
    if l1:
        tail.next = l1
    if l2:
