def find_all_occurrences(sorted_list, target):
    def find_first_occurrence(arr, x):
        left, right = 0, len(arr) - 1
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < x:
                left = mid + 1
            else:
                right = mid
        if left < len(arr) and arr[left] == x:
            return left
        return -1

    n = len(sorted_list)
    if n == 0:
        return []
    first = find_first_occurrence(sorted_list, target)
    if first == -1:
        return []
    indices = []
    i = first
    while i < n and sorted_list[i] == target:
        indices.append(i)
        i += 1
    return indices

