class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def remove(self, key):
        current = self.head
        prev = None

        # If head node itself holds the key to be deleted
        if current is not None:
            if current.data == key:
                self.head = current.next
                return

        # Search for the key to be deleted, keep track of prev
        while current is not None:
            if current.data == key:
                break
            prev = current
            current = current.next

        # Key not found
        if current is None:
            print("Key not found in the list.")
            return

        prev.next = current.next

    def display(self):
        current = self.head
        while current:
            print(current.data, end=" -> ")
            current = current.next
        print("None")

