import functools
import sys

def custom_hash(n):
    def prime_factors(n):
        factors = {}
        d = 2
        while n > 1:
            if n % d == 0:
                factors[d] = factors.get(d, 0) + 1
                n //= d
            else:
                d += 1
        return factors
    fact = prime_factors(n)
    return hash(tuple(sorted(fact.items())))

def memoize_custom_hash(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(arg):
        h = custom_hash(arg)
        if h not in cache:
            cache[h] = func(arg)
        return cache[h]
    return wrapper

@memoize_custom_hash
