import ast

class Polynomial:
    def __init__(self, terms, base=3):
        # terms: [[real, imag, exp], [...]]
        # convert to internal [[complex, exponent], ...]
        self.terms = [[complex(real, imag), exp] for real, imag, exp in terms]
        self.base = base
        self.simplify()

    def simplify(self):
        term_dict = {}
        for coeff, exp in self.terms:
            if exp in term_dict:
                term_dict[exp] += coeff
            else:
                term_dict[exp] = coeff
        # Remove zero terms
        filtered = []
        for exp, coeff in term_dict.items():
            if abs(coeff.real) > 1e-9 or abs(coeff.imag) > 1e-9:
                filtered.append([coeff, exp])
        self.terms = sorted(filtered, key=lambda x: x[1], reverse=True)

    def add(self, other):
        if self.base != other.base:
            raise ValueError("Polynomials have different base exponents.")
        return Polynomial(
            [[t[0].real, t[0].imag, t[1]] for t in self.terms] + [[t[0].real, t[0].imag, t[1]] for t in other.terms],
            self.base)

    def subtract(self, other):
        if self.base != other.base:
            raise ValueError("Polynomials have different base exponents.")
        terms = [[t[0].real, t[0].imag, t[1]] for t in self.terms]
        for t in other.terms:
            terms.append([-t[0].real, -t[0].imag, t[1]])
        return Polynomial(terms, self.base)

    def multiply(self, other):
        if self.base != other.base:
            raise ValueError("Polynomials have different base exponents.")
        res_terms = []
        for c1, e1 in self.terms:
            for c2, e2 in other.terms:
                prod = c1 * c2
                res_terms.append([prod.real, prod.imag, e1+e2])
        return Polynomial(res_terms, self.base)

    def to_list(self):
        out = []
        for coeff, exp in self.terms:
            real, imag = float(coeff.real), float(coeff.imag)
            # if small enough, set to 0.0
            if abs(real) < 1e-9:
                real = 0.0
            if abs(imag) < 1e-9:
                imag = 0.0
            out.append([real, imag, exp])
        return out

