def roman_to_int(s):
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    subtractive_pairs = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}
    # For validation: maximal number for Roman numeral 3999 (MMMCMXCIX)
    result = 0
    i = 0
    length = len(s)
    # Check for invalid chars early
    valid_chars = set(roman_dict.keys())
    if any(c not in valid_chars for c in s):
        return -1
    # Check for more than three repetitions
    prev_char = ''
    count = 0
    for c in s:
        if c == prev_char:
            count += 1
            if c in 'VLD' and count > 1:
                return -1
            elif count > 3:
                return -1
        else:
            prev_char = c
            count = 1
    # Conversion
    result = 0
    i = 0
    while i < length:
        # Check for subtractive pairs
        if i + 1 < length and s[i:i+2] in subtractive_pairs:
            result += subtractive_pairs[s[i:i+2]]
            i += 2
        else:
            # Subtractive misuses: e.g. IL, IC, VX, etc.
            if (i+1 < length
                and roman_dict[s[i]] < roman_dict[s[i+1]]
                and s[i:i+2] not in subtractive_pairs):
                return -1
            result += roman_dict[s[i]]
            i += 1
    # Validation: input must match canonical roman output
    if int_to_roman(result) != s:
        return -1
    return result

def int_to_roman(num):
    val = [1000,900,500,400,100,90,50,40,10,9,5,4,1]
    syms = ["M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"]
    roman_num = ''
    i = 0
    while num > 0:
        for _ in range(num // val[i]):
            roman_num += syms[i]
            num -= val[i]
        i += 1
    return roman_num

