class Stack:
    def __init__(self):
        self.items = []
        self.log = []

    def push(self, item):
        self.items.append(item)
        self.log.append("Pushed " + str(item))

    def pop(self):
        if not self.is_empty():
            item = self.items.pop()
            self.log.append("Popped " + str(item))
            return item
        self.log.append("Popped from an empty stack")
        return None

    def peek(self):
        if not self.is_empty():
            item = self.items[-1]
            self.log.append("Peeked " + str(item))
            return item
        self.log.append("Peeked from an empty stack")
        return None

    def is_empty(self):
        return len(self.items) == 0

    def get_log(self):
        return self.log

