        # Check presence in list2
        found = False
        for j in range(len(list2)):
            if list2[j] == element:
                found = True
                break
        # Uniqueness in intersection
        is_unique = True
        for k in range(len(intersection)):
            if intersection[k] == element:
                is_unique = False
                break
        if found and is_unique:
            # Manually "append" element
            new_intersection = [0] * (len(intersection)+1)
            for idx in range(len(intersection)):
                new_intersection[idx] = intersection[idx]
            new_intersection[len(intersection)] = element
            intersection = new_intersection

    # Manual sort (insertion sort)
    for i in range(1, len(intersection)):
        key = intersection[i]
        j = i-1
        while j >= 0 and intersection[j] > key:
            intersection[j+1] = intersection[j]
            j -= 1
        intersection[j+1] = key

