from typing import List, Union, Optional

def nested_list_summary(nested_list: List[Union[int, List]]) -> List[List[int]]:
    """
    For every non-empty list that appears in the outermost level of `nested_list`,
    return the first and last integer encountered inside that sub-list (no matter
    how deeply they are nested).
    """

    def first_int(lst: List[Union[int, List]]) -> Optional[int]:
        """Depth-first search from the left to get the first integer."""
        for item in lst:
            if isinstance(item, int):
                return item
            if isinstance(item, list):
                value = first_int(item)
                if value is not None:
                    return value
        return None

    def last_int(lst: List[Union[int, List]]) -> Optional[int]:
        """Depth-first search from the right to get the last integer."""
        for item in reversed(lst):
            if isinstance(item, int):
                return item
            if isinstance(item, list):
                value = last_int(item)
                if value is not None:
                    return value
        return None

    result: List[List[int]] = []
    for sub in nested_list:
        if isinstance(sub, list) and sub:          # only consider non-empty lists
            first = first_int(sub)
            last = last_int(sub)
            if first is not None and last is not None:
                result.append([first, last])

    return result

