class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def is_prime(self, num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def exists(self, key):
        node = self.root
        while node:
            if key == node.val:
                return True
            elif key < node.val:
                node = node.left
            else:
                node = node.right
        return False

    def insert(self, key):
        if self.is_prime(key) and not self.exists(key):
            self.root = self._insert_rec(self.root, key)

    def _insert_rec(self, node, key):
        if node is None:
            return TreeNode(key)
        if key < node.val:
            node.left = self._insert_rec(node.left, key)
        elif key > node.val:
            node.right = self._insert_rec(node.right, key)
        return node

    def inorder_traversal(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node:
            self._inorder(node.left, result)
            result.append(node.val)
            self._inorder(node.right, result)

    def kth_smallest(self, k):
        arr = self.inorder_traversal()
        if 1 <= k <= len(arr):
            return arr[k-1]
        else:
            return None

