```go
package main

import (
	"fmt"
	"strings"
)

func LongestSubstring(strings []string) (substr string) {
	n := len(strings)
	if n == 0 {
		return ""
	}

	var shortestStr string
	m := len(strings[0])
	for _, s := range strings {
		if len(s) < m {
			shortestStr = s
			m = len(s)
		}
	}

	var strsFiltered []string
	for _, s := range strings {
		if len(s) >= m {
			strsFiltered = append(strsFiltered, s)
		}
	}

	n = len(strsFiltered)
	lcs := make([][]int, n+1)
	for i := range lcs {
		lcs[i] = make([]int, m+1)
	}

	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if strsFiltered[i-1] == shortestStr[j-1:j] {
				lcs[i][j] = lcs[i-1][j-1] + 1
			} else {
				lcs[i][j] = max(lcs[i-1][j], lcs[i][j-1])
			}
		}
	}

	index := lcs[n][m]
	i, j := n, m
	commonStrs := make([]string, index)
	for i > 0 && j > 0 {
		if shortestStr[j-1:j] == strsFiltered[i-1] {
			index--
			commonStrs[index] = strsFiltered[i-1]
			i--
			j--

		} else if lcs[i-1][j] > lcs[i][j-1] {
			i--
		} else {
			j--
		}
	}

	return strings.Join(commonStrs, "")
}

func max(x, y int) int {
	if x > y {
		return x
	}
	return y
}

