def integer_square_root(n):
    if n < 0:
        raise ValueError("Negative input")
    if n == 0 or n == 1:
        return n
    low, high = 1, n
    while low <= high:
        mid = low + (high - low) // 2
        mid_squared = mid * mid
        if mid_squared == n:
            return mid
        elif mid_squared < n:
            low = mid + 1
        else:
            high = mid - 1
    return high

