import Foundation

func peculiarOrdering(_ lst: inout [Int?]) -> [Int] {
    // Remove nil values
    lst = lst.compactMap { $0 }

    // Check if the list is empty after removing nil values
    if lst.isEmpty {
        return []
    }

    var outList = [Int]()
    while !lst.isEmpty {
        // Add the smallest element
        if let minValue = lst.min() {
            outList.append(minValue)
            // Remove the smallest element
            lst.removeAll(where: { $0 == minValue })
        }

        // Check if list still has elements
        if !lst.isEmpty {
            // Add the largest element
            if let maxValue = lst.max(){
                outList.append(maxValue)
                // Remove the largest element
                lst.removeAll(where: { $0 == maxValue })
            }
        }
    }
    return outList
}
```

The logic of this Swift function is similar to your Python function:

1. Remove the `nil` values from the list.
2. Check if the list is empty. If it is, return an empty array.
3. While the list is not empty, add the smallest (`min()`) element to the `outList` list.
4. Remove that smallest element from the original array using `removeAll(where:)`.
5. If the list is not empty, add the largest element (`max()`) to the `outList` list.
6. Again remove that largest element from the original list.
7. Continue this process until the original list has no elements left.
8. Return the `outList`.

Please note that in Swift we use `Array` instead of `List` and `nil` instead of `None`.

