def quicksort(arr):
    def sort(low, high):
        if low >= high:
            return
        pivot = arr[(low + high) // 2]
        lt, gt = low, high
        i = low
        while i <= gt:
            if arr[i] < pivot:
                arr[lt], arr[i] = arr[i], arr[lt]
                lt += 1
                i += 1
            elif arr[i] > pivot:
                arr[gt], arr[i] = arr[i], arr[gt]
                gt -= 1
            else:
                i += 1
        sort(low, lt - 1)
        sort(gt + 1, high)
    sort(0, len(arr) - 1)
    return arr

def main():
    n = int(input())
    arr = list(map(int, input().split()))
    quicksort(arr)
    print(' '.join(map(str, arr)))

