import itertools
from dataclasses import dataclass

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

class PrimeIDGenerator:
    def __init__(self):
        self.prime_generator = (num for num in itertools.count(2) if is_prime(num))

    def get_next_prime(self):
        return next(self.prime_generator)

prime_id_generator = PrimeIDGenerator()

@dataclass(frozen=True)
class Transaction:
    transaction_id: int
    amount: float
    transaction_type: str  # 'deposit' or 'withdraw'

class Account:
    def __init__(self, initial_balance=0.0):
        self._balance = initial_balance
        self.transactions = []

    def deposit(self, amount):
        if amount <= 0:
            print("Deposit amount must be positive.")
            return
        self._balance = self._balance + amount
        self.transactions.append(Transaction(transaction_id=prime_id_generator.get_next_prime(),
                                              amount=amount, transaction_type='deposit'))

    def withdraw(self, amount):
        if amount <= 0:
            print("Withdrawal amount must be positive.")
            return
        if self._balance < amount:
            print("Insufficient funds.")
            return
        self._balance = self._balance - amount
        self.transactions.append(Transaction(transaction_id=prime_id_generator.get_next_prime(),
                                              amount=amount, transaction_type='withdraw'))

    def get_balance(self):
        return self._balance

    def get_transaction_history(self):
        return self.transactions

