def validate(s):
    stack = []
    i = 0
    n = len(s)
    while i < n:
        if s[i:i+2] == '{{':
            open_braces = 1
            i += 2
            seg = ''
            while i < n and open_braces > 0:
                if s[i:i+2] == '{{':
                    open_braces += 1
                    seg += '{{'
                    i += 2
                elif s[i:i+2] == '}}':
                    open_braces -= 1
                    if open_braces > 0:
                        seg += '}}'
                    i += 2
                else:
                    seg += s[i]
                    i += 1
            if open_braces != 0:
                return False
            if seg and not validate(seg):
                return False
            continue
        elif s[i] in '([{':
            stack.append(s[i])
        elif s[i] in ')]}':
            if not stack or not is_match(stack.pop(), s[i]):
                return False
        i += 1
    return len(stack) == 0

