In a binary search tree, each node should have elements lesser than it on its left subtree and the elements greater than it on its right subtree. Below is a Python implementation of a binary search tree with a search function.

```Python
class Node:
    def __init__(self, item):
        self.val = item
        self.left = None
        self.right = None


def inorder(root):
    if root:
        inorder(root.left)
        print(root.val)
        inorder(root.right)


def insert(node, item):
    if node is None:
        return Node(item)
    if item < node.val:
        node.left = insert(node.left, item)
    else:
        node.right = insert(node.right, item)
    return node


def search(node, item):
    if node is None or node.val == item:
        return node
    if node.val < item:
        return search(node.right, item)
    return search(node.left, item)


items = [5, 4, 9, 15, 13, 18]
root = None
for item in items:
    root = insert(root, item)

print("Inorder traversal of the constructed tree is:")
inorder(root)

print("\nSearch for item 9:")
found = search(root, 9)
if found:
    print("Item found")
else:
    print("Item not found")

print("\nSearch for item 20:")
found = search(root, 20)
if found:
    print("Item found")
else:
    print("Item not found")
```

