class ParkingGarage:
    def __init__(self, num_spots):
        self.num_spots = num_spots
        self.available_spots = set(range(num_spots))
        self.parked_cars = {}
    def park_car(self, car_id):
        if not self.available_spots:
            print("No available spots")
            return
        spot = min(self.available_spots)
        self.available_spots.remove(spot)
        self.parked_cars[car_id] = spot
        print(f"Car {car_id} parked at spot {spot}")
    def remove_car(self, car_id):
        if car_id not in self.parked_cars:
            print(f"Car {car_id} is not in the garage")
            return
        spot = self.parked_cars.pop(car_id)
        self.available_spots.add(spot)
        print(f"Car {car_id} removed from spot {spot}")
    def check_availability(self):
        print(len(self.available_spots))

def main():
