def int_to_roman(num):
    if not isinstance(num, int) or num <= 0 or num > 3999:
        raise ValueError("Input must be an integer between 1 and 3999")

    def convert_to_roman(n):
        if n == 0:
            return ""
        elif n >= 1000:
            return "M" + convert_to_roman(n - 1000)
        # For 900, compose DCCCC instead of CM
        elif n >= 900:
            return "D" + "C"*4 + convert_to_roman(n - 900)
        elif n >= 500:
            return "D" + convert_to_roman(n - 500)
        # For 400, compose CCCC instead of CD
        elif n >= 400:
            return "C"*4 + convert_to_roman(n - 400)
        elif n >= 100:
            return "C" + convert_to_roman(n - 100)
        # For 90, compose LXXXX instead of XC
        elif n >= 90:
            return "L" + "X"*4 + convert_to_roman(n - 90)
        elif n >= 50:
            return "L" + convert_to_roman(n - 50)
        # For 40, compose XXXX instead of XL
        elif n >= 40:
            return "X"*4 + convert_to_roman(n - 40)
        elif n >= 10:
            return "X" + convert_to_roman(n - 10)
        # For 9, compose VIIII instead of IX
        elif n >= 9:
            return "V" + "I"*4 + convert_to_roman(n - 9)
        elif n >= 5:
            return "V" + convert_to_roman(n - 5)
        # For 4, compose IIII instead of IV
        elif n >= 4:
            return "I"*4 + convert_to_roman(n - 4)
        elif n >= 1:
            return "I" + convert_to_roman(n - 1)
        return ""

    return convert_to_roman(num)

