def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    elif n <= 3:
        return True
    elif n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def stair_case_sum(n):
    """Sum all prime numbers generated from various methods of ascending a staircase with n steps."""
    if n <= 0:
        return 0
    else:
        staircase_sum = [0 for _ in range(n+1)]
        staircase_sum[0] = staircase_sum[1] = 1

        for i in range(2, n+1):
            for j in range(1, i):
                if is_prime(j):
                    staircase_sum[i] += staircase_sum[i-j]
        return staircase_sum[n]

print(stair_case_sum(5))
