def evaluate_expression(expression):
    # Tokenize
    res = ''
    i = 0
    n = len(expression)
    while i < n:
        ch = expression[i]
        if ch in '+-*/()':
            # Handle unary - (negative number)
            if ch == '-' and (i == 0 or expression[i-1] in '+-*/('):
                res += ch
                i += 1
                continue
            res += ' ' + ch + ' '
        else:
            res += ch
        i += 1
    tokens = res.split()
    values = []
    operators = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if is_number(token):
            values.append(float(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(': 
                apply_operator(operators, values)
            operators.pop()
        else: # operator
            while operators and operators[-1] != '(' and precedence(operators[-1]) >= precedence(token):
                apply_operator(operators, values)
            operators.append(token)
        i += 1
    while operators:
        apply_operator(operators, values)
    return values[0]

