def insert_bst(root, val):
    if not root:
        return TreeNode(val)
    if val < root.val:
        root.left = insert_bst(root.left, val)
    else:
        root.right = insert_bst(root.right, val)
    return root

def bstToDoublyLinkedList(root):
    if not root:
        return None
    dummy = TreeNode(0)
    prev = dummy
    current = root
    while current:
        if current.left is None:
            prev.right = current
            current.left = prev
            prev = current
            current = current.right
        else:
            pre = current.left
            while pre.right and pre.right != current:
                pre = pre.right
            if pre.right:
                pre.right = None
                prev.right = current
                current.left = prev
                prev = current
                current = current.right
            else:
                pre.right = current
                current = current.left
    head = dummy.right
    if head:
        head.left = None
    if prev != dummy:
        prev.right = None
    return head

