import sys
import json

def parse_json(json_obj, seen=None):
    if seen is None:
        seen = set()
    obj_id = id(json_obj)
    # Check for cyclic references
    if obj_id in seen:
        return "Cyclic reference detected"
    # Only traverse collections
    if isinstance(json_obj, (dict, list, tuple)):
        seen.add(obj_id)
    # Handle dictionary
    if isinstance(json_obj, dict):
        return {k: parse_json(v, seen) for k, v in json_obj.items()}
    # Handle list
    elif isinstance(json_obj, list):
        return [parse_json(item, seen) for item in json_obj]
    # Handle tuple (not usually in JSON, but here for completeness)
    elif isinstance(json_obj, tuple):
        return tuple(parse_json(item, seen) for item in json_obj)
    # Handle primitive types
    elif isinstance(json_obj, (str, int, float, bool)) or json_obj is None:
        return json_obj
    else:
        raise TypeError("Unsupported data type")

def main():
    import sys
    import json
    s = sys.stdin.read()
    json_obj = json.loads(s)
    result = parse_json(json_obj)
