def calculate_average(numbers):
    if not numbers:
        return None
    total = 0
    count = 0
    for number in numbers:
        total += number
        count += 1
    average = total / count
    return round(average, 6)

def calculate_median(numbers):
    if not numbers:
        return None
    n = len(numbers)
    numbers_sorted = sorted(numbers)
    mid = n // 2
    if n % 2 == 0:
        median = (numbers_sorted[mid - 1] + numbers_sorted[mid]) / 2
    else:
        median = numbers_sorted[mid]
    return round(median, 6)

def calculate_mode(numbers):
    if not numbers:
        return None
    frequency = {}
    for number in numbers:
        if number in frequency:
            frequency[number] += 1
        else:
            frequency[number] = 1
    max_count = 0
    for value in frequency.values():
        if value > max_count:
            max_count = value
    modes = []
    for key, value in frequency.items():
        if value == max_count:
            modes.append(key)
    if len(modes) == len(numbers):
        return None
    if len(modes) == 1:
        return modes[0]
    return modes

