class Solution {
    public List<Integer> sortThird(List<Integer> l) {

        List<Integer> sortedElements = new ArrayList<Integer>();
        for (int i = 0; i < l.size(); i++) {
            if (i % 3 == 0) sortedElements.add(l.get(i));
        }

        Collections.sort(sortedElements);
        int k = 0;
        for (int i = 0; i < l.size(); i++) {
            if (i % 3 == 0) l.set(i, sortedElements.get(k++));
        }
        return l;
    }
