from typing import List

def separate_paren_groups(paren_string: str, complete_sets: bool = True) -> List[str]:
    stack = []
    result = []
    last_open = {}

    brackets = {'(':')', '[':']', '{':'}'}

    for index, char in enumerate(paren_string):
        if char in brackets.keys():
            # Char is an open bracket
            stack.append(index)
            last_open[brackets[char]] = len(stack)-1
        elif char in brackets.values():
            # Char is a close bracket
            if stack and last_open.get(char, -1) == len(stack) - 1:
                start = stack.pop()
                result.append(paren_string[start:index+1])
                last_open.pop(char)
            elif not complete_sets:
                result.append(char)
        elif not char.isspace():
            # Char is not a bracket or whitespace; treat it as part of the last group
            if result:
                result[-1] += char
            else:
                result.append(char)

    if not complete_sets:
        # Include any remaining unbalanced brackets as separate groups
        while stack:
            start = stack.pop()
            result.append(paren_string[start:])
    return result

In the original Python function, it used special features that are not available in C, including dictionary (hash map), dynamic lists, string manipulation, etc. To fully adapt this function to C, you need to replace these functionality with C equivalents.

C does not have a built-in hash map, but a 2D char array can be used equivalent to the dictionary above. Check the entered char whether there is in this array.

C does not dynamically resize arrays. A maximum size for the array needs to be declared at the beginning of the function. Additional functionality must also be implemented to handle the situation where the maximum size is exceeded.

In C, in order to append strings we must use strcpy and strcat function. Also, to achieve something like list slicing we must use memcpy and to get last element of char array we must calculate the length of the string then subtract 1.

Considering all these constraints, the adapted function could look something like this:

```c
#include <string.h>
#include <stdlib.h>

#define MAX_SIZE 100

void separate_paren_groups(char *paren_string, int complete_sets, char result[MAX_SIZE][MAX_SIZE]) {
    int stack[MAX_SIZE];
    char last_open[MAX_SIZE];
    int top = -1;
    int i, j = 0;

    char brackets[6] = {'(', ')', '[', ']', '{', '}'};

    int len = strlen(paren_string);
    for(i = 0; i<len; i++) {
        char ch = paren_string[i];
        if (strchr(brackets, ch)) {
            // Char is an open bracket
            stack[++top] = i;
            if (ch == '(')
                last_open[top] = ')';
            else if (ch == '[')
                last_open[top] = ']';
            else if (ch == '{')
                last_open[top] = '}';
        } 
        else if (strchr(brackets, ch)) {
            // Char is a close bracket
            if (top > -1 && last_open[top] == ch) {
                char temp[MAX_SIZE];
                memcpy(temp, &paren_string[stack[top]], i - stack[top] + 1);
                temp[i - stack[top] + 1] = '\0';
                strcpy(result[j++], temp);
                top--;
            } 
            else if (!complete_sets) {
                char temp[2] = {ch, '\0'};
                strcpy(result[j++], temp);
            }
        } 
        else if (ch != ' '){
            // Char is not a bracket or whitespace; treat it as part of the last group
            if (j > 0) {
                char temp[2] = {ch, '\0'};
                strcat(result[j-1], temp);
            }
            else {
                char temp[2] = { ch, '\0'};
                strcpy(result[j++], temp);
            }
        }
    }

    if (!complete_sets) {
        // include any remaining unbalanced brackets as separate groups
        while (top > -1) {
            char temp[MAX_SIZE];
            memcpy(temp, &paren_string[stack[top]], len - stack[top]);
            temp[len - stack[top]] = '\0';
            strcpy(result[j++], temp);
            top--;
        }
    }
}
