Here is a simple implementation in JavaScript using a regex pattern. The auxiliary function "extractCharacters" retrieves a specified count of either alphabetic or alphanumeric characters from a supplied string of characters.

```javascript
function extractCharacters(inputString, count, type) {
    var pattern;
    // check if type is alphabetic or alphanumeric
    if (type === 'alphabetic') {
        pattern = /[a-zA-Z]/g;
    } else if (type === 'alphanumeric') {
        pattern = /[a-zA-Z0-9]/g;
    } else {
        return 'Invalid type allowed types are alphabetic and alphanumeric';
    }

    // find matches using the defined pattern
    var matches = inputString.match(pattern);
    if (!matches || matches.length === 0) {
        return 'No matches found';
    }

    // return the specified count of matches
    return matches.splice(0, count).join('');
}

