import sys

def possible(n: int, s: int, x: int) -> bool:
    # Case with only one element: it must be exactly X to get the right XOR and sum.
    if n == 1:
        return s == x

    # For n >= 2 we need (s - x) to be non-negative and even.
    if s < x:
        return False
    if (s - x) & 1:
        return False

    # For n == 2 we need the two numbers to be a and a+X with a >= 0 and a & X == 0.
    if n == 2:
        a = (s - x) // 2
        if (a & x) != 0:
            return False

    # All other cases are possible.
    return True


