import sys, heapq

def solve_one_dataset(n, m, edges):
    adj = [[] for _ in range(n + 1)]
    for a, b, c in edges:
        adj[a].append((b, c))
        adj[b].append((a, c))

    INF = 10 ** 18
    # dist[v][state] where state: 0 = ticket not used yet
    # 1 = first free edge taken (need one more free edge)
    # 2 = ticket already completely used
    dist = [[INF] * 3 for _ in range(n + 1)]
    dist[1][0] = 0
    pq = [(0, 1, 0)]  # (cost, vertex, state)

    while pq:
        cost, u, s = heapq.heappop(pq)
        if cost != dist[u][s]:
            continue
        for v, c in adj[u]:
            if s == 0:  # ticket not started
                # pay the edge
                if cost + c < dist[v][0]:
                    dist[v][0] = cost + c
                    heapq.heappush(pq, (cost + c, v, 0))
                # start the free sequence
                if cost < dist[v][1]:
                    dist[v][1] = cost
                    heapq.heappush(pq, (cost, v, 1))
            elif s == 1:  # one free edge already taken, this is the second one
                if cost < dist[v][2]:
                    dist[v][2] = cost
                    heapq.heappush(pq, (cost, v, 2))
            else:  # s == 2, ticket finished
                if cost + c < dist[v][2]:
                    dist[v][2] = cost + c
                    heapq.heappush(pq, (cost + c, v, 2))

    return min(dist[n][0], dist[n][2])


