class Graph:
    def __init__(self, vertices):
        self.V = vertices
        self.graph = [[0 for _ in range(vertices)] for _ in range(vertices)]

    def add_edge(self, u, v, weight):
        self.graph[u][v] = weight
        self.graph[v][u] = weight  # Undirected graph

    def dijkstra(self, src):
        dist = [float("Inf")] * self.V
        dist[src] = 0
        sptSet = [False] * self.V
        prev = [-1] * self.V

        for _ in range(self.V):
            u = self.min_distance(dist, sptSet)
            sptSet[u] = True

            for v in range(self.V):
                if self.graph[u][v] > 0 and not sptSet[v]:
                    if dist[v] > dist[u] + self.graph[u][v]:
                        dist[v] = dist[u] + self.graph[u][v]
                        prev[v] = u
        return dist, prev

    def min_distance(self, dist, sptSet):
        min_val = float("Inf")
        min_index = -1
        for v in range(self.V):
            if not sptSet[v] and dist[v] < min_val:
                min_val = dist[v]
                min_index = v
        return min_index if min_index != -1 else 0

    def get_shortest_path(self, src, dest):
        dist, prev = self.dijkstra(src)
        if dist[dest] == float("Inf"):
            return "No path from source to destination"
        path = []
        at = dest
        while at != -1:
            path.insert(0, at)
            if at == src:
                break
            at = prev[at]
        return path

    def display_graph(self):
        for row in self.graph:
            print(' '.join(str(num) for num in row))

def main():
