def ternary_max_heapify(arr, n, i):
    largest = i
    left = 3 * i + 1
    middle = 3 * i + 2
    right = 3 * i + 3

    if left < n and arr[left] > arr[largest]:
        largest = left
    if middle < n and arr[middle] > arr[largest]:
        largest = middle
    if right < n and arr[right] > arr[largest]:
        largest = right

    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        ternary_max_heapify(arr, n, largest)

def build_max_ternary_heap(arr):
    n = len(arr)
    start_index = (n - 2) // 3
    for i in range(start_index, -1, -1):
        ternary_max_heapify(arr, n, i)

def heap_sort(arr):
