def merge_sort(arr):
    if len(arr) <= 1:
        return [(arr[0], 1)] if arr else []
    mid = len(arr) // 2
    left_half = merge_sort(arr[:mid])
    right_half = merge_sort(arr[mid:])
    return merge(left_half, right_half)

def merge(left, right):
    sorted_counted_list = []
    i = j = 0
    while i < len(left) and j < len(right):
        left_val, left_count = left[i]
        right_val, right_count = right[j]
        if left_val < right_val:
            sorted_counted_list.append(left[i])
            i += 1
        elif left_val > right_val:
            sorted_counted_list.append(right[j])
            j += 1
        else:
            sorted_counted_list.append((left_val, left_count + right_count))
            i += 1
            j += 1
    sorted_counted_list.extend(left[i:])
    sorted_counted_list.extend(right[j:])
    return sorted_counted_list

