def flattenList(lst):
    def flatten(lst, visited):
        lst_id = id(lst)
        if lst_id in visited:
            return []
        visited.add(lst_id)
        stack = lst[::-1]
        result = []
        while stack:
            element = stack.pop()
            if isinstance(element, list):
                element_id = id(element)
                if element_id in visited:
                    continue
                visited.add(element_id)
                stack.extend(element[::-1])
            else:
                result.append(element)
        visited.remove(lst_id)
        return result
    visited_sets = set()
    return flatten(lst, visited_sets)

