from concurrent.futures import ThreadPoolExecutor, as_completed

def multiply_even_numbers(start, end):
    for i in range(start, end, 2):
        yield i * 2

def process_large_dataset(n, num_threads=4):
    threads = num_threads if n >= num_threads else 1
    chunk_size = (n + threads - 1) // threads
    results = [None] * threads
    with ThreadPoolExecutor(max_workers=threads) as executor:
        futures = {}
        for idx in range(threads):
            chunk_start = idx * chunk_size
            # Make sure the start is even
            if chunk_start % 2 != 0:
                chunk_start += 1
            chunk_end = min((idx + 1) * chunk_size, n)
            if chunk_start >= chunk_end:
                results[idx] = []
                continue
            futures[executor.submit(lambda s=chunk_start,e=chunk_end: list(multiply_even_numbers(s,e)), )] = idx
        for future in as_completed(futures):
            idx = futures[future]
            results[idx] = future.result()
    # Output in order of input chunks to preserve order
    for chunk in results:
        for val in chunk:
            print(val)

def main():
    n = int(input())
    process_large_dataset(n)

if __name__ == "__main__":
    main()

