def can_partition(nums):
    total_sum = sum(nums)

    # If the total sum is odd, it cannot be partitioned into two equal subsets
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    n = len(nums)

    # Create a boolean DP table to store the possibility of getting a particular sum
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]

    # Base case: If sum is 0, it is always possible to get sum 0
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the DP table in bottom-up manner
    for i in range(1, n + 1):
        for j in range(1, target_sum + 1):
            # If the current element is greater than the current sum, exclude it
            if nums[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                # Either include the current element or exclude it
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]

    # If it is possible to get the target sum, it means the list can be partitioned
    return dp[n][target_sum]

def encrypt(text, shift):
    result = ""
    for i in range(len(text)):
        char = text[i]
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                result += chr((ord(char) + shift_amount - 97) % 26 + 97)
            else:
                result += chr((ord(char) + shift_amount - 65) % 26 + 65)
        else:
            result += char
    return result

def main():
    text = input()
    shift = int(input())
    print(encrypt(text, shift))

