from collections import deque
import sys

def count_stepping_numbers(n: int, m: int) -> int:
    if n > m:
        return 0

    q = deque()
    visited = set()
    cnt = 0

    # single-digit numbers are stepping numbers by definition
    for d in range(10):
        if d <= m:
            q.append(d)
            visited.add(d)
            if d >= n:
                cnt += 1

    while q:
        cur = q.popleft()
        last = cur % 10
        for delta in (-1, 1):
            nxt_digit = last + delta
            if 0 <= nxt_digit <= 9:
                nxt = cur * 10 + nxt_digit
                if nxt <= m and nxt not in visited:
                    visited.add(nxt)
                    q.append(nxt)
                    if nxt >= n:
                        cnt += 1
    return cnt

