    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    keys = list(map(int, data[1:1 + n]))

    root = None
    for k in keys:
        root = insert_avl(root, k)

    result = []
    inorder(root, result)
    print(' '.join(result))

