import sys
sys.setrecursionlimit(1 << 25)

def main():
    n, l, r = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(n):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    # Collect sizes of all cycles (connected components)
    visited = [False] * (n + 1)
    cycle_sizes = []
    for i in range(1, n + 1):
        if not visited[i]:
            start = i
            current = start
            prev = None
            length = 0
            while True:
                if visited[current]:
                    if current == start and length > 0:
                        break
                    else:
                        length = 0
                        break
                visited[current] = True
                length += 1
                next_node = None
                for neighbor in adj[current]:
                    if neighbor != prev:
                        next_node = neighbor
                        break
                if next_node is None:
                    break
                prev = current
                current = next_node
            if length > 0:
                cycle_sizes.append(length)

    if not cycle_sizes:
        print("Bob")
        return

    max_size = max(cycle_sizes)

    # Grundy numbers for paths
    g_path = [0] * (max_size + 1)
    for s in range(1, max_size + 1):
        reachable = set()
        for k in range(l, r + 1):
            if k > s:
                continue
            t = s - k
            for a in range(t + 1):
                b = t - a
                reachable.add(g_path[a] ^ g_path[b])
        g = 0
        while g in reachable:
            g += 1
        g_path[s] = g

    # Grundy numbers for cycles
    g_cycle = [0] * (max_size + 1)
    for m in range(max_size + 1):
        reachable = set()
        for k in range(l, r + 1):
            if k > m:
                continue
            reachable.add(g_path[m - k])
        g = 0
        while g in reachable:
            g += 1
        g_cycle[m] = g

    xor_sum = 0
    for m in cycle_sizes:
        xor_sum ^= g_cycle[m]

    print("Alice" if xor_sum != 0 else "Bob")

if __name__ == "__main__":
    main()

def apply_operator(operators, values):
    operator = operators.pop()
    right = values.pop()
    left = values.pop()
    if operator == '+':
        values.append(left + right)
    elif operator == '-':
        values.append(left - right)
    elif operator == '*':
        values.append(left * right)
    elif operator == '/':
        values.append(left / right)

def precedence(op):
    if op in ('+', '-'):
        return 1
    if op in ('*', '/'):
        return 2
    return 0

def same_or_greater_precedence(op1, op2):
    return precedence(op1) >= precedence(op2)

def is_operator(c):
    return c in "+-*/"

def is_number(c):
    return c.isdigit()

