    operators = []
    values = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
        elif expression[i] == '(':  # left parenthesis
            operators.append(expression[i])
            i += 1
        elif is_number(expression[i]):
            val = 0
            while i < len(expression) and is_number(expression[i]):
                val = val * 10 + int(expression[i])
                i += 1
            values.append(val)
        elif expression[i] == '.':
            # Handle floats: read as 'val . digits'
            prev_val = values.pop()
            i += 1
            decimal_place = 0.1
            float_val = prev_val
            while i < len(expression) and is_number(expression[i]):
                float_val += int(expression[i]) * decimal_place
                decimal_place /= 10
                i += 1
            values.append(float_val)
        elif is_operator(expression[i]):
            while (operators and operators[-1] != '(' and same_or_greater_precedence(operators[-1], expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])
            i += 1
        elif expression[i] == ')':
            while operators and operators[-1] != '(':  # pop until matching (
                apply_operator(operators, values)
            operators.pop()
            i += 1
    while operators:
        apply_operator(operators, values)
    res = values[0]
    if isinstance(res, float):
