        dp = {0: 0}
        for coin, num in zip(denoms, avail):
            new_dp = {}
            for value, used in dp.items():
                for k in range(num + 1):
                    nv = value + k * coin
                    nc = used + k
                    if nv not in new_dp or nc < new_dp[nv]:
                        new_dp[nv] = nc
            dp = new_dp

        best = float('inf')
        for paid, pc in dp.items():
            if paid < P:
                continue
            change = paid - P
            cc = minimal_change(change)
            best = min(best, pc + cc)
