class Node:
    def __init__(self, value):
        self.info = value
        self.next = None
        self.prev = None

class Queue:    
    def __init__(self):
        self.head = None
        self.tail = None

    def is_empty(self):
        return not bool(self.head and self.tail)

    def enqueue(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            self.tail = self.head
        else:
            self.tail.next = new_node
            new_node.prev = self.tail
            self.tail = new_node

    def dequeue(self):
        if self.is_empty():
            print("Queue is empty")
            return None
        else:
            removed_node = self.head.info
            self.head = self.head.next
            if self.head:
                self.head.prev = None
            else:
                self.tail = None
            return removed_node

    def reverse(self):
        if self.is_empty():
            print("Queue is empty")
            return
        current_node = self.head
        temp_node = None
        while current_node:
            temp_node = current_node.prev
            current_node.prev = current_node.next
            current_node.next = temp_node
            current_node = current_node.prev
        if temp_node:
            self.tail = self.head
            self.head = temp_node.prev

    def sort(self): 
        if self.is_empty():
            print("Queue is empty")
            return
        current_node = self.head
        while current_node:
            next_node = current_node.next
            while next_node:
                if current_node.info > next_node.info:
                    current_node.info, next_node.info = next_node.info, current_node.info
                next_node = next_node.next
            current_node = current_node.next
