def remove_none_recursively(data):
    if isinstance(data, dict):
        return clean_dict(data)
    elif isinstance(data, list):
        return clean_list(data)
    else:
        return data

def clean_dict(d):
    if not d:
        return {}
    key = next(iter(d))
    value = d[key]
    cleaned_value = remove_none_recursively(value)
    rest = {k: v for k, v in d.items() if k != key}
    if cleaned_value is None:
        return clean_dict(rest)
    result = clean_dict(rest)
    result = {key: cleaned_value, **result}
    return result

def clean_list(lst):
    if not lst:
        return []
    head = lst[0]
    tail = lst[1:]
    cleaned_head = remove_none_recursively(head)
    if cleaned_head is None:
        return clean_list(tail)
    return [cleaned_head] + clean_list(tail)

def main():
