                start = temp_start
                end = i
            elif (i - temp_start) == (end - start):
                subarray1 = arr[start:end+1]
                subarray2 = arr[temp_start:i+1]
                if convert_to_binary(subarray2) < convert_to_binary(subarray1):
                    start = temp_start
                    end = i
        if current_sum < 0:
            current_sum = 0
