class LinkedList:
    def __init__(self):
        self.head = None

    def insert_at_head(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def delete_by_value(self, value):
        current = self.head
        previous = None
        while current is not None:
            if current.data == value:
                if previous is not None:
                    previous.next = current.next
                else:
                    self.head = current.next
                return
            previous = current
            current = current.next

    def display(self):
        current = self.head
        values = []
        while current is not None:
            values.append(str(current.data))
            current = current.next
        print(' -> '.join(values) + ' -> None')

    def reverse(self):
        previous = None
        current = self.head
        while current is not None:
            next_node = current.next
            current.next = previous
            previous = current
            current = next_node
        self.head = previous

    def rotate_to_right(self, k):
        if not self.head or k == 0:
            return
        # Compute the length and get the tail
        current = self.head
        length = 1
        while current.next:
            current = current.next
            length += 1
        # Make it circular
        current.next = self.head
        k = k % length
        if k == 0:
            current.next = None
            return
        # Find new tail (length - k)th node
        new_tail = self.head
        for _ in range(length - k - 1):
            new_tail = new_tail.next
        self.head = new_tail.next
        new_tail.next = None

