            self.data_dict[key] = {"Occupation": occupation, "Birthday": birthday, "Hobby": hobby}

    def remove_entry(self, key):
        if key in self.data_dict:
            del self.data_dict[key]

    def modify_entry(self, key, occupation=None, birthday=None, hobby=None):
        if key in self.data_dict:
            if occupation:
                if self.validate_occupation(occupation):
