    let consonants: Vec<char> = s_lower
        .chars()
        .filter(|c| allowed_consonants.contains(*c))
        .collect();

    let total = consonants.len();

    let unique: HashSet<_> = consonants.into_iter().collect();
    let unique_count = unique.len();

