def build_tree(nodes_desc):
    if not nodes_desc:
        return None
    nodes = [None] + [TreeNode() for _ in nodes_desc]  # nodes[1]..nodes[n]
    for idx, (v, l, r) in enumerate(nodes_desc, 1):
        if l != 0:
            nodes[idx].left = nodes[l]
        if r != 0:
            nodes[idx].right = nodes[r]
    return nodes[1]

def dfs(node):
    if not node:
        return (0, 0, True)  # height, max_imbalance, is_balanced
    lh, lim, lb = dfs(node.left)
    rh, rim, rb = dfs(node.right)
    cur_diff = abs(lh - rh)
    is_bal = lb and rb and cur_diff <= 1
    max_diff = max(lim, rim)
    if not is_bal:
        max_diff = max(max_diff, cur_diff)
    return (1 + max(lh, rh), max_diff, is_bal)

