            self.balance += amount
            print(f"Deposited ${amount:.2f}. New balance: ${self.balance:.2f}")
        else:
            print("Deposit amount must be positive.")
    def withdraw(self, amount, day):
        fee = 0
        if day > 10:
            fee = 2
            print("A $2 fee has been applied because the withdrawal was made after the 10th day of the month.")
        total = amount + fee
        if amount > 0:
            if self.balance >= total:
                self.balance -= total
                print(f"Withdrew ${total:.2f}. New balance: ${self.balance:.2f}")
            else:
                print("Insufficient funds.")
        else:
            print("Withdrawal amount must be positive.")
    def get_balance(self):
