import math

class SurfaceArea:
    @staticmethod
    def cube(side_length: float) -> float:
        return 6 * (side_length ** 2)

    @staticmethod
    def sphere(radius: float) -> float:
        return 4 * math.pi * (radius ** 2)

    @staticmethod
    def cylinder(radius: float, height: float) -> float:
        return 2 * math.pi * radius * (radius + height)

    @staticmethod
    def cone(radius: float, height: float) -> float:
        slant_height = (radius**2 + height**2) ** 0.5
        return math.pi * radius * (radius + slant_height)

    @staticmethod
    def rectangular_prism(length: float, width: float, height: float) -> float:
        return 2 * (length*width + length*height + width*height)

    @staticmethod
    def square_pyramid(base_edge: float, height: float) -> float:
        radius_effective = base_edge / 2  # Half the base edge for slant height computation
        slant_height = (radius_effective**2 + height**2) ** 0.5
        base_area = base_edge ** 2
        lateral_area = 4 * (0.5 * base_edge * slant_height)
        return base_area + lateral_area

