def spiral_bottom_up_diagonal_traversal(root):
    def diagonal_helper(node, row, col, result):
        if node is None:
            return
        diag_index = row + col
        if diag_index not in result:
            result[diag_index] = []
        result[diag_index].append((node.val, col))
        diagonal_helper(node.left, row + 1, col, result)
        diagonal_helper(node.right, row, col + 1, result)
    if root is None:
        return []
    diagonals = {}
    diagonal_helper(root, 0, 0, diagonals)
    traversal = []
    for diag_sum in range(len(diagonals)-1, -1, -1):
        nodes_in_diag = sorted(diagonals[diag_sum], key=lambda x: x[1])
        traversal.extend([node[0] for node in nodes_in_diag])
    return traversal

