def permute_unique(s):
    def backtrack(path, counter, results):
        if len(path) == len(s):
            results.append(''.join(path))
            return
        for char in counter:
            if counter[char] > 0:
                path.append(char)
                counter[char] -= 1
                backtrack(path, counter, results)
                counter[char] += 1
                path.pop()
    from collections import Counter
    counter = Counter(s)
    results = []
    backtrack([], counter, results)
    return results

def main():
