function smallest_variation_in_subgroup($arr, $limit, $subset){
    // Mapping array elements to counts of their occurrence
    $counts = [];
    foreach ($arr as $a) {
        if (!isset($counts[$a])) {
            $counts[$a] = 1;
        } else {
            $counts[$a]++;
        }
    }

    // Numbers in the subset with occurrence less than half of the array's length
    $to_subtract = [];
    foreach ($counts as $k => $v) {
        if (in_array($k, $subset) && $v < count($arr) / 2) {
            $to_subtract[] = $k;
        }
    }

    // Sorting them by occurrence in ascending order
    usort($to_subtract, function ($a, $b) use ($counts) {
        return $counts[$a] <=> $counts[$b];
    });

    // Subtracting them until limit or subset is depleted
    $idx = 0;
    while ($idx < count($to_subtract) && $limit > 0) {
        $limit--;
        $arr[array_search($to_subtract[$idx], $arr)] = $to_subtract[count($to_subtract) - 1];
        $counts[$to_subtract[$idx]]--;
        $counts[$to_subtract[count($to_subtract) - 1]]++;
        if ($counts[$to_subtract[$idx]] < count($arr) / 2) {
            $idx++;
        }
    }

    // Cannot make array palindromic if subset is depleted before limit
    if ($idx < count($to_subtract)) {
        return -1;
    }

    // Count compared to the most occurrence number in the subset
    $max_subset_elm = array_reduce(array_keys($counts), function ($max, $item) use ($counts, $subset) {
        return (in_array($item, $subset) && $counts[$item] > $counts[$max]) ? $item : $max;
    }, array_keys($counts)[0]);

    return array_sum(array_map(function ($k, $v) use ($max_subset_elm) {
        return $k != $max_subset_elm ? $v : 0;
    }, array_keys($counts), $counts));
}
