def find_most_consistent_player(games):
    player_stats = {}

    # Calculate shooting percentages for each player and game
    for game in games:
        name = game['name']
        made = game['made']
        attempted = game['attempted']

        if attempted > 0:
            shooting_percentage = made / attempted
        else:
            shooting_percentage = 0

        if name in player_stats:
            player_stats[name]['percentages'].append(shooting_percentage)
        else:
            player_stats[name] = {'percentages': [shooting_percentage]}

    # Calculate variance for each player
    for player, stats in player_stats.items():
        percentages = stats['percentages']
        mean = sum(percentages) / len(percentages)
        variances = [(percentage - mean) ** 2 for percentage in percentages]
        variance = sum(variances) / len(variances)
        stats['variance'] = variance

    # Find player with lowest variance
    most_consistent_player = min(player_stats.items(), key=lambda x: x[1]['variance'])[0]

    return most_consistent_player
