def add_without_plus(a, b):
    while b != 0:
        carry = a & b
        a = a ^ b
        b = carry << 1
    return a

def multiply_without_star(a, b):
    result = 0
    while b:
        if b & 1:
            result = add_without_plus(result, a)
        a = a << 1
        b = b >> 1
    return result

def compute_factorial(n):
    if n == 0 or n == 1:
        return 1
    return multiply_without_star(n, compute_factorial(n - 1))

