def find_longest_subarray(severity_scores, threshold):
    max_length = 0
    start_index = 0
    current_sum = 0
    current_start = 0

    for i in range(len(severity_scores)):
        current_sum += severity_scores[i]

        while current_sum / (i - current_start + 1) >= threshold:
            length = i - current_start + 1
            if length > max_length:
