class TreeNode:
    def __init__(self, val: int = 0, left: 'TreeNode' = None, right: 'TreeNode' = None):
        self.val = val          # 0 or 1
        self.left = left        # left child
        self.right = right      # right child


def sumRootToLeaf(root: TreeNode) -> int:
    """
    Given the root of a binary tree where each node holds 0 or 1,
    return the sum of the binary numbers represented by every
    root-to-leaf path (most-significant bit at the root).

    The function assumes `root` is not None.
    """

    def dfs(node: TreeNode, current: int) -> int:
        if node is None:
            return 0

        # Shift accumulated value left and add current node's bit
        current = (current << 1) | node.val

        # If this is a leaf, current holds the complete binary number
        if node.left is None and node.right is None:
            return current

        # Recurse on children and sum their contributions
        return dfs(node.left, current) + dfs(node.right, current)

    return dfs(root, 0)

