class MinStack:
    def __init__(self):
        self.stack = []

    def push(self, value):
        if not self.stack:
            # (value, min)
            self.stack.append((value, value))
        else:
            current_min = self.stack[-1][1]
            self.stack.append((value, min(value, current_min)))

    def pop(self):
        if not self.stack:
            return 'error'
        value, _ = self.stack.pop()
        return value

    def peek(self):
        if not self.stack:
            return 'error'
        value, _ = self.stack[-1]
        return value

    def get_min(self):
        if not self.stack:
            return 'error'
        _, min_value = self.stack[-1]
        return min_value

