def build_tree(n, nodes_info):
    nodes = {}
    for val, l, r in nodes_info:
        if val not in nodes:
            nodes[val] = TreeNode(val)
        if l != -1:
            if l not in nodes:
                nodes[l] = TreeNode(l)
            nodes[val].left = nodes[l]
        if r != -1:
            if r not in nodes:
                nodes[r] = TreeNode(r)
            nodes[val].right = nodes[r]
    # Assume the first given node is root
    return nodes[nodes_info[0][0]]

def exists(node, target):
    if not node:
        return False
    if node.val == target:
        return True
    elif target < node.val:
        return exists(node.left, target)
    else:
        return exists(node.right, target)

def find_lca(root, p, q):
    # Check presence
    if not exists(root, p) or not exists(root, q):
        return None
    node = root
    while node:
        if p < node.val and q < node.val:
            node = node.left
        elif p > node.val and q > node.val:
            node = node.right
        else:
            return node
    return None

