The solution to your problem is written in C++. The code below contains two functions `encode_cyclic` and `decode_cyclic`. The `encode_cyclic` function takes a string, splits it into parts of three characters each and shifts the characters of each part to the right in a cyclic manner. The `decode_cyclic` function then reverses the operations of the `encode_cyclic` function by shifting the characters to the left in a similar cyclic manner.

```c++
#include <string>

using namespace std;

string encode_cyclic(string text){
    for(int i=0; i < text.length(); i += 3){
        if(i+2 < text.length()){
            char temp = text[i+2];
            text[i+2] = text[i+1];
            text[i+1] = text[i];
            text[i] = temp;
        }
    }
    return text;
}

string decode_cyclic(string text){
    for(int i=0; i < text.length(); i += 3){
        if(i+2 < text.length()){
            char temp = text[i];
            text[i] = text[i+1];
            text[i+1] = text[i+2];
            text[i+2] = temp;
        }
    }
    return text;
}
```

