    results = [reverse_special_chars(word)[::-1] for word in words[::-1]]
    return ' '.join(results)

def reverse_special_chars(input_text):
    letters = list(input_text)
    start, end = 0, len(letters) - 1
    while start < end:
        while not letters[start].isalpha() and start < end:
            start += 1
        while not letters[end].isalpha() and start < end:
            end -= 1
        letters[start], letters[end] = letters[end], letters[start]
        start += 1
        end -= 1
    return ''.join(letters)

