from functools import reduce

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return n == 2 or n == 3
    # Generate candidate divisors (5,7,11,13,... up to √n)
    sqrt_n = int(n ** 0.5)
    inc = lambda acc: acc + [acc[-1]+2] if (len(acc) % 2 == 1) else acc + [acc[-1]+4]
    seed = [5]
    # Dynamically build the list using reduce and lambdas
    build_divisors = lambda s, limit: reduce(lambda acc, _: inc(acc), [None]*((limit-5)//2+1), s)
    candidates = build_divisors(seed, sqrt_n) if sqrt_n >= 5 else []
    # Now check divisibility
    is_not_divisor = lambda acc, d: acc and n % d != 0
    return reduce(is_not_divisor, candidates, True)

