import ast
import sys

def flatten_dict(data, parent_key='', sep='_', visited=None):
    if visited is None:
        visited = set()
    obj_id = id(data)
    if obj_id in visited:
        return {}
    visited.add(obj_id)
    items = []
    if isinstance(data, dict):
        for k, v in data.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep, visited).items())
            elif isinstance(v, (list, tuple)):
                for i, item in enumerate(v):
                    items.extend(flatten_dict({str(i): item}, f"{new_key}{sep}{i}", sep, visited).items())
            else:
                items.append((new_key, str(v)))
    else:
        items.append((parent_key, str(data)))
    visited.remove(obj_id)
    return dict(items)

