class BIT:
    def __init__(self, size):
        self.N = size
        self.tree = [0] * (self.N + 2)  # 1-based indexing

    def update(self, idx, delta):
        while idx <= self.N:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res


def find_predecessor(bit, val):
    """Greatest inserted key < val, or None."""
    if val <= 1:
        return None
    lo, hi, ans = 1, val - 1, None
    while lo <= hi:
        mid = (lo + hi) // 2
        if bit.query(mid) - bit.query(mid - 1) > 0:  # mid present
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans


def find_successor(bit, val, N):
    """Smallest inserted key > val, or None."""
    if val >= N:
        return None
    lo, hi, ans = val + 1, N, None
    while lo <= hi:
        mid = (lo + hi) // 2
        if bit.query(mid) - bit.query(mid - 1) > 0:  # mid present
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans


def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    seq = list(map(int, data[1:1 + N]))

    bit = BIT(N)
    depth = {}
    left_full = {}
    right_full = {}
    cumulative = 0

    for x in seq:
        # first insertion becomes root
        if not depth:
            depth[x] = 0
            bit.update(x, 1)
            print(cumulative)
            continue

        pred = find_predecessor(bit, x)
        succ = find_successor(bit, x, N)

        parent = None
        # try to attach as right child of predecessor if possible
        if pred is not None and not right_full.get(pred, False):
            parent = pred
            right_full[pred] = True
        else:
            # otherwise attach as left child of successor
            if succ is not None and not left_full.get(succ, False):
                parent = succ
                left_full[succ] = True
        if parent is None:
            parent_depth = 0  # should never happen
        else:
            parent_depth = depth[parent]
        depth[x] = parent_depth + 1
        cumulative += depth[x]
        bit.update(x, 1)
        print(cumulative)


