def find_left(arr, target):
    low, high = 0, len(arr) - 1
    left = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            left = mid
            high = mid - 1
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return left

def find_right(arr, target):
    low, high = 0, len(arr) - 1
    right = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            right = mid
            low = mid + 1
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return right


