Please note: This code snippet does not accurately compute the index for nested objects or manage the errors as of now.

The solution would be to modify the provided function to update the index for each non-object items, ignoring the object elements, and to include error handling. Here is the corrected version of the provided function:

```javascript
function sumMultiplication(obj, nonObjectItemIndex = 0) {
  let sum = 0;
  let nextNonObjectItemIndex = nonObjectItemIndex;
  try {
    if (!obj || typeof obj !== 'object') {
      return 0;
    }
    for (let key in obj) {
      if (obj.hasOwnProperty(key)) {
        let value = obj[key];
        if (Array.isArray(value) || (typeof value === 'object' && value !== null)) {
          sum += sumMultiplication(value, nextNonObjectItemIndex);
        } else if (typeof value === "number") {
          sum += value * nonObjectItemIndex;
          nextNonObjectItemIndex += 1;
        } else {
          throw new Error("Invalid value type must be number");
        }
      }
    }
  } catch (err) {
    console.error(err.message);
    return 0;
  }
  return sum;
}
```

