            parts = content.split(';')
            if len(parts) != 3:
                print("Invalid add command format.")
                continue
            title, author, isbn = [s.strip() for s in parts]
            bookstore.add_book(title, author, isbn)
        elif command.startswith('remove '):
            isbn = command[7:].strip()
            bookstore.remove_book(isbn)
        elif command == 'display':
            bookstore.display_books()
        else:
