def zeroMatrix(matrix):
    """
    Given a 2-D list of integers, set the entire row and column to 0
    for every element that is 0 in the original matrix.

    The function returns the modified matrix (changes are done in place).

    Example
    -------
    >>> zeroMatrix([[1, 2, 3], [4, 0, 6], [7, 8, 9]])
    [[1, 0, 3], [0, 0, 0], [7, 0, 9]]
    """
    if not matrix or not matrix[0]:
        return matrix  # handle empty matrix

    m, n = len(matrix), len(matrix[0])

    # First pass: record which rows and columns contain a zero.
    zero_rows = set()
    zero_cols = set()
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 0:
                zero_rows.add(i)
                zero_cols.add(j)

    # Second pass: zero out recorded rows.
    for i in zero_rows:
        for j in range(n):
            matrix[i][j] = 0

    # Third pass: zero out recorded columns.
    for j in zero_cols:
        for i in range(m):
            matrix[i][j] = 0

    return matrix

