```python
def average_score(data, year=None):
    result = {}
    for item in data:
        # check data format
        if type(item) is not tuple or len(item) != 3 or type(item[0]) is not str or type(item[1]) is not int or type(item[2]) is not list:
            return "Error: Invalid data format."
        name, yr, scores = item
        # check if scores are valid
        if not all(isinstance(score, (int, float)) for score in scores):
            return "Error: Scores must be numbers."
        # calculate average score
        average = sum(scores) / len(scores)
        if year is None or yr == year:
            if name in result and type(result[name]) is dict:
                result[name][yr] = average
            elif name in result and type(result[name]) is not dict:
                result[name] = {yr: result[name]}
            else:
                result[name] = average
    return result
```

