def power(base, exponent, memo=None):
    if memo is None:
        memo = {}
    if exponent == 0:
        return 1
    if exponent < 0:
        return 1 / power(base, -exponent, memo)
    if exponent in memo:
        return memo[exponent]
    half = power(base, exponent // 2, memo)
    if exponent % 2 == 0:
        result = half * half
    else:
        result = base * half * half
    memo[exponent] = result
    return result

