from itertools import product

def generate_good_integers(limit: int):
    digits = ('2', '8')
    max_len = len(str(limit))
    good = []
    for length in range(1, max_len + 1):
        for tup in product(digits, repeat=length):
            val = int(''.join(tup))
            if val <= limit:
                good.append(val)
    # remove duplicates (there are none, but for safety) and sort
    return sorted(set(good))

