    if not n_line:
        return
    n = int(n_line)

    if n == 1:
        print(-1)
        return

    good_numbers = generate_good_integers(n)
    # memoization for divisors that have already been computed
    memo = {1: 0}

    def dfs(x: int) -> int:
        if x in memo:
            return memo[x]
        best = -1
        for g in good_numbers:
            if g > x:
                break
            if x % g == 0:
                sub = dfs(x // g)
                if sub != -1:
                    best = max(best, 1 + sub)
        memo[x] = best
        return best

