def find_peak(nums):
    def binary_search(nums, low, high):
        mid = low + (high - low) // 2
        if ((mid == 0 or nums[mid - 1] <= nums[mid]) and
            (mid == len(nums) - 1 or nums[mid + 1] <= nums[mid])):
            return mid
        elif (mid > 0 and nums[mid - 1] > nums[mid]):
            return binary_search(nums, low, mid - 1)
        else:
            return binary_search(nums, mid + 1, high)
    if not nums:
        return None
    peak_index = binary_search(nums, 0, len(nums) - 1)
    return nums[peak_index]

