def sieve_of_eratosthenes(max_num):
    if max_num < 2:
        return []
    is_prime = [True] * (max_num + 1)
    is_prime[0] = False
    is_prime[1] = False
    p = 2
    while p * p <= max_num:
        if is_prime[p]:
            for i in range(p * p, max_num + 1, p):
                is_prime[i] = False
        p += 1
    primes = [x for x in range(2, max_num + 1) if is_prime[x]]
