def has_two_cube_sums(n):
    pairs = []
    max_a = int(round(n ** (1/3))) + 2  # small safety margin for float errors
    for a in range(1, max_a + 1):
        a_cubed = a ** 3
        remaining = n - a_cubed
        if remaining < a_cubed:
            continue  # ensure a <= b so we don't count both (a,b) and (b,a)

        # binary search to see whether remaining is a perfect cube
        low, high = 1, int(round(remaining ** (1/3))) + 2
        b = -1
        while low <= high:
            mid = (low + high) // 2
            mid_cubed = mid ** 3
            if mid_cubed == remaining:
                b = mid
                break
            elif mid_cubed < remaining:
                low = mid + 1
            else:
                high = mid - 1
        if b != -1 and b >= a:
            pairs.append((a, b))

    # look for two pairs with all four numbers different
    for i in range(len(pairs)):
        for j in range(i + 1, len(pairs)):
            a1, b1 = pairs[i]
            a2, b2 = pairs[j]
            if a1 != a2 and a1 != b2 and b1 != a2 and b1 != b2:
                return True
    return False

