import json
import sys

def traverse_update(data):
    if isinstance(data, dict):
        keys_to_rename = []
        for key, value in list(data.items()):
            # Check for appDetails at this level
            if key == 'appDetails' and isinstance(value, dict):
                # Check for nested appDetails containing version
                for sub_key, sub_value in value.items():
                    if sub_key == 'appDetails' and isinstance(sub_value, dict) and 'version' in sub_value:
                        sub_value['version'] = '2.0.0'
            if key == 'description':
                keys_to_rename.append(key)
            traverse_update(value)
        for old_key in keys_to_rename:
            data['summary'] = data.pop(old_key)
    elif isinstance(data, list):
        for item in data:
            traverse_update(item)

