import sys

def max_group_size(arr, k):
    # Count how many numbers give each remainder modulo k
    cnt = [0] * k
    for num in arr:
        cnt[num % k] += 1

    res = 0

    # At most one element with remainder 0 can be taken
    if cnt[0] > 0:
        res += 1

    # Handle the rest of the remainders in pairs (r, k-r)
    for r in range(1, k // 2 + 1):
        s = k - r
        if r == s:  # This only happens when k is even and r == k/2
            if cnt[r] > 0:
                res += 1
        else:
            res += max(cnt[r], cnt[s])

    return res


