def manual_divide(dividend, divisor):
    negative_result = (dividend < 0) != (divisor < 0)
    dividend, divisor = abs(dividend), abs(divisor)
    quotient = 0
    # Integer part
    while dividend >= divisor:
        dividend -= divisor
        quotient += 1
    # Fractional part
    remainder = dividend
    fractional_part_length = 5
    fractional_part = 0
    temp_divisor = divisor
    for _ in range(fractional_part_length):
        remainder *= 10
        x = 0
        while remainder >= temp_divisor:
            remainder -= temp_divisor
            x += 1
        fractional_part = fractional_part * 10 + x
    result = quotient + fractional_part / (10 ** fractional_part_length)
    return -result if negative_result else result

