import heapq

def main():
    import sys
    input = sys.stdin.readline

    n, m = map(int, input().split())
    graph = [[] for _ in range(n)]
    has_negative_weight = False
    for _ in range(m):
        u, v, w = map(int, input().split())
        if w < 0:
            has_negative_weight = True
        graph[u].append((v, w))
    s = int(input())
    if has_negative_weight:
        print("Error: Graph contains negative edge weights, Dijkstra's algorithm does not support negative weights.")
        return

    distances = [float('inf')] * n
    distances[s] = 0
    hq = [(0, s)]
    while hq:
        d, u = heapq.heappop(hq)
        if d > distances[u]:
            continue
        for v, w in graph[u]:
            if distances[v] > distances[u] + w:
                distances[v] = distances[u] + w
                heapq.heappush(hq, (distances[v], v))
    out = []
    for dist in distances:
        if dist == float('inf'):
            out.append('INF')
        else:
            out.append(str(dist))
    print(' '.join(out))

