func tetra(_ n: Int) -> Any {
    if n < 0 {
        return "Input must be a non-negative integer."
    }

    // Base cases
    var tetraList = [1, 4, 2, 6]

    // Compute tetra(i) for i from 4 to n
    for i in 4...n {
        if i % 2 == 0 {
            tetraList.append(1 + i/2)
        } else if i % 3 == 0 {
            tetraList.append(tetraList[i-1] + tetraList[i-2])
        } else {
            tetraList.append(tetraList[i-1] + tetraList[i-2] + tetraList[i-3])
