class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def build_tree_from_level_list(data):
    # Convert data to node values
    if not data or data[0] == 'None':
        return None
    nodes = []
    for val in data:
        if val == 'None':
            nodes.append(None)
        else:
            nodes.append(TreeNode(int(val)))
    kids = nodes[::-1]
    root = kids.pop()
    queue = [root]
    i = 1
    while kids:
        node = queue.pop(0)
        if node:
            if kids:
                node.left = kids.pop()
                queue.append(node.left)
            if kids:
                node.right = kids.pop()
                queue.append(node.right)
    return root

def inorder_traversal(root):
    stack = []
    current = root
    result = []
    while stack or current:
        while current:
            stack.append(current)
            current = current.left
        current = stack.pop()
        result.append(current.value)
        current = current.right
    return result

def main():
    line = input().strip()
    if line == '':
        print()
        return
    data = line.split()
    root = build_tree_from_level_list(data)
    res = inorder_traversal(root)
    print(' '.join(str(x) for x in res))

