def binary_to_decimal_recursive(binary_str, current_decimal=0, depth=0):
    if depth == 0:
        # Validate input only at top level
        if not all(char in '01' for char in binary_str):
            return None
    if not binary_str:
        return current_decimal
    chunk = binary_str[:10]
    chunk_decimal = 0
    for char in chunk:
        chunk_decimal = (chunk_decimal << 1) | int(char)
    current_decimal = (current_decimal << len(chunk)) | chunk_decimal
    return binary_to_decimal_recursive(binary_str[10:], current_decimal, depth+1)

