        return key in d

    def swap(i, j):
        dict_list[i], dict_list[j] = dict_list[j], dict_list[i]

    length = len(dict_list)
    # Bring all dicts with the key to the front
    for i in range(length):
        for j in range(0, length - i - 1):
            if not has_key(dict_list[j], key) and has_key(dict_list[j+1], key):
                swap(j, j+1)
    # Sort only dicts with the key
    k = 0
    while k < len(dict_list) and has_key(dict_list[k], key):
        k += 1
    for i in range(k):
        for j in range(0, k - i - 1):
            if dict_list[j][key] > dict_list[j+1][key]:
                swap(j, j+1)
    print(json.dumps(dict_list))

