async function getMQTTMessage(event) {
    let promise = new Promise((resolve, reject) => {
        const params = {
            topic: event.topic
        };
        IotData.getThingShadow(params, (error, data) => {
            if (error) {
                console.error(`Failed to fetch MQTT message: ${error}`);
                reject(error);
            } else {
                let mqttMessage = JSON.parse(data.payload);
                resolve(mqttMessage);
            }
        });
    });
    return promise;
}

async function handleMQTTMessage(message) {
    try {
        await influx.writePoints([
            {
                measurement: 'mqtt_data',
                tags: { source: message.source },
                fields: { value: message.data },
            }
        ]);
    } catch (error) {
        console.error(`Failed to write data to InfluxDB: ${error}`);
        throw error;
    }
}
```

