```
#include "msgDefinition.pb.h"

void Sender::initialize()
{
    DataMsg *msg = new DataMsg("DataMsg");
    send(msg, "out");
}

```
Then you will be able to identify the message by its class. In your receiver:

```
#include "msgDefinition.pb.h"

void Receiver::handleMessage(cMessage *msg)
{
    if (dynamic_cast<DataMsg *>(msg) != nullptr) {
        DataMsg *dataMsg = check_and_cast<DataMsg *>(msg);  
