def parse_json(json_string):
    def extract_key_value(s, key):
        idx = s.find('"' + key + '"')
        if idx == -1:
            return None
        idx = s.find(':', idx)
        if idx == -1:
            return None
        idx += 1
        while idx < len(s) and s[idx] in [' ', '\n']:
            idx += 1
        # Now at value, could be string or object or array
        if s[idx] == '"':
            start = idx+1
            end = start
            while end < len(s) and s[end] != '"':
                if s[end] == '\\':
                    end += 2
                else:
                    end += 1
            return s[start:end]
        # Otherwise return None for this simple parser
        return None

    def extract_cast_names(s):
        # find '"cast"'
        cast_pos = s.find('"cast"')
        if cast_pos == -1:
            return []
        bracket = s.find('[', cast_pos)
        if bracket == -1:
            return []
        end_bracket = bracket
        level = 1
        while level > 0 and end_bracket+1 < len(s):
            end_bracket += 1
            if s[end_bracket] == '[':
                level += 1
            elif s[end_bracket] == ']':
                level -= 1
        arr = s[bracket+1:end_bracket]
        # Now arr is the content between [ and ]
        # Each object is { "name": "..." }
        names = []
        i = 0
        while i < len(arr):
            pos = arr.find('"name"', i)
            if pos == -1:
                break
            colon = arr.find(':', pos)
            if colon == -1:
                break
            # skip spaces
            j = colon+1
            while j < len(arr) and arr[j] in [' ', '\n']:
                j += 1
            if arr[j] == '"':
                start = j+1
                end = start
                while end < len(arr) and arr[end] != '"':
                    if arr[end] == '\\' and end+1 < len(arr):
                        end += 2
                    else:
                        end += 1
                names.append(arr[start:end])
                i = end+1
            else:
                i = j+1
        return names

    title = extract_key_value(json_string, 'title')
    director = extract_key_value(json_string, 'director')
    cast = extract_cast_names(json_string)
    return title, director, cast

