```py
def dfs(index, target, dp, coins):
    if dp[index][target] != -1:
        return dp[index][target]
    if target == 0:
        return 1
    if index == 0:
        return 0
    res = 0
    for q in range(min(coins[index], target//index) + 1):
        res += dfs(index - 1, target - index*q, dp, coins)
    dp[index][target] = res
    return res

def coin_combinations2(coins, total):
    M = len(coins)
    dp = [[-1]*(total + 1) for _ in range(M + 1)]
    return dfs(M, total, dp, coins)

