def sortedArrayToBST(nums):
    if not nums:
        return None
    stack = []
    root = None
    stack.append((0, len(nums)-1, None, None, None)) # (left, right, parent, is_left, node)
    nodes = {}
    while stack:
        left, right, parent, is_left, node_id = stack.pop()
        if left > right:
            continue
        mid = (left + right) // 2
        node = TreeNode(nums[mid])
        nodes[mid] = node
        if parent is not None:
            if is_left:
                parent.left = node
            else:
                parent.right = node
        else:
            root = node
        stack.append((mid+1, right, node, False, None))
        stack.append((left, mid-1, node, True, None))
    return root

def preorder(root, res):
    if not root:
        return
    res.append(str(root.val))
    preorder(root.left, res)
    preorder(root.right, res)

