from typing import List, Tuple

def candyCrush(board: List[List[int]]) -> Tuple[List[List[int]], int]:
    """
    Simulates the Candy Crush elimination process on a 2-D board.

    Parameters
    ----------
    board : List[List[int]]
        m x n matrix where positive integers represent candy types and `0`
        represents an empty cell.

    Returns
    -------
    Tuple[List[List[int]], int]
        A tuple containing the stable board after no more candies can be
        crushed and the total number of candies that were crushed
        throughout the simulation.
    """

    if not board or not board[0]:
        return board, 0  # empty board edge-case

    m, n = len(board), len(board[0])
    total_crushed = 0

    while True:
        # 1) Find all candies that should be crushed
        crush = [[False] * n for _ in range(m)]

        # Horizontal check
        for i in range(m):
            for j in range(n - 2):
                val = board[i][j]
                if val != 0 and val == board[i][j + 1] == board[i][j + 2]:
                    crush[i][j] = crush[i][j + 1] = crush[i][j + 2] = True

        # Vertical check
        for j in range(n):
            for i in range(m - 2):
                val = board[i][j]
                if val != 0 and val == board[i + 1][j] == board[i + 2][j]:
                    crush[i][j] = crush[i + 1][j] = crush[i + 2][j] = True

        # Count how many we are going to crush this round
        crushed_this_round = sum(crush[i][j] for i in range(m) for j in range(n))
        if crushed_this_round == 0:
            break  # Board is stable

        total_crushed += crushed_this_round

        # 2) Set crushed positions to 0
        for i in range(m):
            for j in range(n):
                if crush[i][j]:
                    board[i][j] = 0

        # 3) Apply gravity column by column
        for j in range(n):
            write_row = m - 1  # position where we will write the next non-zero value
            for i in range(m - 1, -1, -1):
                if board[i][j] != 0:
                    board[write_row][j] = board[i][j]
                    write_row -= 1
            # fill the rest of the column with zeros
