class Observer:
    def __init__(self):
        self.count = 0

    def update(self, action):
        if action == "changed":
            self.count += 1

class Persona:
    def __init__(self):
        self._pseudonym = None
        self._observers = [Observer()]

    @property
    def pseudonym(self):
        return self._pseudonym

    @pseudonym.setter
    def pseudonym(self, value):
        for observer in self._observers:
            if observer.count < 3:
                self._pseudonym = value
                observer.update("changed")
                print(f"Pseudonym changed to {value}. This is change number {observer.count}.")
            else:
                print(f"Pseudonym cannot be changed more than three times. Current pseudonym is {self._pseudonym}.")


