def sort_by_frequency(s):
    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    order = []
    recorded = set()
    for char in s:
        if char not in recorded:
            order.append(char)
            recorded.add(char)
    # Get pairs of (char, frequency, original_order)
    char_info = []
    for idx, char in enumerate(order):
        char_info.append((char, frequency[char], idx))
    # Manual sorting (since we avoid built-ins for sorting): selection sort
    for i in range(len(char_info)):
        max_idx = i
        for j in range(i+1, len(char_info)):
            # Higher frequency first, for ties original order
            if char_info[j][1] > char_info[max_idx][1] or (char_info[j][1] == char_info[max_idx][1] and char_info[j][2] < char_info[max_idx][2]):
                max_idx = j
        char_info[i], char_info[max_idx] = char_info[max_idx], char_info[i]
    sorted_string = ''
    for char, freq, _ in char_info:
        sorted_string += char * freq
    return sorted_string

def generate_permutations(s, path, used, res):
    if len(path) == len(s):
        res.append(''.join(path))
        return
    for i in range(len(s)):
        if used[i]:
            continue
        # Skip duplicates
        skip = False
        for j in range(i):
            if s[j] == s[i] and not used[j]:
                skip = True
                break
        if skip:
            continue
        used[i] = True
        path.append(s[i])
        generate_permutations(s, path, used, res)
        path.pop()
        used[i] = False

def main():
