        def validate_isbn(self):
            isbn_10_regex = r'^(?:\d{9}X|\d{10})$'
            isbn_13_regex = r'^(?:\d{13})$'
            if re.match(isbn_10_regex, self.isbn):
                return self._validate_isbn_10()
            elif re.match(isbn_13_regex, self.isbn):
                return self._validate_isbn_13()
            else:
                return False

        def _validate_isbn_10(self):
            total = 0
            for i in range(9):
                total += int(self.isbn[i]) * (10 - i)
            if self.isbn[9].upper() == 'X':
                total += 10
            elif self.isbn[9].isdigit():
                total += int(self.isbn[9])
            else:
                return False
            return total % 11 == 0

        def _validate_isbn_13(self):
            total = 0
            for i in range(13):
                if i % 2 == 0:
                    total += int(self.isbn[i])
                else:
                    total += int(self.isbn[i]) * 3
            return total % 10 == 0

    book = Book(title, author, isbn)
    if book.validate_isbn():
        print('Valid')
    else:
