def build_tree_from_level_order(data):
    if not data or data[0] == '':
        return None
    values = data.split()
    if not values:
        return None
    root_val = values.pop(0)
    if root_val == 'null':
        return None
    root = TreeNode(int(root_val))
    queue = [root]
    while queue and values:
        node = queue.pop(0)
        if values:
            left_val = values.pop(0)
            if left_val != 'null':
                node.left = TreeNode(int(left_val))
                queue.append(node.left)
        if values:
            right_val = values.pop(0)
            if right_val != 'null':
                node.right = TreeNode(int(right_val))
                queue.append(node.right)
    return root

def tree_to_doubly_linked_list(root):
    if not root:
        return None
    prev = None
    head = None
    def in_order(node):
        nonlocal prev, head
        if not node:
            return
        in_order(node.left)
        new_node = DoublyLinkedListNode(node.val)
        if not prev:
            head = new_node
        else:
            prev.next = new_node
            new_node.prev = prev
        prev = new_node
        in_order(node.right)
    in_order(root)
    return head

