```python
def palindrome_check(num):
    return str(num) == str(num)[::-1]

def find_max_palindrome(seq):
    max_palindrome = -1
    max_indices = []
    for index, value in enumerate(seq):
        if palindrome_check(value) and value > max_palindrome:
            max_palindrome = value
            max_indices = [index]
        elif palindrome_check(value) and value == max_palindrome:
            max_indices.append(index)
    return max_palindrome, max_indices

def find_all_max_palindrome(seq, cur_max=-1, cur_indices=[], cur_index=0):
    if cur_index == len(seq):
        return cur_max, cur_indices
    else:
        if palindrome_check(seq[cur_index]):
            if seq[cur_index] > cur_max:
                return find_all_max_palindrome(seq, seq[cur_index], [cur_index], cur_index+1)
            elif seq[cur_index] == cur_max:
                cur_indices.append(cur_index)
        return find_all_max_palindrome(seq, cur_max, cur_indices, cur_index+1)

