from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(values):
    if not values or values[0] == 'null':
        return None
    root = TreeNode(int(values[0]))
    queue = deque([root])
    i = 1
    while queue and i < len(values):
        current = queue.popleft()
        if i < len(values):
            if values[i] != 'null':
                current.left = TreeNode(int(values[i]))
                queue.append(current.left)
            i += 1
        if i < len(values):
            if values[i] != 'null':
                current.right = TreeNode(int(values[i]))
                queue.append(current.right)
            i += 1
    return root

def trees_identical_and_inorder(t1, t2):
    # Structural identical (non-recursive)
    stack1 = [t1]
    stack2 = [t2]
    while stack1 and stack2:
        n1 = stack1.pop()
        n2 = stack2.pop()
        if not n1 and not n2:
            continue
        if (not n1) or (not n2) or (n1.val != n2.val):
            return False
        stack1.append(n1.right)
        stack1.append(n1.left)
        stack2.append(n2.right)
        stack2.append(n2.left)
    if stack1 or stack2:
        return False
    # In-order traversal identical (iterative)
    def inorder(root):
        stack = []
        res = []
        while stack or root:
            while root:
                stack.append(root)
                root = root.left
            node = stack.pop()
            res.append(node.val)
            root = node.right
        return res
    return inorder(t1) == inorder(t2)

