If numbers are complex, we will use the class `Complex` which includes methods for arithmetic operations on complex numbers.

```Java
import java.util.Arrays;

class ComplexNumber {
    double real, img;
    ComplexNumber(double real, double img) {
        this.real = real;
        this.img = img;
    }

    static ComplexNumber multiply(ComplexNumber c1, ComplexNumber c2) {
        double real = c1.real * c2.real - c1.img * c2.img;
        double img = c1.real * c2.img + c1.img * c2.real;
        return new ComplexNumber(real, img);
    }

    public String toString() {
        return "("+real+" + "+img+"i)";
    }
}

public class Main {
    private static final int MATRIX_SIZE = 10;

    static void complexMultiplicationMatrix() {
        ComplexNumber[][] cmatrix = new ComplexNumber[MATRIX_SIZE][MATRIX_SIZE];
        for (int i = 0; i < MATRIX_SIZE; i++) {
            for (int j = 0; j < MATRIX_SIZE; j++) {
                cmatrix[i][j] = ComplexNumber.multiply(new ComplexNumber(i+1, 0), new ComplexNumber(j+1, 0));
                System.out.print(cmatrix[i][j] + " ");
            }
            System.out.println();
        }
    }

    static void transpose(int matrix[][]) {
        System.out.println("\nTranspose Matrix: ");
        for (int i = 0; i < MATRIX_SIZE; i++) {
            for (int j = 0; j < MATRIX_SIZE; j++) {
                System.out.print(matrix[j][i] + " ");
            }
            System.out.println();
        }
    }

    static void buildMultiplicationMatrix() {
        int matrix[][] = new int[MATRIX_SIZE][MATRIX_SIZE];
        for (int i = 0; i < MATRIX_SIZE; i++) {
            for (int j = 0; j < MATRIX_SIZE; j++) {
                matrix[i][j] = (i+1)*(j+1);
                System.out.print(matrix[i][j] + " ");
            }
            System.out.println();
        }
        transpose(matrix);
    }

    public static void main(String[] args) {
        System.out.println("Multiplication Matrix: ");
        buildMultiplicationMatrix();
        System.out.println("\nComplex Number Multiplication Matrix: ");
        complexMultiplicationMatrix();
    }
}
