from collections import deque
from typing import List

def modify_deque(operations: List[str]) -> List[str]:
    """
    Simulate a deque with the given list of operations.

    Each operation is one of:
        - "push_front X": add X to the front
        - "push_back X":  add X to the back
        - "pop_front":    remove front element (no-op if empty)
        - "pop_back":     remove back element  (no-op if empty)

    The function returns the final contents of the deque as a list,
    in front-to-back order.
    """
    dq = deque()

    for op in operations:
        if op.startswith("push_front"):
            # Extract the value after the first space
            value = op.split(" ", 1)[1]
            dq.appendleft(value)
        elif op.startswith("push_back"):
            value = op.split(" ", 1)[1]
            dq.append(value)
        elif op == "pop_front":
            if dq:
                dq.popleft()
        elif op == "pop_back":
            if dq:
                dq.pop()
        else:
            # If the operation is malformed, you could raise an error or ignore.
            # We'll ignore it here.
            continue

    return list(dq)

