def is_palindrome_input():
    """
    Reads a string from standard input and checks if it is a palindrome, ignoring spaces, punctuation, and capitalization.
    Outputs 'True' if it is a palindrome, 'False' otherwise.
    """

    s = input()

    def is_alphanumeric(c):
        return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9')

    def to_lower(c):
        if 'A' <= c <= 'Z':
            return chr(ord(c) - ord('A') + ord('a'))
        return c

    left = 0
    right = len(s) - 1

    while left < right:
        while left < right and not is_alphanumeric(s[left]):
            left += 1
        while left < right and not is_alphanumeric(s[right]):
            right -= 1
        if left < right:
            if to_lower(s[left]) != to_lower(s[right]):
                print('False')
                return
            left += 1
            right -= 1
    print('True')

