def max_product(arr):
    max1 = max2 = max3 = -float('inf')
    min1 = min2 = float('inf')

    for num in arr:
        # Update max values
        if num > max1:
            max3, max2, max1 = max2, max1, num
        elif num > max2:
            max3, max2 = max2, num
        elif num > max3:
            max3 = num

        # Update min values
        if num < min1:
            min2, min1 = min1, num
        elif num < min2:
            min2 = num

    product1 = max1 * max2 * max3
    product2 = min1 * min2 * max1
    return max(product1, product2)

