class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(nodes):
    if not nodes:
        return None
    tree_nodes = [TreeNode(val=node[0]) for node in nodes]
    for i, (val, left_idx, right_idx) in enumerate(nodes):
        if left_idx != -1:
            tree_nodes[i].left = tree_nodes[left_idx]
        if right_idx != -1:
            tree_nodes[i].right = tree_nodes[right_idx]
    return tree_nodes[0]

def is_bst(root):
    prev = None
    current = root
    while current:
        if current.left is None:
            if prev and prev.val >= current.val:
                return False
            prev = current
            current = current.right
        else:
            pre = current.left
            while pre.right and pre.right != current:
                pre = pre.right
            if pre.right is None:
                pre.right = current
                current = current.left
            else:
                pre.right = None
                if prev and prev.val >= current.val:
                    return False
                prev = current
                current = current.right
    return True

