    cache = OrderedDict()
    last3gets = deque(maxlen=3)
    for line in lines[1:]:
        if not line.strip():
            continue
        parts = line.split()
        if parts[0] == 'put':
            key = int(parts[1])
            value = parts[2]
            if key in cache:
                curr_value = cache[key]
                # Check if update conditions apply
                if value > curr_value and key not in last3gets:
                    # Move to the end (most-recently used)
                    cache.move_to_end(key)
                cache[key] = value
            else:
                if len(cache) >= N:
                    cache.popitem(last=False)  # Pop least-recently used
                cache[key] = value
        elif parts[0] == 'get':
            key = int(parts[1])
            if key in cache:
