import sys
import random

def read_grid():
    grid = []
    for _ in range(20):
        line = input().strip()
        grid.append([int(c) for c in line])
    return grid

def live_neighbors(grid, i, j):
    n = 20
    count = 0
    for di in [-1,0,1]:
        for dj in [-1,0,1]:
            if di == 0 and dj == 0:
                continue
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                count += grid[ni][nj]
    return count

def print_grid(grid):
    for row in grid:
        print(''.join(str(c) for c in row))

def main():
    N = int(input())
    grid = read_grid()
    random.seed(42)  # for test reproducibility
    for gen in range(1, N+1):
        # Random event: 10% chance to toggle one random cell
        if random.random() < 0.1:
            ri = random.randint(0,19)
            rj = random.randint(0,19)
            grid[ri][rj] = 1 - grid[ri][rj]
        next_grid = [row[:] for row in grid]
        for i in range(20):
            for j in range(20):
                ln = live_neighbors(grid, i, j)
                if grid[i][j]==1 and ln == 2:
