import ast

def flatten_dict(d, parent_key='', sep='^'):
    items = []
    def _flatten(x, key, parent_key, sep):
        if isinstance(x, dict):
            for k, v in x.items():
                new_key = (key + sep + k) if key else k
                _flatten(v, new_key, '', sep)
        elif isinstance(x, (list, tuple)):
            for i, v in enumerate(list(x)):
                new_key = f"{key}<{i}>" if key else f"<{i}>"
                _flatten(v, new_key, '', sep)
        elif isinstance(x, set):
            sorted_list = sorted(x)
            for i, v in enumerate(sorted_list):
                new_key = f"{key}{{{i}}}" if key else f"{{{i}}}"
                _flatten(v, new_key, '', sep)
        else:
            items.append((key, x))
    _flatten(d, parent_key, '', sep)
    return dict(items)

