class HashTable:
    def __init__(self, size=101):
        self.size = size
        self.slots = [None] * size
        self.data = [None] * size

    def hash_function(self, key):
        return key % self.size

    def rehash(self, old_hash, i):
        # Quadratic probing: (hash_value + i^2) % size
        return (old_hash + i * i) % self.size

    def put(self, key, value):
        hash_value = self.hash_function(key)
        i = 0
        slot = hash_value
        while self.slots[slot] is not None and self.slots[slot] != key:
            i += 1
            slot = self.rehash(hash_value, i)
        self.slots[slot] = key
        self.data[slot] = value

    def get(self, key):
        hash_value = self.hash_function(key)
        i = 0
        slot = hash_value
        probes = 0
        while self.slots[slot] is not None:
            if self.slots[slot] == key:
                return self.data[slot]
            i += 1
            slot = self.rehash(hash_value, i)
            probes += 1
            if probes > self.size:
                break
        return None

def fibonacci(n, memo=None):
    if memo is None:
        # To store up to at least n values, size much larger than n. E.g. n+10
        memo = HashTable(size=max(101, n*2+1))
    if n < 0:
        raise ValueError("Fibonacci number is not defined for negative numbers")
    if n == 0:
        return 0
    if n == 1:
        return 1
    cached = memo.get(n)
    if cached is not None:
        return cached
    result = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    memo.put(n, result)
    return result

def main():
    n = int(input())
    print(fibonacci(n))

