```go
import (
    "strings"
    "unicode"
)

func CountDistinctCharacters(str string) int {
    distinctChars := map[rune]bool{}

    for _, char := range strings.ToLower(str) {
        if unicode.IsLetter(char) {
            distinctChars[char] = true
        }
    }

    return len(distinctChars)
}
