class Calculator:
    def __init__(self, *numbers):
        if not numbers:
            raise ValueError("At least one number is required")
        self.numbers = numbers

    def add(self):
        return sum(self.numbers)

    def subtract(self):
        result = self.numbers[0]
        for num in self.numbers[1:]:
            result -= num
        return result

    def multiply(self):
        result = 1
        for num in self.numbers:
