import sys
import re

class Book:
    def __init__(self, title, author, isbn, ddc):
        self.title = title
        self.author = author
        self.isbn = isbn
        self.ddc = ddc

class Library:
    def __init__(self):
        self.books = []
        self.isbn_set = set()
        self.ddc_set = set()

    def add_book(self, title, author, isbn, ddc):
        if not self._is_valid_isbn(isbn):
            print("Invalid ISBN format.")
            return
        if not self._is_valid_ddc(ddc):
            print("Invalid DDC format.")
            return
        if isbn in self.isbn_set:
            print("ISBN number must be unique.")
            return
        if ddc in self.ddc_set:
            print("DDC number must be unique.")
            return
        book = Book(title, author, isbn, ddc)
        self.books.append(book)
        self.isbn_set.add(isbn)
        self.ddc_set.add(ddc)
        print("Book added.")

    def remove_book(self, isbn):
        for book in self.books:
            if book.isbn == isbn:
                self.books.remove(book)
                self.isbn_set.remove(isbn)
                self.ddc_set.remove(book.ddc)
                print(f"Book with ISBN '{isbn}' removed.")
                return
        print(f"No book found with ISBN '{isbn}'.")

    def list_all_books(self):
        for book in self.books:
            print(f"{book.title} | {book.author} | {book.isbn} | {book.ddc}")

    def _is_valid_isbn(self, isbn):
        pattern = r'^\d{3}-?\d{1,5}-?\d{1,7}-?\d{1,7}-?[\dxX]$'
        return bool(re.match(pattern, isbn))

    def _is_valid_ddc(self, ddc):
        pattern = r'^\d\.\d{2}(\.\d{1,6})?$'
        return bool(re.match(pattern, ddc))


