```python
def headline(title):
    small_words = {'the', 'a', 'and', 'in', 'an', 'or', 'at', 'by', 'to'}
    words = title.split()
    for i in range(len(words)):
        if i == 0 or i == len(words)-1 or words[i] not in small_words:
            words[i] = words[i].capitalize() 
    return ' '.join(words)

