def bitwise_sum(a, b):
    while b != 0:
        carry = a & b
        carry = carry << 1
        a = a ^ b
        b = carry
    return a

def bitwise_difference(a, b):
    while b != 0:
        borrow = (~a) & b
        borrow = borrow << 1
        a = a ^ b
        b = borrow
    return a

def bitwise_left_shift(a, n):
    return a << n

def bitwise_right_shift(a, n):
    return a >> n

def binary_search(arr, target):
    left = 0
    right = bitwise_difference(len(arr), 1)
    while left <= right:
        mid = bitwise_sum(left, bitwise_right_shift(bitwise_difference(right, left), 1))
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = bitwise_sum(mid, 1)
        else:
            right = bitwise_difference(mid, 1)
    return -1

def main():
