class Calculator:
    @staticmethod
    def Add(a, b):
        # bitwise addition for 32-bit signed values
        MAX = 0x7FFFFFFF
        MIN = 0x80000000
        mask = 0xFFFFFFFF
        while b:
            carry = (a & b) & mask
            a = (a ^ b) & mask
            b = (carry << 1) & mask
        if a & MIN:
            return ~((~a) & mask)
        return a

    @staticmethod
    def Subtract(a, b):
        # a - b = a + (~b + 1)
        return Calculator.Add(a, Calculator.Add(~b, 1))

    @staticmethod
    def Multiply(a, b):
        result = 0
        negative = (a < 0) != (b < 0)
        a = abs(a)
        b = abs(b)
        while b:
            if b & 1:
                result = Calculator.Add(result, a)
            a <<= 1
            b >>= 1
        return Calculator.Subtract(0, result) if negative else result

    @staticmethod
    def Divide(a, b):
        if b == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        negative = (a < 0) != (b < 0)
        a = abs(a)
        b = abs(b)
        quotient = 0
        temp = 0
        for i in reversed(range(32)):
            if (temp + (b << i)) <= a:
                temp = Calculator.Add(temp, b << i)
                quotient = Calculator.Add(quotient, 1 << i)
        return Calculator.Subtract(0, quotient) if negative else quotient

