import sys

def optimal_coins(coins, limit):
    """Min-coin DP up to and including limit."""
    INF = 10 ** 9
    dp = [INF] * (limit + 1)
    dp[0] = 0
    for v in range(1, limit + 1):
        for c in coins:
            if c > v:
                break
            if dp[v - c] + 1 < dp[v]:
                dp[v] = dp[v - c] + 1
    return dp

def main():
    case_no = 0
    for line in sys.stdin.read().splitlines():
        line = line.strip()
        if not line:
            continue
        if line == '0':
            break
        nums = list(map(int, line.split()))
        n, coins = nums[0], nums[1:]
        case_no += 1

        # 1) existence of unreachable amounts
        if coins[0] != 1:
            print(f"Case #{case_no}: Cannot pay some amount")
            continue

        # 2) test greedy optimality up to cn + c(n-1)
        limit = coins[-1] + (coins[-2] if len(coins) >= 2 else 0)
        dp = optimal_coins(coins, limit)

        greedy_ok = True
        for m in range(1, limit + 1):
            rem = m
            greedy_cnt = 0
            for c in reversed(coins):
                if rem == 0:
                    break
                if rem >= c:
                    q, rem = divmod(rem, c)
                    greedy_cnt += q
            if dp[m] < greedy_cnt:
                greedy_ok = False
                break

        if greedy_ok:
            print(f"Case #{case_no}: OK")
        else:
            print(f"Case #{case_no}: Cannot use greedy algorithm")

