import ast

def convert_to_tuple(node):
    if isinstance(node, dict):
        # If this dict is of form {'root': {...}}
        if len(node) == 1 and 'root' in node:
            return convert_to_tuple(node['root'])
        value = node.get('value', None)
        left = convert_to_tuple(node.get('left', None))
        right = convert_to_tuple(node.get('right', None))
        if value is None:
            value = 0  # default, e.g. for root node
        return (value, left, right)
    elif isinstance(node, tuple):
        value, left, right = node
        return (value, convert_to_tuple(left), convert_to_tuple(right))
    else:
        return node

def level_order_traversal(tree):
    if not isinstance(tree, tuple):
        tree = convert_to_tuple(tree)
    result = []
    if not tree:
        return result
    queue = [tree]
    while queue:
        current = queue.pop(0)
        if not isinstance(current, tuple):
            continue
        value, left, right = current
        if value is not None:
            result.append(value)
        if left is not None:
            queue.append(left)
        if right is not None:
            queue.append(right)
    return result

def main():
