    def sort_key(x):
        # Sorting by price descending, then Levenshtein from "product" reverse (i.e., negative distance)
        return (-x['price'], -levenshtein(x['name'], "product"))
    output = sorted(filtered, key=sort_key)
    print(json.dumps(output))

