    }

    func noMoreThanTwoConsecutiveNumbers() -> Bool {
        return fileName.range(of: #"(\d{3,})"#, options: .regularExpression) == nil
    }

    func wordsSeparatedBySpecificDelimiters() -> Bool {
        return fileName.range(of: #"[\w-]+([\._][\w-]+)*"#, options: .regularExpression) != nil
    }

    func hasCorrectPeriodPlacement() -> Bool {
        let splitFile = fileName.split(separator: ".")
        return splitFile.count > 1 && !splitFile.contains("")
    }

    func acceptableLength() -> Bool {
        return 4 <= fileName.count && fileName.count <= 100
    }

    func acceptableFileExtension() -> Bool {
        let extensions = ["txt", "exe", "dll", "pdf", "jpeg", "cpp", "java","python"]
