def flatten_dict(d, parent_key='', sep='.'): 
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        elif isinstance(v, list):
            for i, elem in enumerate(v):
                # For lists, append the index as another level in the key
                combined_key = f"{new_key}.{i}"
                if isinstance(elem, dict):
                    items.extend(flatten_dict(elem, combined_key, sep=sep).items())
                elif isinstance(elem, list):
                    # Nested list: flatten recursively
                    # We'll treat the nested list as a value of combined_key, so call flatten_dict with a fake key
                    fake_dict = {str(i): elem}
                    items.extend(flatten_dict(fake_dict, new_key, sep=sep).items())
                else:
                    items.append((combined_key, elem))
        else:
            items.append((new_key, v))
    return dict(items)

