class HashMap:
    def __init__(self):
        self._store = {}
    def get(self, key, default=None):
        return self._store.get(key, default)
    def __setitem__(self, key, value):
        self._store[key] = value

def fibonacci(n, memo=None):
    if memo is None:
        memo = HashMap()
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    fib_n_minus_1 = memo.get(n - 1)
    if fib_n_minus_1 is None:
        fib_n_minus_1 = fibonacci(n - 1, memo)
        memo[n - 1] = fib_n_minus_1
    fib_n_minus_2 = memo.get(n - 2)
    if fib_n_minus_2 is None:
        fib_n_minus_2 = fibonacci(n - 2, memo)
        memo[n - 2] = fib_n_minus_2
    return fib_n_minus_1 + fib_n_minus_2

