def partition(arr, low, high):
    pivot_index = low
    pivot_value = arr[pivot_index]
    while low < high:
        while low < high and arr[high] <= pivot_value:
            high -= 1
        arr[low] = arr[high]
        while low < high and arr[low] >= pivot_value:
            low += 1
        arr[high] = arr[low]
    arr[low] = pivot_value
    return low

def quickselect(arr, low, high, k):
    if low == high:
        return arr[low]
    pivot_index = partition(arr, low, high)
    if k == pivot_index:
        return arr[k]
    elif k < pivot_index:
        return quickselect(arr, low, pivot_index - 1, k)
    else:
        return quickselect(arr, pivot_index + 1, high, k)

def get_unique(arr):
    unique_arr = []
    for num in arr:
        if num not in unique_arr:
            unique_arr.append(num)
    return unique_arr

def main():
    import sys
    line = sys.stdin.readline()
    arr = list(map(int, line.strip().split()))
    unique_arr = get_unique(arr)
    if len(unique_arr) < 3:
        print("List must contain at least three unique values")
        return
    n = len(unique_arr)
    # Find largest
    first_largest = quickselect(unique_arr, 0, n - 1, 0)
    unique_arr.remove(first_largest)
    # Find second largest
    second_largest = quickselect(unique_arr, 0, n - 2, 0)
    unique_arr.remove(second_largest)
    # Find third largest
    third_largest = quickselect(unique_arr, 0, n - 3, 0)
    print(f"{first_largest} {second_largest} {third_largest}")

