import math

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_factors(n):
    result = []
    temp = n
    # Number of times 2 divides n
    if temp % 2 == 0:
        result.append(2)
        while temp % 2 == 0:
            temp = temp // 2
    # n must be odd at this point
    i = 3
    while i * i <= temp:
        if temp % i == 0:
            if i not in result:
                result.append(i)
            while temp % i == 0:
                temp = temp // i
        i += 2
    if temp > 2:
        result.append(temp)
    return result

def is_carmichael(num):
    if is_prime(num):
        return False
    factors = prime_factors(num)
    # Check for square-freeness
    prod = 1
    for p in factors:
        prod *= p
    if prod != num:
        return False
    for p in factors:
        if (num - 1) % (p - 1) != 0:
            return False
    return True

