def unique_array_sets(input):
    if not isinstance(input, list):
        raise TypeError('The input should be a list.')
    result = []
    for item in input:
        if not isinstance(item, list):
            raise TypeError('Each item of the input list should be a list.')
        try:
            unique_item = list(set(item))
            if len(unique_item) == len(item) and unique_item not in result:
                result.append(unique_item)
        except TypeError as e:
            raise TypeError('Each item of the inner list should be an integer. ' + str(e))
    return result

