        self.val = val
        self.left = None
        self.right = None

def main():
    import sys
    sys.setrecursionlimit(2000)
    N = int(input())
    node_info = dict()
    for _ in range(N):
        parts = input().split()
        idx = int(parts[0])
        val = int(parts[1])
        left_idx = int(parts[2])
        right_idx = int(parts[3])
        node_info[idx] = (val, left_idx, right_idx)
    root_line = input().split()
    root_idx = int(root_line[0])
    targetSum = int(root_line[1])
    # Build tree
    nodes = dict()
    for idx in node_info:
        nodes[idx] = TreeNode(node_info[idx][0])
    for idx, (val, lidx, ridx) in node_info.items():
        if lidx != -1:
            nodes[idx].left = nodes[lidx]
        if ridx != -1:
            nodes[idx].right = nodes[ridx]
    root = nodes[root_idx]
    # Find paths
    res = []
    def dfs(node, path, s):
        if not node:
            return
        path.append(node.val)
        s += node.val
        if not node.left and not node.right:
            if s == targetSum:
                res.append(path[:])
        else:
            dfs(node.left, path, s)
            dfs(node.right, path, s)
        path.pop()
    dfs(root, [], 0)
    res.sort()
    for path in res:
        print(' '.join(map(str, path)))

