```

3. And now, for rendering this model in the View, create a HTML helper method that can recursively cycle through your Nodes and create the nested HTML for it:

```csharp
public static MvcHtmlString DisplayTree(this HtmlHelper help, Node root)
{
    var html = string.Empty;

    if (root != null)
    {
        html += "<ul>";
        html += "<li>" + root.Name;

        foreach (Node child in root.Children)
        {
            html += help.DisplayTree(child);
        }

        html += "</li>";
        html += "</ul>";
    }

    return new MvcHtmlString(html);
}
```

4. Finally in your View, call the helper method for your model Root:

```html
<div>
    @Html.DisplayTree(Model.Root)
</div>
