from typing import List, Tuple

def create_schedule_dataset(tasks: List[int]) -> Tuple[List[int], List[int]]:
    """
    Returns the first 20 unique tasks and their indices in the input list.

    If fewer than 20 unique tasks exist, returns ([], []).
    """
    unique_tasks: List[int] = []
    indices: List[int] = []
    seen = set()

    # Iterate through the list once, recording each new task
    for idx, task in enumerate(tasks):
        if task not in seen:
            seen.add(task)
            unique_tasks.append(task)
            indices.append(idx)
            if len(unique_tasks) == 20:
                break  # We have collected enough unique tasks

    # Ensure we have exactly 20 unique tasks; otherwise, return empty lists
    if len(unique_tasks) < 20:
        return ([], [])

    return (unique_tasks, indices)

