    def __init__(self):
        self.last_result = 0
        self.operations_log = []

    def _validate_inputs(self, a, b):
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError("Operands must be integers")

    def _log_operation(self, operation, a, b, result):
        self.operations_log.append(f"{operation} {a} {b} {result}")

    def and_operation(self, a, b):
        self._validate_inputs(a, b)
        self.last_result = a & b
        self._log_operation('AND', a, b, self.last_result)
        return self.last_result

    def or_operation(self, a, b):
        self._validate_inputs(a, b)
        self.last_result = a | b
        self._log_operation('OR', a, b, self.last_result)
        return self.last_result

    def xor_operation(self, a, b):
        self._validate_inputs(a, b)
        self.last_result = a ^ b
        self._log_operation('XOR', a, b, self.last_result)
        return self.last_result

    def is_power_of_two(self):
        return (self.last_result & (self.last_result - 1)) == 0 and self.last_result != 0

