import java.util.Random;
import java.util.ArrayList;
import java.lang.Math;

public class Statistics {
    public static void main(String[] args) {
        Random rand = new Random();
        double[] numArray = new double[100];
        ArrayList<Double> secondArray = new ArrayList<Double>();

        // Step 1: Instantiate an array containing 100 randomized double-precision floating point numerals
        for (int i = 0; i < 100; i++) {
            numArray[i] = rand.nextDouble() * 100;
            // I am multiplying here by 100 to make numbers vary from 0 to 100, else it varies from 0 to 1.
        }

        // Step 2: Compute the mean value of these numerals
        double sum = 0;
        for (double num : numArray) {
            sum += num;
        }
        double mean = sum / numArray.length;
        System.out.println("Mean: " + mean);

        // Step 3: Compute the standard deviation of these numerals based on the previously computed mean
        double squareSum = 0;
        for (double num : numArray) {
            squareSum += Math.pow(num - mean, 2);
        }
        double stdev = Math.sqrt(squareSum / numArray.length);
        System.out.println("Standard Deviation: " + stdev);

        // Step 4: Generate a second array that consists only of the numbers from the initial array that fall within one standard deviation of the mean.
        for (double num : numArray) {
            if (Math.abs(num - mean) <= stdev) {
                secondArray.add(num);
            }
        }
        System.out.println("Elements within one standard deviation of the mean:");
        for (double num : secondArray) {
            System.out.print(num + " ");
        }
    }
}
