Here is a C++ program that implements bubble sort to sort an array in ascending order and checks if the array is already sorted:

```cpp
#include<iostream>
using namespace std;

// Function to check if array is sorted
bool isSorted(int arr[], int size){
    for(int i = 0; i < size - 1; i++){
        if(arr[i] > arr[i + 1]) 
            return false;
    }
    return true;
} 

// Function to sort the array
void sortArray(int arr[], int size) {
    int i, j;
    for (i = 0; i < size-1; i++)       
        for (j = 0; j < size-i-1; j++)
            if (arr[j] > arr[j+1])
                swap(arr[j], arr[j+1]);
}

// Function to print the array
void printArray(int arr[], int size) {
    for(int i = 0; i < size; i++)
        cout << arr[i] << " ";
    cout << endl;
}

int main() {
    int arr[] = {4, 2, 1, 7, 10};
    int size = sizeof(arr)/sizeof(arr[0]);

    if(isSorted(arr, size))
        cout << "Array is already sorted" << endl;
    else {
        sortArray(arr, size);
        printArray(arr, size);
    }

    return 0;
}
```

This program first checks if the array is sorted with the `isSorted` function. If the array is sorted, the program prints "Array is already sorted". If the array is not sorted, the program sorts the array with the `sortArray` function and then prints the sorted array.

The `sortArray` function implements the bubble sort algorithm, which repeatedly steps through the list, compares adjacent elements and swaps them if they are in the wrong order. The pass through the list is repeated until the list is sorted.

