import sys

def main():
    getcontext().prec = 20
    line = sys.stdin.readline()
    tokens = line.strip().split()
    stack = []
    operators = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b,
        '%': lambda a, b: a % b,
        '**': lambda a, b: a ** b,
    }
    i = 0
    n = len(tokens)
    try:
        while i < n:
            token = tokens[i]
            if token == '**':
                if len(stack) < 2:
                    print('Error: Invalid expression.')
                    return
                b = stack.pop()
                a = stack.pop()
                res = a.__pow__(b)
                stack.append(res)
            elif token in operators:
                if len(stack) < 2:
                    print('Error: Invalid expression.')
                    return
                b = stack.pop()
                a = stack.pop()
                res = operators[token](a, b)
                stack.append(res)
            else:
                try:
                    stack.append(Decimal(token))
                except InvalidOperation:
                    print('Error: Invalid expression.')
                    return
            i += 1
