    if not input_str:
        print("None 0")
        return
    arr = [int(x) for x in input_str.split()]
    sorted_arr = quicksort(arr)
    unique_elements = []
    prev = None
    # Traverse from largest to smallest
    i = len(sorted_arr) - 1
    while i >= 0:
        if sorted_arr[i] != prev:
            unique_elements.append(sorted_arr[i])
            prev = sorted_arr[i]
        i -= 1
    unique_count = len(unique_elements)
    if unique_count < 2:
        print("None", unique_count)
    else:
        print(f"{unique_elements[1]} {unique_count}")

