        # If it's followed by a letter, we want to only use the percent variant
        if '%' in grade:
            return int(percent_match.group(1))
        elif re.search(r'[ABCDF][+-]?', grade):
            # Check if the number and the letter are together, e.g., '85 B+'
            num_part = int(percent_match.group(1))
            # Actually, for grades like '85 B+', for this problem, treat as letter grade, not number
            grade_text_part = re.findall(r'[ABCDF][+-]?', grade)
            if grade_text_part:
                base_dict = {'A': 90, 'B': 80, 'C': 70, 'D': 60, 'F': 50}
                letter = grade_text_part[0][0]
                mod = grade_text_part[0][1:] if len(grade_text_part[0]) > 1 else ''
                score = base_dict.get(letter, 0)
                if mod == '+':
                    score += 3
                elif mod == '-':
                    score -= 2
                return score
            else:
                return num_part
        else:
            return int(percent_match.group(1))
    # Letter grade variant
    letter_match = re.search(r'([ABCDF])[ ]*([+-]?)', grade)
    if letter_match:
        base_dict = {'A': 90, 'B': 80, 'C': 70, 'D': 60, 'F': 50}
        letter = letter_match.group(1)
        mod = letter_match.group(2)
        score = base_dict.get(letter, 0)
        if mod == '+':
            score += 3
        elif mod == '-':
            score -= 2
        return score
    return 0

