def is_spam(email):
    import re
    spam_keywords = {'free', 'win', 'winner', 'prize'}
    negation_words = {'not', 'never'}

    # Find quoted sections and non-quoted parts
    # Use regex to find quoted text
    quoted_spans = [(m.start(), m.end()) for m in re.finditer(r'".*?"', email)]
    quoted_indexes = set()
    for s, e in quoted_spans:
        quoted_indexes.update(range(s, e))

    # Build unquoted text by ignoring quoted indices
    unquoted_chars = [email[i] for i in range(len(email)) if i not in quoted_indexes]
    unquoted_text = ''.join(unquoted_chars)

    # Check for spam words in unquoted text
    words = re.findall(r'\b\w+\b', unquoted_text.lower())
    has_spam = any(w in spam_keywords for w in words)
    has_neg = any(w in negation_words for w in words)

    if has_spam:
        # If negation present in the unquoted region, treat as ham
        if has_neg:
            return 'ham'
        else:
            return 'spam'
    else:
        return 'ham'

