    return ".".join(str(random.randint(0, 255)) for _ in range(4))


def _random_mac() -> str:
    """Return a random MAC address in colon-separated hexadecimal notation."""
    return ":".join(f"{random.randint(0, 255):02X}" for _ in range(6))


