class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def insert_at_beginning(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def insert_at_end(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def delete_node(self, key):
        temp = self.head
        if temp is not None:
            if temp.data == key:
                self.head = temp.next
                return
        prev = None
        while temp is not None:
            if temp.data == key:
                break
            prev = temp
            temp = temp.next
        if temp is None:
            return
        prev.next = temp.next

    def display_list(self):
        temp = self.head
        while temp:
            print(temp.data, end=" -> ")
            temp = temp.next
        print("None")

    def find_middle(self):
        slow_ptr = self.head
        fast_ptr = self.head
        if not self.head:
            return None
        while fast_ptr and fast_ptr.next:
            slow_ptr = slow_ptr.next
            fast_ptr = fast_ptr.next.next
        return slow_ptr.data

def main():
    ll = LinkedList()
    while True:
        try:
            line = input()
        except EOFError:
            break
        if line == "exit":
            break
        tokens = line.strip().split()
        if not tokens:
            continue
        cmd = tokens[0]
        if cmd == 'insert_begin' and len(tokens) == 2:
            ll.insert_at_beginning(int(tokens[1]))
        elif cmd == 'insert_end' and len(tokens) == 2:
            ll.insert_at_end(int(tokens[1]))
        elif cmd == 'delete' and len(tokens) == 2:
            ll.delete_node(int(tokens[1]))
        elif cmd == 'display':
            ll.display_list()
        elif cmd == 'middle':
            val = ll.find_middle()
            print(val if val is not None else 'None')

