            and agent.get("OTHERROLE") == "SUBMITTER"
            and agent.get("TYPE") == "INDIVIDUAL"
        ):
            notes = agent.get("notes", [])
            # Normalise to a list of strings
            if isinstance(notes, str):
                notes = [notes]
            for note in notes:
                if isinstance(note, str) and "@" in note:
