In the above code, if `name`, `description`, or `title` is `null`, `undefined` or an empty string, Angular will bind the value that comes after `||` to the element.

However, if you prefer a custom directive, here's one way to do it:

```javascript
app.directive('defaultText', function() {
  return {
    restrict: 'A',
    require: 'ngModel',   // get a hold of NgModelController
    link: function(scope, element, attrs, ngModelCtrl) {
      if (!ngModelCtrl) {
        // do nothing if no ng-model specified
        return;
      }

      ngModelCtrl.$formatters.push(function(val) {
        return val || attrs.defaultText || '';
      });
    }
  };
});
