def is_valid_cover_sizes(sizes: List[int]) -> bool:
    """
    Return True if every size in `sizes` is greater than MIN_CONTENT_LENGTH
    and there are no duplicates; otherwise, return False.
    """
    # Empty list: vacuously satisfies both conditions
    if not sizes:
        return True

    # 1. Check that each size is > MIN_CONTENT_LENGTH
    for size in sizes:
