import sys

def parse_csv(csv_str):
    csv_pattern = re.compile(
        r'''(?:^|,)(?:("(?:[^"\\]|\\.)*")|([^,()]*))''',
        re.VERBOSE
    )

    def parse_field(field):
        f = field.strip()
        if len(f) >= 2 and f[0] == '"' and f[-1] == '"':
            # remove surrounding quotes, unescape quotes
            return f[1:-1].replace('\\"', '"')
        # try to cast to int
        try:
            return int(f)
        except ValueError:
            pass
        return f if f != '' else None

    def tokenize(s):
        tokens = []
        buf = ''
        in_quotes = False
        i = 0
        while i < len(s):
            c = s[i]
            if in_quotes:
                buf += c
                if c == '"':
                    if i + 1 < len(s) and s[i+1] == '"':  # escaped quote
                        buf += '"'
                        i += 1
                    else:
                        in_quotes = False
                i += 1
            elif c == '"':
                buf += c
                in_quotes = True
                i += 1
            elif c == ',':
                tokens.append(buf.strip())
                buf = ''
                i += 1
            elif c == '(' or c == ')':
                if buf.strip() != '':
                    tokens.append(buf.strip())
                tokens.append(c)
                buf = ''
                i += 1
            else:
                buf += c
                i += 1
        if buf.strip() != '':
            tokens.append(buf.strip())
        return tokens

    def create_nested_list(tokens):
        stack = [[]]
        for token in tokens:
            if token == '(': 
                lst = []
                stack[-1].append(lst)
                stack.append(lst)
            elif token == ')':
                stack.pop()
            else:
                val = parse_field(token)
                if val is not None:
                    stack[-1].append(val)
        return stack[0]

    tokens = tokenize(csv_str.strip())
    return create_nested_list(tokens)

