import sys
from collections import deque

class Node:
    __slots__ = ("val", "left", "right")
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree(values):
    if not values or values[0] == 'N':
        return None
    root = Node(int(values[0]))
    q = deque([root])
    i = 1
    n = len(values)
    while q and i < n:
        cur = q.popleft()
        # left child
        if values[i] != 'N':
            cur.left = Node(int(values[i]))
            q.append(cur.left)
        i += 1
        if i >= n:
            break
        # right child
        if values[i] != 'N':
            cur.right = Node(int(values[i]))
            q.append(cur.right)
        i += 1
    return root

def correct_bst(root):
    current = root
    first = second = prev = None
    while current:
        if current.left is None:
            if prev and prev.val > current.val:
                if first is None:
                    first = prev
                second = current
            prev = current
            current = current.right
        else:
            # Morris traversal: find predecessor
            pred = current.left
            while pred.right and pred.right is not current:
                pred = pred.right
            if pred.right is None:
                pred.right = current
                current = current.left
            else:
                pred.right = None
                if prev and prev.val > current.val:
                    if first is None:
                        first = prev
                    second = current
                prev = current
                current = current.right
    if first and second:
        first.val, second.val = second.val, first.val

def inorder(node, out):
    if node:
        inorder(node.left, out)
        out.append(str(node.val))
        inorder(node.right, out)

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    t = int(data[0].strip())
    line_idx = 1
    for _ in range(t):
        # Skip possible empty lines
        while line_idx < len(data) and data[line_idx].strip() == "":
            line_idx += 1
        if line_idx >= len(data):
            break
        values = data[line_idx].strip().split()
        line_idx += 1
        root = build_tree(values)
        correct_bst(root)
        result = []
        inorder(root, result)
        print(" ".join(result))

