    """
    Validate an email address using a finite state machine (FSM).

    Parameters:
    email (str): The email address to validate.

    Returns:
    bool: True if the email is valid, False otherwise.
    """
    # Define states
    START, AT, DOMAIN, DOT, END = 0, 1, 2, 3, 4
    current_state = START

    def transition(state, char):
        if state == START:
            if char.isalnum() or char in "_-":
                return START
            elif char == "@":
                return AT
            else:
                return None
        elif state == AT:
            if char.isalnum():
                return DOMAIN
            else:
                return None
        elif state == DOMAIN:
            if char.isalnum() or char in "-":
                return DOMAIN
            elif char == ".":
                return DOT
            else:
                return None
        elif state == DOT:
            if char.isalnum():
                return DOMAIN
            else:
                return None
        elif state == END:
            return None
        else:
            return None

    for i, char in enumerate(email):
        current_state = transition(current_state, char)
        if current_state is None:
            print(False)
            return

    if current_state not in {DOMAIN, DOT} or email.endswith("."):
        print(False)
        return

    domain_part = email.split('@')[-1]
    if domain_part.count('.') < 1:
        print(False)
        return

    tld = domain_part[domain_part.rfind('.') + 1:]
    if len(tld) < 2 or not tld.isalpha():
        print(False)
        return

    print(True)

