Here's the Rust code for the Python implementation you provided:

```rust
use std::collections::HashMap;

#[derive(Debug)]
struct InsufficientBalanceException;

impl std::fmt::Display for InsufficientBalanceException {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "InsufficientBalanceException")
    }
}

impl std::error::Error for InsufficientBalanceException {}


fn below_zero(operations: HashMap<i32, Vec<(&str, i32)>>, case_insensitive: bool) -> Result<HashMap<&str, &'static str>, Box<dyn std::error::Error>> {
    let mut account_balances: HashMap<i32, i32> = operations.keys().map(|&key| (key, 0)).collect();
    let mut no_negative_balance_accounts = vec![];

    for (&account, ops) in operations.iter() {
        for &(operation, value) in ops {
            let mut operation = operation;
            if case_insensitive {
                operation = &operation.to_lowercase();
            }

            match operation {
                "deposit" => *account_balances.get_mut(&account).unwrap() += value,
                "withdrawal" =>  {
                    let balance = account_balances.get_mut(&account).unwrap();
                    *balance -= value;
                    if *balance < 0 {
                        return Err(Box::new(InsufficientBalanceException));
                    }
                },
                _ => (),
            }

            if let Some(&balance) = account_balances.get(&account) {
                if balance >= 0 {
                    no_negative_balance_accounts.push(account);
                }
            }
        }
    }
    let result: HashMap<&str, &'static str> = no_negative_balance_accounts.iter().map(|&account| (account, "No negative balance")).collect();
    Ok(result)
}
```

