class Library:
    def __init__(self):
        self.available_books = []

    def add_book(self, book_title):
        if book_title not in self.available_books:
            self.available_books.append(book_title)
            print(f"Book '{book_title}' added to the library.")
        else:
            print(f"Book '{book_title}' is already in the library.")

    def check_out_book(self, book_title):
        if book_title in self.available_books:
            self.available_books.remove(book_title)
            print(f"Book '{book_title}' checked out.")
        else:
            print(f"Book '{book_title}' is not available in the library.")

    def return_book(self, book_title):
        self.available_books.append(book_title)
        print(f"Book '{book_title}' returned to the library.")

    def display_books(self):
        if self.available_books:
            print("Available books in the library:")
            for book in self.available_books:
                print(f"- {book}")
        else:
            print("No books are currently available in the library.")

