    val = lst[0]
    node = TreeNode(val)
    node.left = list_to_tree(lst[1]) if len(lst) > 1 else None
    node.right = list_to_tree(lst[2]) if len(lst) > 2 else None
    return node

def serialize(root):
    def preorder(node):
        if node is None:
            return "null,"
        return node.val + "," + preorder(node.left) + preorder(node.right)
    return preorder(root)

def deserialize(data):
    def build_tree(values):
        value = next(values)
        if value == "null":
            return None
        node = TreeNode(value)
        node.left = build_tree(values)
        node.right = build_tree(values)
        return node
    values = iter(data.split(",")[:-1])
    return build_tree(values)

