def is_valid_roman(s):
    # Invalid repeats
    invalid_patterns = ['IIII', 'VV', 'XXXX', 'LL', 'CCCC', 'DD', 'MMMM']
    for pattern in invalid_patterns:
        if pattern in s:
            return False
    # Invalid pairs
    # I can be subtracted from V and X only.
    # X can be subtracted from L and C only.
    # C can be subtracted from D and M only.
    i = 0
    roman_numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    valid_subtractions = {'IV', 'IX', 'XL', 'XC', 'CD', 'CM'}
    while i < len(s):
        if i+1 < len(s):
            a, b = s[i], s[i+1]
            if roman_numerals[a] < roman_numerals[b]:
                # It must be a valid subtractive combination
                if a + b not in valid_subtractions:
                    return False
                i += 2
                continue
        i += 1
    return True

def roman_to_int(s):
    roman_numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    valid_subtractions = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}
    # Filter non-roman chars
    filtered = ''.join(c for c in s if c in roman_numerals)
    if not filtered:
        return 0
    if not is_valid_roman(filtered):
        return None
    total = 0
    i = 0
    while i < len(filtered):
        if i + 1 < len(filtered) and filtered[i:i+2] in valid_subtractions:
            total += valid_subtractions[filtered[i:i+2]]
            i += 2
        else:
            total += roman_numerals[filtered[i]]
            i += 1
    return total

def main():
