def parse_matrix():
    matrix = []
    while True:
        try:
            line = input()
            if line.strip() == '':
                break
            row = []
            for elem in line.strip().split():
                if elem == 'None':
                    row.append(None)
                else:
                    row.append(int(elem))
            matrix.append(row)
        except EOFError:
            break
    return matrix

def main():
    matrix = parse_matrix()
    max_value = float('-inf')
    positions = []
    found = False
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            value = matrix[i][j]
            if value is not None:
                found = True
                if value > max_value:
                    max_value = value
                    positions = [(i, j)]
                elif value == max_value:
                    positions.append((i, j))
    if not found or not positions:
        print('None')
    elif len(positions) == 1:
        print(positions[0])
    else:
        print(positions)

if __name__ == '__main__':
    main()

def main():
    nums = list(map(int, input().split()))
    target = int(input())
    n = len(nums)
    # dp[i][j] = tuple: (min_count, last_idx) for sum j using first i nums
    dp = [ [ (float('inf'), -1) for _ in range(target+1) ] for _ in range(n+1) ]
    from collections import deque
    # Base case: sum 0 achievable with 0 elements
    for i in range(n+1):
        dp[i][0] = (0, -1)

    for i in range(1, n+1):
        for j in range(target+1):
            # Not including nums[i-1]
            if dp[i-1][j][0] < dp[i][j][0]:
                dp[i][j] = dp[i-1][j]
            # Including nums[i-1]
            if j >= nums[i-1]:
                prev = dp[i-1][j-nums[i-1]]
                if prev[0]+1 < dp[i][j][0]:
                    dp[i][j] = (prev[0]+1, i-1)
    min_count, idx = dp[n][target]
    if min_count == float('inf'):
        print('Exists: False')
        print('Subsequence:')
        return
    # Backtrack to find subsequence
    res = deque()
    i, j = n, target
    while j > 0 and i > 0:
        if dp[i][j] == dp[i-1][j]:
            i -= 1
        else:
            res.appendleft(str(nums[i-1]))
            j -= nums[i-1]
            i -= 1
    print('Exists: True')
    print('Subsequence:', ' '.join(res))

if __name__ == '__main__':
    main()

def read_matrix(n, m):
    matrix = []
    for _ in range(n):
        row = list(map(int, input().split()))
        if len(row) != m:
            raise ValueError("All rows must have exactly {} elements.".format(m))
        matrix.append(row)
    return matrix

def main():
    try:
        n_m = input().strip()
        while n_m == '':
            n_m = input().strip()
        n, m = map(int, n_m.split())
        matrix1 = read_matrix(n, m)
        matrix2 = read_matrix(n, m)
        result = []
        for row1, row2 in zip(matrix1, matrix2):
            if len(row1) != len(row2):
                print("Error: Matrices must have the same dimensions.")
                return
            result.append([a + b for a, b in zip(row1, row2)])
        for r in result:
            print(' '.join(map(str, r)))
    except Exception as e:
        print("Error: Matrices must have the same dimensions.")

if __name__ == "__main__":
    main()

class TreeNode:
    def __init__(self, value=0):
        self.value = value
        self.left = None
        self.right = None

def main():
    n = int(input())
    nodes = [None]  # 1-based indexing
    for _ in range(n):
        nodes.append(TreeNode(0))

    vals = []
    children = []
    for i in range(1, n+1):
        v, l, r = map(int, input().split())
        nodes[i].value = v
        children.append((i, l, r))

    for i, l, r in children:
        if l != 0:
            nodes[i].left = nodes[l]
        if r != 0:
            nodes[i].right = nodes[r]

    root = nodes[1] if n > 0 else None

    if not root:
        print()
        return

    queue = []
    result = []
    queue.append(root)
    while queue:
        current = queue.pop(0)
        result.append(str(current.value))
        if current.left:
            queue.append(current.left)
        if current.right:
            queue.append(current.right)
    print(' '.join(result))

if __name__ == "__main__":
    main()
